function xb_on() {
    if (setting('xb_m1', '') !== '1') {   /* bir martalik: Mikrokreditbank va Turonbank ham umumiy ro'yxatga o'tadi */
        $on = array_filter(explode(',', (string)setting('xb_on', '')));
        if (setting('mkb_on', '1') === '1') array_unshift($on, 'mkb'); if (setting('tb_on', '1') === '1') array_unshift($on, 'turon');
        setset('xb_on', implode(',', array_values(array_unique($on)))); setset('xb_m1', '1'); setset('xb_try', '0');
    }
    return array_values(array_filter(explode(',', (string)setting('xb_on', ''))));
}
function xb_st() { $s = json_decode((string)setting('xb_st', '{}'), true); return is_array($s) ? $s : array(); }
function xb_ref() {   /* tekshiruv uchun mo'ljal: Mikrokreditbank/Turonbank o'rtachasi, bo'lmasa rasmiy kurs */
    $v = q("SELECT AVG(buy) FROM rates WHERE cur='USD' AND kind='bank' AND manual=0 AND buy>0 AND (bank LIKE '%ikrokredit%' OR bank LIKE '%uron%')")->fetchColumn();
    if ($v) return (float)$v;
    $o = q("SELECT official FROM rates WHERE cur='USD' AND kind='official' LIMIT 1")->fetchColumn(); return $o ? (float)$o : null;
}
function multi_get($urls, $to = 15) {   /* bir nechta sahifani parallel oladi: url => (matn|null, xato) */
    $mh = curl_multi_init(); $hs = array();
    foreach (array_values(array_unique($urls)) as $u) {
        $c = curl_init($u);
        curl_setopt_array($c, array(CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => $to, CURLOPT_CONNECTTIMEOUT => 8, CURLOPT_FOLLOWLOCATION => 1, CURLOPT_ENCODING => '',
            CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36',
            CURLOPT_HTTPHEADER => array('Accept: text/html,application/json;q=0.9,*/*;q=0.8', 'Accept-Language: uz,ru;q=0.8,en;q=0.6')));
        curl_multi_add_handle($mh, $c); $hs[$u] = $c;
    }
    do { $st = curl_multi_exec($mh, $act); if ($act) curl_multi_select($mh, 0.5); } while ($act && $st === CURLM_OK);
    $out = array();
    foreach ($hs as $u => $c) {
        $b = (string)curl_multi_getcontent($c); $code = (int)curl_getinfo($c, CURLINFO_HTTP_CODE); $err = curl_error($c);
        $out[$u] = $err === '' && $code < 400 && $b !== '' ? array($b, '') : array(null, $err !== '' ? $err : ($code >= 400 ? 'HTTP ' . $code : 'bo\'sh javob'));
        curl_multi_remove_handle($mh, $c); curl_close($c);
    }
    curl_multi_close($mh);
    return $out;
}
function xb_fetch($force = false) {
    $on = xb_on(); if (!$on) return 'tanlanmagan';
    if (!$force && time() - (int)setting('xb_try', '0') < max(5, (int)setting('xb_int', '15')) * 60) return 'kutish';
    setset('xb_try', (string)time()); @set_time_limit(180);
    $L = xb_list(); $st = xb_st(); $ref = xb_ref(); $todo = array(); $last = array(); $ok = 0;
    foreach ($on as $id) if (isset($L[$id])) {   /* oxirgi ishlagan manzil birinchi */
        $us = array_slice($L[$id], 1); if (!empty($st[$id]['src'])) array_unshift($us, $st[$id]['src']);
        $todo[$id] = array_values(array_unique($us));
    }
    for ($pass = 0; $todo && $pass < 4; $pass++) {   /* har bosqichda hamma banklar parallel */
        $want = array(); foreach ($todo as $id => $us) if (isset($us[$pass])) $want[$id] = $us[$pass];
        if (!$want) break;
        $res = multi_get(array_values($want));
        foreach ($want as $id => $u) {
            list($html, $e) = $res[$u];
            $r = $html === null ? null : mkb_parse($html, $ref);
            if (!is_array($r)) { $last[$id] = parse_url($u, PHP_URL_HOST) . ': ' . ($html === null ? $e : 'kurs topilmadi'); continue; }
            save_rate('USD', $L[$id][0], 'bank', $r[0], $r[1], null, $u, 0, date('Y-m-d H:i:s'));
            $st[$id] = array('ok_at' => date('Y-m-d H:i:s'), 'err' => '', 'src' => $u); unset($todo[$id]); $ok++;
        }
    }
    foreach ($todo as $id => $us) $st[$id] = array('ok_at' => isset($st[$id]['ok_at']) ? $st[$id]['ok_at'] : '', 'err' => date('d.m H:i') . ' — ' . mb_substr(isset($last[$id]) ? $last[$id] : 'manba yo\'q', 0, 160), 'src' => isset($st[$id]['src']) ? $st[$id]['src'] : '');
    setset('xb_st', json_encode($st));
    return 'OK ' . $ok . '/' . count($on);
}
function xb_state() {
    $on = xb_on(); $st = xb_st(); $out = array();
    foreach (xb_list() as $id => $b) {
        $r = q("SELECT buy,sell,COALESCE(measured_at,fetched_at) AS at FROM rates WHERE cur='USD' AND kind='bank' AND bank=? LIMIT 1", array($b[0]))->fetch();
        $out[] = array('id' => $id, 'name' => $b[0], 'on' => in_array($id, $on, true), 'rate' => $r ?: null, 'err' => isset($st[$id]['err']) ? $st[$id]['err'] : '');
    }
    return array('list' => $out);
}
function bank_rows() { return q("SELECT cur, bank, buy, sell, manual, COALESCE(measured_at, fetched_at) AS at FROM rates WHERE kind='bank' ORDER BY cur, bank")->fetchAll(); }
function fix_usd($cur, $v) { $v = (float)$v; return ($cur === 'USD' && $v > 0 && $v < 5000) ? $v * 10 : $v; }
function rates_data() {
    global $CUR; $res = array();
    foreach ($CUR as $c => $name) $res[$c] = array('code' => $c, 'name' => $name, 'official' => null, 'banks' => array());
    foreach (q('SELECT * FROM rates ORDER BY bank')->fetchAll() as $r) {
        if (!isset($res[$r['cur']])) continue;
        $stale = strtotime($r['fetched_at']) < time() - STALE_H * 3600 && !$r['manual'];
        if ($r['kind'] !== 'official') { foreach (array('buy', 'sell', 'prev_buy', 'prev_sell') as $k) if ($r[$k] !== null) $r[$k] = fix_usd($r['cur'], $r[$k]); }
        $row = array('bank' => $r['bank'], 'buy' => $r['buy'], 'sell' => $r['sell'], 'dbuy' => $r['prev_buy'] !== null ? round($r['buy'] - $r['prev_buy'], 2) : null,
            'dsell' => $r['prev_sell'] !== null ? round($r['sell'] - $r['prev_sell'], 2) : null, 'src' => $r['manual'] ? 'qo\'lda kiritilgan' : parse_url($r['source'], PHP_URL_HOST), 'at' => $r['measured_at'] ?: $r['fetched_at'], 'stale' => $stale);
        if ($r['kind'] === 'official') { $row['official'] = $r['official'];
            $y = q("SELECT official FROM rate_history WHERE cur=? AND bank=? AND at < CURDATE() ORDER BY at DESC LIMIT 1", array($r['cur'], $r['bank']))->fetchColumn();
            $row['yest'] = $y !== false && $y !== null ? (float)$y : null;
            $base = $r['prev_official'] !== null ? (float)$r['prev_official'] : $row['yest'];
            $row['d'] = $base !== null ? round($r['official'] - $base, 2) : null; $res[$r['cur']]['official'] = $row; }
        else $res[$r['cur']]['banks'][] = $row;
    }
    return array_values($res);
}

/* ---------- AUTENTIFIKATSIYA (Mini App initData imzosi) ---------- */
function auth_user() {
    $raw = isset($_SERVER['HTTP_X_INIT']) ? $_SERVER['HTTP_X_INIT'] : '';
    parse_str($raw, $d);
    if (empty($d['hash']) || empty($d['user']) || empty($d['auth_date']) || time() - (int)$d['auth_date'] > 86400) out(array('ok' => false, 'error' => 'Avtorizatsiya xatosi'), 401);
    $hash = $d['hash']; unset($d['hash']); ksort($d); $parts = array();
    foreach ($d as $k => $v) $parts[] = $k . '=' . $v;
    $calc = hash_hmac('sha256', implode("\n", $parts), hash_hmac('sha256', BOT_TOKEN, 'WebAppData', true));
    if (!hash_equals($calc, $hash)) out(array('ok' => false, 'error' => 'Imzo noto\'g\'ri'), 401);
    $u = json_decode($d['user'], true); $now = date('Y-m-d H:i:s');
    q('INSERT INTO users (id,username,name,created_at,last_seen) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE username=VALUES(username), name=VALUES(name), last_seen=VALUES(last_seen)',
        array($u['id'], isset($u['username']) ? $u['username'] : '', trim($u['first_name'] . ' ' . (isset($u['last_name']) ? $u['last_name'] : '')), $now, $now));
    if (q('SELECT blocked FROM users WHERE id=?', array($u['id']))->fetchColumn()) out(array('ok' => false, 'error' => 'Hisobingiz bloklangan'), 403);
    return $u;
}

