function px_logo(&$rows, $H, $x, $y, $bank) {   /* 48x48 logotipni (x,y) chap-yuqori burchakka chizadi; topilmasa false */
    $d = logo_data(); $k = logo_key($bank); if ($k === '' || !isset($d[$k])) return false;
