function px_tools(&$rows, $W, $H) {
    $meta = gl_meta() + gl2_meta(); $blob = gl_blob() . gl2_blob(); $t = array();
    $t['span'] = function ($y, $x1, $x2, $c) use (&$rows, $W, $H) {
        if ($y < 0 || $y >= $H || $x2 <= $x1) return;
        $x1 = max(0, $x1); $x2 = min($W, $x2); $a = (int)floor($x1); $b = (int)floor($x2);
        $px = function ($i, $cov) use (&$rows, $y, $c, $W) {
            if ($i < 0 || $i >= $W || $cov <= 0) return;
            $o = $i * 3;
            for ($k = 0; $k < 3; $k++) $rows[$y][$o + $k] = chr((int)(ord($rows[$y][$o + $k]) + ($c[$k] - ord($rows[$y][$o + $k])) * $cov));
        };
        if ($a === $b) { $px($a, $x2 - $x1); return; }
        $px($a, 1 - ($x1 - $a));
        $n = $b - ($a + 1);
        if ($n > 0) $rows[$y] = substr_replace($rows[$y], str_repeat(chr($c[0]) . chr($c[1]) . chr($c[2]), $n), ($a + 1) * 3, $n * 3);
        $px($b, $x2 - $b);
    };
    $span = $t['span'];
    $t['rr'] = function ($x, $y, $w, $h, $r, $c1, $c2 = null) use ($span) {
        for ($i = 0; $i < $h; $i++) {
            $in = 0;
            if ($i < $r) { $d = $r - $i - 0.5; $in = $r - sqrt(max(0, $r * $r - $d * $d)); }
            elseif ($i >= $h - $r) { $d = $i - ($h - $r) + 0.5; $in = $r - sqrt(max(0, $r * $r - $d * $d)); }
            if ($c2) { $q = $i / max(1, $h - 1); $cc = array((int)($c1[0] + ($c2[0] - $c1[0]) * $q), (int)($c1[1] + ($c2[1] - $c1[1]) * $q), (int)($c1[2] + ($c2[2] - $c1[2]) * $q)); } else $cc = $c1;
            $span($y + $i, $x + $in, $x + $w - $in, $cc);
        }
    };
    $t['dot'] = function ($cx, $cy, $r, $c) use ($span) {
        for ($yy = (int)floor($cy - $r); $yy <= (int)ceil($cy + $r); $yy++) {
            $dy = $yy + 0.5 - $cy; if (abs($dy) >= $r) continue;
            $h = sqrt($r * $r - $dy * $dy); $span($yy, $cx - $h, $cx + $h, $c);
        }
    };
    $t['tri'] = function ($tx, $ty, $up, $c, $k = 1) use ($span) {
        for ($yy = (int)($ty - 7 * $k); $yy < (int)($ty + 7 * $k); $yy++) {
            $q = $up ? ($yy + 0.5 - ($ty - 7 * $k)) / (14 * $k) : (($ty + 7 * $k) - ($yy + 0.5)) / (14 * $k); $hh = 8 * $k * $q;
            $span($yy, $tx + 8 * $k - $hh, $tx + 8 * $k + $hh, $c);
        }
    };
    $t['T'] = function ($set, $str, $x, $base, $c, $al = 'l') use (&$rows, $meta, $blob, $W, $H) {
        $g = $meta[$set]; $w = 0;
        $chars = preg_split('//u', (string)$str, -1, PREG_SPLIT_NO_EMPTY);
        foreach ($chars as $ch) $w += isset($g[$ch]) ? $g[$ch][0] : $g[' '][0];
        $cx = $al === 'r' ? $x - $w : ($al === 'c' ? $x - $w / 2 : $x);
        $w = 0;
        foreach ($chars as $ch) {
            $gg = isset($g[$ch]) ? $g[$ch] : $g[' '];
            if ($gg[3] > 0) {
                $gx = (int)round($cx + $gg[1]); $gy = (int)round($base + $gg[2]);
                for ($r = 0; $r < $gg[4]; $r++) {
                    $y = $gy + $r; if ($y < 0 || $y >= $H) continue;
                    $seg = substr($blob, $gg[5] + $r * $gg[3], $gg[3]);
                    for ($k = 0; $k < $gg[3]; $k++) {
                        $a = ord($seg[$k]); $px = $gx + $k; if ($a === 0 || $px < 0 || $px >= $W) continue; $o = $px * 3;
                        if ($a === 255) { $rows[$y][$o] = chr($c[0]); $rows[$y][$o + 1] = chr($c[1]); $rows[$y][$o + 2] = chr($c[2]); }
                        else for ($q = 0; $q < 3; $q++) $rows[$y][$o + $q] = chr((int)(ord($rows[$y][$o + $q]) + ($c[$q] - ord($rows[$y][$o + $q])) * $a / 255));
                    }
                }
            }
            $cx += $gg[0]; $w += $gg[0];
        }
        return $w;
    };
    return $t;
}
/* TartibOn pechati: barcha xabar rasmlarining o'ng pastki burchagida rangli «@Tartib⏻n» logotipi */
function px_stamp($t, $right, $bottom) {
    $m = gl_meta() + gl2_meta(); $f = 'IS30';
    $tw = function ($s) use ($m, $f) { $w = 0; foreach (preg_split('//u', $s, -1, PREG_SPLIT_NO_EMPTY) as $ch) $w += isset($m[$f][$ch]) ? $m[$f][$ch][0] : 0; return $w; };
    $navy = array(15, 27, 61); $g1 = array(62, 224, 122); $g2 = array(18, 214, 230);
    $w1 = $tw('@Tartib'); $wn = $tw('n'); $ring = 26; $pad = 20; $h = 54;
    $w = $pad + $w1 + 3 + $ring + 3 + $wn + $pad; $x = $right - $w; $y = $bottom - $h;
    $t['rr']($x - 3, $y - 3, $w + 6, $h + 6, 30, $g1, $g2);   /* rangli chegara */
    $t['rr']($x, $y, $w, $h, 27, array(255, 255, 255));
    $base = $y + 37; $t['T']($f, '@Tartib', $x + $pad, $base, $navy);
    $cx = $x + $pad + $w1 + 3 + $ring / 2; $cy = $base - 11; $r = 10.5;
    $col = function ($yy) use ($g1, $g2, $cy, $r) { $q = max(0, min(1, ($yy - ($cy - $r - 6)) / (2 * $r + 6))); return array((int)($g1[0] + ($g2[0] - $g1[0]) * $q), (int)($g1[1] + ($g2[1] - $g1[1]) * $q), (int)($g1[2] + ($g2[2] - $g1[2]) * $q)); };
    for ($a = 42; $a <= 318; $a += 3) { $px = $cx + $r * sin(deg2rad($a)); $py = $cy - $r * cos(deg2rad($a)); $t['dot']($px, $py, 2.4, $col($py)); }
    for ($yy = $cy - $r - 5; $yy <= $cy - 1; $yy += 1) $t['dot']($cx, $yy, 2.4, $col($yy));
    $t['T']($f, 'n', $cx + $ring / 2 + 3, $base, $col($base - 6));
}
function px_png($rows, $W, $H) {
    $raw = ''; foreach ($rows as $r) $raw .= "\0" . $r;
    if (function_exists('gzcompress')) { $z = gzcompress($raw, 6); }
    else {
        $z = "\x78\x01"; $n = strlen($raw);
        for ($i = 0; $i < $n; $i += 65535) { $ch = substr($raw, $i, 65535); $z .= chr($i + 65535 >= $n ? 1 : 0) . pack('v', strlen($ch)) . pack('v', strlen($ch) ^ 0xFFFF) . $ch; }
        $z .= hash('adler32', $raw, true);
    }
    $chunk = function ($t, $d) { return pack('N', strlen($d)) . $t . $d . pack('N', crc32($t . $d)); };
    return "\x89PNG\r\n\x1a\n" . $chunk('IHDR', pack('NNCCCCC', $W, $H, 8, 2, 0, 0, 0)) . $chunk('IDAT', $z) . $chunk('IEND', '');
}
/* 1-ramka: banklarda dollar kursi — hammasi bitta jadvalda, bank logotiplari bilan. Dizayn: A — oq, B — ko'k, C — qorong'i (admin tanlaydi) */
function card_rows() {
    $D = array();
    foreach (rates_data() as $c) if ($c['code'] === 'USD') foreach ($c['banks'] as $b)
        if ($b['buy'] > 0 && $b['sell'] > 0 && empty($b['stale']) && $b['src'] !== 'qo\'lda kiritilgan') $D[] = array($b['bank'], (float)$b['buy'], (float)$b['sell']);
    usort($D, function ($a, $b) { return $a[1] == $b[1] ? ($a[2] < $b[2] ? -1 : 1) : ($b[1] < $a[1] ? -1 : 1); });
    return $D;
}
function g_logo(&$rows, $H, $x, $y, $bank, $sz) {   /* logotipni sz x sz ga kichraytirib chizadi (blok o'rtachasi) */
    $d = logo_data(); $k = logo_key($bank); if ($k === '' || !isset($d[$k])) return false;
    $raw = gzuncompress(base64_decode($d[$k])); if ($raw === false) return false;
    $x = (int)round($x); $y = (int)round($y); $f = 48 / $sz;
    for ($j = 0; $j < $sz; $j++) {
        $yy = $y + $j; if ($yy < 0 || $yy >= $H) continue; $line = '';
        $sy0 = (int)floor($j * $f); $sy1 = max($sy0 + 1, (int)floor(($j + 1) * $f));
        for ($i = 0; $i < $sz; $i++) {
            $sx0 = (int)floor($i * $f); $sx1 = max($sx0 + 1, (int)floor(($i + 1) * $f)); $r = $g = $b = 0; $n = 0;
            for ($sy = $sy0; $sy < $sy1; $sy++) for ($sx = $sx0; $sx < $sx1; $sx++) { $o = ($sy * 48 + $sx) * 3; $r += ord($raw[$o]); $g += ord($raw[$o + 1]); $b += ord($raw[$o + 2]); $n++; }
            $line .= chr((int)($r / $n)) . chr((int)($g / $n)) . chr((int)($b / $n));
        }
        $rows[$yy] = substr_replace($rows[$yy], $line, $x * 3, $sz * 3);
    }
    return true;
}
function g_short($n) { return strtr($n, array('Orient Finans bank' => 'Orient Finans', 'Milliy bank (NBU)' => 'Milliy bank', "Ipak Yo'li bank" => "Ipak Yo'li")); }
/* C dizayn: ikki ustunli qorong'i kvadrat jadval (Telegram'da xira chetsiz). $W x $H — bank kam bo'lsa balandlik qisqaradi */
function card_grid($D, $bb, $bs, $W, $H, $fn, $fv, $head = 1) {
    $per0 = (int)ceil(count($D) / 2); $H = (int)min($H, 150 + 76 + 40 + $per0 * 104);   /* bank kam — qatorlar 104 px dan oshmaydi */
    $rows = array_fill(0, $H, str_repeat(chr(239) . chr(239) . chr(244), $W)); $t = px_tools($rows, $W, $H); $T = $t['T']; $rr = $t['rr']; $span = $t['span'];
    $gold = array(245, 197, 66); $white = array(255, 255, 255); $mut = array(140, 155, 190); $green = array(74, 222, 128); $red = array(248, 113, 113); $line = array(38, 50, 86);
    $rr(0, 0, $W, $H, 0, array(22, 33, 66), array(10, 16, 36));
    $m = gl_meta() + gl2_meta(); $tw = function ($f, $s) use ($m) { $w = 0; foreach (preg_split('//u', $s, -1, PREG_SPLIT_NO_EMPTY) as $ch) $w += isset($m[$f][$ch]) ? $m[$f][$ch][0] : 0; return $w; };
    $pad = 56; $T('IB58', 'Dollar kursi', $pad, 92, $white);
    $T('IM24', 'Banklarda olish va sotish narxi', $pad + $tw('IB58', 'Dollar kursi') + 28, 70, $mut);
    $T('IM24', 'USD ' . "\xC2\xB7" . ' ' . date('d.m.Y'), $pad + $tw('IB58', 'Dollar kursi') + 28, 100, $gold);
    for ($k = 0; $k < 4; $k++) $span(116 + $k, $pad, $pad + 150, $gold);
    $rx = $W - $pad; $T('IM24', 'Eng arzon sotish: ', $rx - $tw('IS30', n0($bs)) - 6, 100, $mut, 'r'); $T('IS30', n0($bs), $rx, 101, $red, 'r');
    $T('IM24', 'Eng yuqori olish: ', $rx - $tw('IS30', n0($bb)) - 6, 64, $mut, 'r'); $T('IS30', n0($bb), $rx, 65, $green, 'r');
    $top = 150; $foot = 76; $n = count($D); $per = (int)ceil($n / 2); $RH = ($H - $top - $foot - 40) / $per;
    $cw = ($W - 2 * $pad - 40) / 2; $nw = $tw($fv, '11 850');
    $ts = (int)min(60, $RH - 8); $ls = (int)min(48, $ts - 10);
    $avail = $cw - 8 - 2 * $nw - 34 - 30 - 4 - $ts - 14; $mx = 0; foreach ($D as $b) $mx = max($mx, $tw($fn, g_short($b[0])));
    if ($mx > $avail) $fn = 'IS30';   /* bitta rasmda hamma nom bir xil shriftda */
    foreach (array(0, 1) as $col) {
        $x0 = $pad + $col * ($cw + 40); $sellR = $x0 + $cw - 8; $buyR = $sellR - $nw - 34;
        $T('IM24', 'OLISH', $buyR - $nw / 2, $top + 26, $mut, 'c'); $T('IM24', 'SOTISH', $sellR - $nw / 2, $top + 26, $mut, 'c');
        for ($i = 0; $i < $per; $i++) {
            $k = $col * $per + $i; if (!isset($D[$k])) break; $b = $D[$k];
            $y = $top + 40 + $i * $RH; if ($i) $span((int)$y, (int)$x0, (int)($x0 + $cw), $line);
            $cy = $y + $RH / 2; $tx = $x0 + 4;
            $rr($tx, $cy - $ts / 2, $ts, $ts, $ts / 4, $white);
            if (!g_logo($rows, $H, $tx + ($ts - $ls) / 2, $cy - $ls / 2, $b[0], $ls)) { $t['dot']($tx + $ts / 2, $cy, $ls / 2, array(47, 128, 237)); $T('IS30', mb_substr($b[0], 0, 1), $tx + $ts / 2, $cy + 11, $white, 'c'); }
            $name = g_short($b[0]); $fz = $fn;
            $base = $cy + ($fz === 'IB40' ? 14 : 11);
            $T($fz, $name, $tx + $ts + 14, $base, $white);
            $vb = $cy + ($fv === 'IB40' ? 14 : 11);
            $T($fv, n0($b[1]), $buyR, $vb, $b[1] == $bb ? $gold : $green, 'r'); $T($fv, n0($b[2]), $sellR, $vb, $b[2] == $bs ? $gold : $red, 'r');
        }
    }
    $span($top + 40, (int)($pad + $cw + 20), (int)($pad + $cw + 21), $line);
    for ($yy = $top + 10; $yy < $H - $foot - 10; $yy++) $span($yy, (int)($pad + $cw + 19), (int)($pad + $cw + 21), $line);
    px_stamp($t, $W - $pad, $H - 22);
    return px_png($rows, $W, $H);
}
function png_card($style = null) {
    global $CARD_ERR; $CARD_ERR = '';
    $D = card_rows(); if (!$D) { $CARD_ERR = "Banklarda dollar kursi bazada yo'q"; return false; }
    $bb = max(array_map(function ($x) { return $x[1]; }, $D)); $bs = min(array_map(function ($x) { return $x[2]; }, $D));
    $st = $style ?: setting('card_style', 'C'); if (!in_array($st, array('A', 'B', 'C'), true)) $st = 'C';
    if ($st === 'A') return card_A($D, $bb, $bs);
    if ($st === 'C') return card_grid($D, $bb, $bs, 1280, 1280, 'IS30', 'B30');
    return card_B($D, $bb, $bs);
}
function card_tile($t, &$rows, $H, $cx, $cy, $name, $edge = null) {   /* oq plitka + logotip; logotip yo'q bo'lsa — rangli doirada bosh harf */
    if ($edge) $t['rr']($cx - 32, $cy - 32, 64, 64, 16, $edge);
    $t['rr']($cx - 30, $cy - 30, 60, 60, 15, array(255, 255, 255));
