define('DEF_CAP', "O‘zbekiston tijorat banklarida AQSh dollarining sotib olish va sotish kurslari bo‘yicha kunlik ma’lumot\n📌 Ma’lumotlar axborot maqsadida taqdim etiladi.\n#ValyutaKursi #Valyuta #TartibOn");
/* Kanal/guruh egasi yozgan rasm tagidagi matn (bo'sh bo'lsa — admin namunasi). k: a, b, c (namoz), w (ob-havo) */
function owner_cap($owner, $k, $def, $vars = array()) {
    $v = trim((string)setting('ucap_' . $owner . '_' . $k, ''));
    return $v === '' ? $def : mb_substr(strtr($v, $vars), 0, 1024);
}
/* Rasm tagidagi matn: admin paneldan o'zgartiriladi (k = 'a' dollar kartasi, 'b' MB ro'yxati). O'chirilgan bo'lsa bo'sh qaytadi. */
function frame_cap($k) {
    if (setting('cap_' . $k . '_on', '1') !== '1') return '';
    return mb_substr(trim((string)setting('cap_' . $k, DEF_CAP)), 0, 1024);
}
function tg_photo($chat, $png, $cap = '', $ext = 'png', $pm = '', $rm = '') {
    $bd = '----up' . md5(uniqid('', true));
    $body = "--$bd\r\nContent-Disposition: form-data; name=\"chat_id\"\r\n\r\n$chat\r\n";
    if (!empty(quiet_p('sendPhoto', array('chat_id' => $chat))['disable_notification'])) $body .= "--$bd\r\nContent-Disposition: form-data; name=\"disable_notification\"\r\n\r\ntrue\r\n";
    if ($cap !== '') $body .= "--$bd\r\nContent-Disposition: form-data; name=\"caption\"\r\n\r\n$cap\r\n";
    if ($cap !== '' && $pm !== '') $body .= "--$bd\r\nContent-Disposition: form-data; name=\"parse_mode\"\r\n\r\n$pm\r\n";
    if ($rm !== '') $body .= "--$bd\r\nContent-Disposition: form-data; name=\"reply_markup\"\r\n\r\n$rm\r\n";
    $body .= "--$bd\r\nContent-Disposition: form-data; name=\"photo\"; filename=\"kurs." . $ext . "\"\r\nContent-Type: image/" . ($ext === 'jpg' ? 'jpeg' : 'png') . "\r\n\r\n" . $png . "\r\n--$bd--\r\n";
    $c = curl_init('https://api.telegram.org/bot' . BOT_TOKEN . '/sendPhoto');
    curl_setopt_array($c, array(CURLOPT_POST => 1, CURLOPT_POSTFIELDS => $body, CURLOPT_HTTPHEADER => array('Content-Type: multipart/form-data; boundary=' . $bd), CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 60));
    $r = curl_exec($c); curl_close($c);
    return $r ? json_decode($r, true) : array('ok' => false, 'description' => 'tarmoq xatosi');
}
function send_chat($chat, $parts = null) {   /* $parts: array('a','b') — faqat shu ramkalar (null = tanlanganlarning hammasi) */
    global $CARD_ERR;
    $jobs = array();
    if (!empty($chat['send_a']) && ($parts === null || in_array('a', $parts, true))) $jobs[] = array('png_card', 'a');
    if (!$jobs) return 'hech qanday ramka tanlanmagan';
    foreach ($jobs as $jb) {
        $fn = $jb[0]; $png = $fn();
        if ($png === false) return 'rasm yaratilmadi: ' . ($CARD_ERR ?: 'noma\'lum sabab');
        $r = tg_photo($chat['chat_id'], $png, owner_cap(isset($chat['owner']) ? $chat['owner'] : 0, $jb[1], frame_cap($jb[1]), array('{sana}' => date('d.m.Y'))));
        if (empty($r['ok'])) return isset($r['description']) ? $r['description'] : 'yuborilmadi';
        usleep(400000);
    }
    return '';
}
