    $pick = function ($ks) use ($F) { $o = array(); foreach ($ks as $k) $o[$k] = array('t' => $F[$k]); return $o; };
    $lv = function ($a) { $o = array(); foreach ($a as $k => $t) $o[$k] = array('t' => $t); return $o; };
    $M = array();
    for ($g = 1; $g <= 11; $g++) {
        if ($g <= 4) $k = array('matematika', 'ona_tili', 'oqish', 'tabiiy', 'ingliz');
