        else $k = array_merge(array('algebra', 'geometriya', 'ona_tili', 'adabiyot', 'uzb_tarix', 'jahon_tarix', 'biologiya', 'fizika', 'kimyo', 'geografiya', 'informatika', 'ingliz', 'rus'), $g >= 8 ? array('huquq') : array());
        $M[(string)$g] = array('t' => $g . '-sinf', 'k' => $pick($k));
