            'til' => array('t' => 'Til sertifikatlari', 'k' => $lv(array('ielts' => 'IELTS', 'cefr_ingliz' => 'CEFR · ingliz tili', 'cefr_rus' => 'CEFR · rus tili', 'nemis' => 'Nemis tili', 'koreys' => 'Koreys tili (TOPIK)', 'turk' => 'Turk tili'))),
            'malaka' => array('t' => 'Malaka imtihonlari', 'k' => $lv(array('oqituvchi' => "O'qituvchilar attestatsiyasi", 'tibbiyot' => 'Tibbiyot xodimlari', 'buxgalteriya' => 'Buxgalteriya'))))));
    return $T;
}
function quiz_path($path) {   /* yo'l bo'yicha sarlavhalar ro'yxati; noto'g'ri bo'lsa null. Bo'sh yo'l — barcha bo'limlar */
    $path = trim((string)$path, '/'); if ($path === '') return array();
    $n = array('k' => quiz_tree()); $T = array();
    foreach (explode('/', $path) as $p) { if (!isset($n['k'][$p])) return null; $n = $n['k'][$p]; $T[] = $n['t']; }
    return $T;
}
function quiz_leaf($path) { $T = quiz_path($path); if (!$T) return false; $n = array('k' => quiz_tree()); foreach (explode('/', trim($path, '/')) as $p) $n = $n['k'][$p]; return empty($n['k']); }
function quiz_label($path, $short = false) {   /* «🏫 Maktab › 5-sinf › Matematika» yoki qisqa: «5-sinf · Matematika» */
    $T = quiz_path($path); if ($T === null) return ''; if (!$T) return 'Barcha bo\'limlar';
    if ($short) { $T = array_map(function ($x) { return trim(preg_replace('/^[^\p{L}\p{N}]+/u', '', preg_replace('/\s*\(.*\)$/u', '', $x))); }, array_slice($T, -2)); return implode(' · ', $T); }
    return implode(' › ', $T);
}
function quiz_find($s) {   /* CSV: kod (maktab/5/matematika) yoki nom (Maktab > 5-sinf > Matematika) → kod */
    $s = trim((string)$s); if (quiz_leaf(strtolower($s))) return strtolower($s);
    $parts = preg_split('/\s*(?:>|›|»|\\\\|\/)\s*/u', $s, -1, PREG_SPLIT_NO_EMPTY); $n = array('k' => quiz_tree()); $code = array();
    $nm = function ($x) { return preg_replace('/[^\p{L}\p{N}]+/u', '', mb_strtolower(quiz_apos(preg_replace('/\s*\(.*\)$/u', '', $x)), 'UTF-8')); };
    foreach ($parts as $p) {
        $f = null; $pp = $nm($p);
        foreach ($n['k'] as $k => $c) if ($nm($c['t']) === $pp || $k === $pp || $nm($c['t']) === $pp . 'sinf') { $f = $k; break; }
        if ($f === null) return ''; $code[] = $f; $n = $n['k'][$f]; if (empty($n['k'])) break;
    }
    $c = implode('/', $code); return quiz_leaf($c) ? $c : '';
}
function quiz_subj($s) {
    global $QZ_SUBJ; $s = mb_strtolower(trim((string)$s), 'UTF-8');
    foreach ($QZ_SUBJ as $x) if (mb_strtolower($x, 'UTF-8') === $s) return $x;
    return '';
}
function quiz_apos($s) { return str_replace(array('ʻ', 'ʼ', '‘', '’', '`', '´', 'ʹ'), "'", (string)$s); }
/* Javobni solishtirish uchun: kichik harf, tutuq belgilarisiz (O'zbekiston = Ozbekiston), tinish belgilarisiz, ortiqcha bo'sh joysiz, "300 000" = "300000" */
function quiz_norm($s) {
    $s = mb_strtolower(trim(quiz_apos($s)), 'UTF-8');
    $s = preg_replace('/(?<=\d),(?=\d)/u', '.', $s);
    $s = preg_replace("/[^\p{L}\p{N}. ]+/u", ' ', str_replace("'", '', $s));
    $s = preg_replace('/(?<!\d)\.|\.(?!\d)/u', ' ', $s);
    $s = preg_replace('/(?<=\d) (?=\d)/u', '', trim(preg_replace('/\s+/u', ' ', $s)));
    return $s;
}
function quiz_match($text, $ans, $alts) {
    $t = quiz_norm($text); if ($t === '') return false;
    foreach (array_merge(array($ans), explode('|', (string)$alts)) as $a) { $a = quiz_norm($a); if ($a !== '' && $a === $t) return true; }
    return false;
}
/* Javob kataklari. Rejim (quiz_dg=1): SH, CH, O', G' — bitta katak; 0: har bir harf alohida. Tutuq belgisi katak olmaydi. Har so'z alohida guruh. */
function quiz_cells($ans, $dg = null) {
    if ($dg === null) $dg = setting('quiz_dg', '1') === '1';
    $s = mb_strtoupper(quiz_apos(trim((string)$ans)), 'UTF-8');
    $num = (bool)preg_match('/^[\d\s.,]+$/u', $s);
    if ($num) $s = preg_replace('/(?<=\d)\s+(?=\d)/u', '', $s);
    $g = array(); $n = 0;
    foreach (preg_split("/[^\p{L}\p{N}']+/u", $s, -1, PREG_SPLIT_NO_EMPTY) as $w) {
        preg_match_all($dg ? "/SH|CH|O'|G'|[^']/u" : "/[^']/u", $w, $m); $c = count($m[0]);
        if ($c) { $g[] = $c; $n += $c; }
    }
    return array('n' => $n, 'groups' => $g, 'num' => $num);
}
function quiz_boxes($ans) {
    $c = quiz_cells($ans); $b = array();
    foreach ($c['groups'] as $k) $b[] = trim(str_repeat('⬜ ', $k));
    $info = $c['num'] ? '🔢 ' . $c['n'] . ' ta raqam' : '🔤 ' . $c['n'] . ' ta harf' . (count($c['groups']) > 1 ? ', ' . count($c['groups']) . ' ta so\'z' : '');
    return array(implode('     ', $b), $info);
}
function quiz_qtext($q, $sec, $pts) {
    list($box, $info) = quiz_boxes($q['answer']);
    return "🧩 <b>TARTIBON KROSSVORD</b>\n\n📚 " . htmlspecialchars(quiz_label($q['cat'], true)) . "\n\n❓ Savol: " . htmlspecialchars($q['question']) . "\n\n" . $box . "\n" . $info
        . "\n\n⏳ Vaqt: " . $sec . " soniya\n🏆 Birinchi to'g'ri javob: +" . $pts . " ochko\n\nJavobni guruhga yozing!";
}
function quiz_q_save($d, $id = 0) {
    $cat = trim((string)(isset($d['cat']) ? $d['cat'] : ''), '/'); if (!quiz_leaf($cat)) return 'Bo\'limni oxirigacha tanlang (masalan: Maktab › 5-sinf › Matematika)';
    $sub = mb_substr(quiz_label($cat, true), 0, 120);
    $qt = trim((string)(isset($d['question']) ? $d['question'] : '')); $an = trim(preg_replace('/\s+/u', ' ', quiz_apos(isset($d['answer']) ? $d['answer'] : '')));
    if (mb_strlen($qt) < 5 || mb_strlen($qt) > 600) return 'Savol 5–600 belgidan iborat bo\'lsin';
    if ($an === '' || mb_strlen($an) > 60 || quiz_norm($an) === '') return 'Javob 1–60 belgidan iborat bo\'lsin';
    $list = function ($v) { return mb_substr(implode('|', array_filter(array_map('trim', preg_split('/[|\n]/u', quiz_apos($v))), 'strlen')), 0, 1000); };
    $alts = $list(isset($d['alts']) ? $d['alts'] : ''); $opts = $list(isset($d['opts']) ? $d['opts'] : '');
    $note = mb_substr(trim((string)(isset($d['note']) ? $d['note'] : '')), 0, 500); $lv = max(1, min(3, (int)(isset($d['level']) ? $d['level'] : 1)));
    $c = quiz_cells($an); $h = md5(quiz_norm($qt));
    try {
        if ($id) q('UPDATE quiz_questions SET cat=?, subject=?, level=?, question=?, answer=?, alts=?, opts=?, note=?, letters=?, qhash=? WHERE id=?', array($cat, $sub, $lv, $qt, $an, $alts, $opts, $note, $c['n'], $h, (int)$id));
        else q('INSERT INTO quiz_questions (cat,subject,level,question,answer,alts,opts,note,letters,qhash,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)', array($cat, $sub, $lv, $qt, $an, $alts, $opts, $note, $c['n'], $h, time()));
    } catch (PDOException $e) { return $e->getCode() == 23000 ? 'dup' : 'Bazaga yozilmadi'; }
    return '';
}
/* CSV: bo'lim (kod yoki nom); savol; to'g'ri javob; noto'g'ri variantlar (| bilan); izoh; muqobil javoblar (| bilan); daraja (1-3). Ajratgich ; , yoki TAB — o'zi aniqlanadi. UTF-8. */
function quiz_import($csv) {
    $csv = preg_replace('/^\xEF\xBB\xBF/', '', str_replace(array("\r\n", "\r"), "\n", (string)$csv));
    if (!mb_check_encoding($csv, 'UTF-8')) return array('ok' => false, 'error' => 'Fayl UTF-8 kodlashda bo\'lishi kerak (Excel: «CSV UTF-8» sifatida saqlang)');
    $first = (string)strtok($csv, "\n"); $d = ';'; $best = substr_count($first, ';');
    foreach (array(',', "\t") as $c) if (substr_count($first, $c) > $best) { $best = substr_count($first, $c); $d = $c; }
    $fh = fopen('php://temp', 'r+'); fwrite($fh, $csv); rewind($fh);
    $add = 0; $dup = 0; $err = array(); $ln = 0;
    while (($r = fgetcsv($fh, 0, $d)) !== false) {
        $ln++; if (!$r || (count($r) === 1 && trim((string)$r[0]) === '')) continue;
        $r = array_map('trim', $r) + array_fill(0, 7, '');
        if ($ln === 1 && quiz_find($r[0]) === '' && preg_match('/^(bo|fan|kod|bolim|subject|cat)/iu', quiz_apos($r[0]))) continue;   /* sarlavha qatori */
        $cat = quiz_find($r[0]); if ($cat === '') { if (count($err) < 20) $err[] = $ln . '-qator: bo\'lim topilmadi «' . mb_substr($r[0], 0, 40) . '»'; continue; }
        $e = quiz_q_save(array('cat' => $cat, 'question' => $r[1], 'answer' => $r[2], 'opts' => $r[3], 'note' => $r[4], 'alts' => $r[5], 'level' => $r[6] !== '' ? $r[6] : 1));
        if ($e === '') $add++; elseif ($e === 'dup') $dup++; elseif (count($err) < 20) $err[] = $ln . '-qator: ' . $e;
        if ($ln > 5000) { $err[] = 'Bir martada ko\'pi bilan 5000 qator'; break; }
    }
    fclose($fh);
    return array('ok' => true, 'added' => $add, 'dup' => $dup, 'errors' => $err);
}
function quiz_cfg($cid) {
    $s = q('SELECT * FROM quiz_settings WHERE chat_id=?', array($cid))->fetch();
    $s = $s ? $s : array('chat_id' => $cid, 'enabled' => 0, 'subject' => '', 'cat' => '', 'interval_min' => 10, 'answer_sec' => 60, 'points' => 10, 'next_at' => 0, 'last_err' => '', 'mode' => 'test', 'q_total' => 0, 'q_done' => 0, 'round_from' => 0);
    $s['channel'] = q("SELECT 1 FROM chats WHERE chat_id=? AND ctype='Kanal' LIMIT 1", array($cid))->fetchColumn() ? 1 : 0;
    $s['mode'] = 'test';   /* savol-javob faqat 4 variantli test (A, B, C, D) */
    return $s;
}
/* Test variantlari: to'g'ri javob + 3 ta noto'g'ri (savolda bo'lmasa — shu fandagi boshqa javoblardan yoki yaqin sonlardan), aralashtirilgan */
function quiz_opts($qq) {
    $ans = trim((string)$qq['answer']); $na = quiz_norm($ans); $w = array(); $seen = array($na => 1);
    $add = function ($x) use (&$w, &$seen) { $x = trim((string)$x); $k = quiz_norm($x); if ($x === '' || $k === '' || isset($seen[$k]) || mb_strlen($x) > 100) return; $seen[$k] = 1; $w[] = $x; };
    foreach (explode('|', (string)$qq['opts']) as $x) $add($x);
    if (count($w) < 3 && preg_match('/^\d{1,9}$/', $ans)) { $n = (int)$ans; foreach (array(1, -1, 2, -2, 10, -10, 5) as $d) if ($n + $d > 0) $add((string)($n + $d)); }
    if (count($w) < 3) {
        $num = (bool)preg_match('/^[\d\s.,]+$/u', $ans);
        $c = q('SELECT answer FROM quiz_questions WHERE id<>? AND cat=? ORDER BY RAND() LIMIT 40', array($qq['id'], $qq['cat']))->fetchAll(PDO::FETCH_COLUMN);
        foreach ($c as $x) if ((bool)preg_match('/^[\d\s.,]+$/u', $x) === $num) $add($x);
        foreach ($c as $x) $add($x);
        if (count($w) < 3) foreach (q('SELECT answer FROM quiz_questions WHERE id<>? ORDER BY RAND() LIMIT 20', array($qq['id']))->fetchAll(PDO::FETCH_COLUMN) as $x) $add($x);
    }
    $all = array_slice($w, 0, 3); $all[] = $ans; shuffle($all);
    return array($all, (int)array_search($ans, $all, true));
}
function quiz_start_test($cid, $s, $qq, $sid, $sec, $pts) {
    list($opts, $ok) = quiz_opts($qq);
    $qt = mb_substr('🧩 TARTIBON TEST · ' . quiz_label($qq['cat'], true) . ' · +' . $pts . " ochko\n\n" . $qq['question'], 0, 300);
    $p = array('chat_id' => $cid, 'question' => $qt, 'options' => array_map(function ($x, $i) { return array('text' => mb_substr('ABCD'[$i] . ') ' . $x, 0, 100)); }, $opts, array_keys($opts)), 'type' => 'quiz',
        'correct_option_id' => $ok, 'is_anonymous' => (bool)$s['channel'], 'open_period' => $sec);
    if (trim((string)$qq['note']) !== '') $p['explanation'] = mb_substr($qq['note'], 0, 200);
    $r = pr_call('sendPoll', $p);
    if (empty($r['ok'])) return $r;
    $t = time(); q('UPDATE quiz_sessions SET message_id=?, poll_id=?, correct_opt=?, opts=?, started_at=?, ends_at=? WHERE id=?',
        array((int)$r['result']['message_id'], (string)$r['result']['poll']['id'], $ok, json_encode($opts, JSON_UNESCAPED_UNICODE), $t, $t + $sec, $sid));
    return $r;
}
/* Guruhdagi test javobi (kanalda ovozlar anonim — kelmaydi). Har bir to'g'ri javobga ochko, bir kishiga bir marta. */
function quiz_poll_answer($pa) {
    if (empty($pa['user']['id']) || !empty($pa['user']['is_bot']) || empty($pa['option_ids'])) return;
    $s = q("SELECT id, chat_id, points, ends_at, correct_opt, opts FROM quiz_sessions WHERE poll_id=? AND kind='test'", array((string)$pa['poll_id']))->fetch();
    if (!$s) return;
    $now = time(); if ($now > (int)$s['ends_at'] + 5) return;   /* so'rovnoma yopilgan */
    $uid = (int)$pa['user']['id']; $nm = uname($pa['user']); $un = isset($pa['user']['username']) ? (string)$pa['user']['username'] : '';
    $opt = (int)$pa['option_ids'][0]; $ok = $opt === (int)$s['correct_opt']; $O = json_decode((string)$s['opts'], true);
    $db = db(); $db->beginTransaction();
    try {
        q('INSERT INTO quiz_participants (chat_id,user_id,name,username,last_at) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name), username=VALUES(username), last_at=VALUES(last_at)', array($s['chat_id'], $uid, $nm, $un, $now));
        if (q('INSERT IGNORE INTO quiz_answers (session_id,chat_id,user_id,answer,correct,points,at) VALUES (?,?,?,?,?,?,?)',
            array($s['id'], $s['chat_id'], $uid, mb_substr(isset($O[$opt]) ? $O[$opt] : (string)$opt, 0, 100), $ok ? 1 : 0, $ok ? (int)$s['points'] : 0, $now))->rowCount() === 1) {
            q('UPDATE quiz_participants SET answered=answered+1' . ($ok ? ', correct=correct+1, points=points+' . (int)$s['points'] . ', win_at=' . $now : '') . ' WHERE chat_id=? AND user_id=?', array($s['chat_id'], $uid));
            if ($ok) q('UPDATE quiz_sessions SET winner_id=?, winner_name=?, won_at=? WHERE id=? AND winner_id IS NULL', array($uid, $nm, $now, $s['id']));   /* birinchi topgan */
        }
        $db->commit();
    } catch (Exception $e) { if ($db->inTransaction()) $db->rollBack(); }
}
/* Shu guruhda yaqinda berilmagan savol */
function quiz_pick($cid, $cat) {   /* tanlangan bo'lim va uning ichidagi barcha fanlardan */
    $recent = q('SELECT question_id FROM quiz_sessions WHERE chat_id=? ORDER BY id DESC LIMIT 300', array($cid))->fetchAll(PDO::FETCH_COLUMN);
    $cand = q('SELECT * FROM quiz_questions' . ($cat !== '' ? ' WHERE cat=? OR cat LIKE ?' : '') . ' ORDER BY RAND() LIMIT 60', $cat !== '' ? array($cat, $cat . '/%') : array())->fetchAll();
    if (!$cand) return null;
    $pos = array_flip(array_reverse($recent));   /* 0 — eng eski */
    foreach ($cand as $c) if (!isset($pos[$c['id']])) return $c;
    usort($cand, function ($a, $b) use ($pos) { return $pos[$a['id']] - $pos[$b['id']]; });
    return $cand[0];
}
/* Guruhga yangi savol. Faol savol bo'lsa yuborilmaydi. Natija: array(ok, xato) */
function quiz_start($cid) {
    $s = quiz_cfg($cid);
    if ((int)$s['enabled'] && (int)$s['q_total'] > 0 && (int)$s['q_done'] >= (int)$s['q_total']) return array(false, 'Bu o\'yindagi barcha savollar berildi');
    $qq = quiz_pick($cid, (string)$s['cat']);
    if (!$qq) return array(false, 'Savollar bazasida ' . ($s['cat'] !== '' ? '«' . quiz_label($s['cat']) . '» bo\'limidan ' : '') . 'savol yo\'q');
    $now = time(); $sec = max(15, min(600, (int)$s['answer_sec'])); $pts = max(1, min(1000, (int)$s['points']));
    try { q("INSERT INTO quiz_sessions (chat_id,question_id,subject,points,started_at,ends_at,status,act,kind) VALUES (?,?,?,?,?,?,'active',1,?)", array($cid, $qq['id'], mb_substr(quiz_label($qq['cat'], true), 0, 120), $pts, $now, $now + $sec, $s['mode'])); }
    catch (PDOException $e) { return array(false, 'Guruhda hozir faol savol bor'); }
    $sid = (int)db()->lastInsertId();
    q('UPDATE quiz_settings SET next_at=? WHERE chat_id=?', array($now + $sec + max(1, (int)$s['interval_min']) * 60, $cid));   /* yakunlash kechiksa ham qayta yubormaydi */
    $r = $s['mode'] === 'test' ? quiz_start_test($cid, $s, $qq, $sid, $sec, $pts) : pr_call('sendMessage', array('chat_id' => $cid, 'text' => quiz_qtext($qq, $sec, $pts), 'parse_mode' => 'HTML'));
    if (empty($r['ok'])) {
        q("UPDATE quiz_sessions SET status='failed', act=NULL, finished_at=? WHERE id=?", array(time(), $sid));
        $e = 'Telegram: ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi');
        q('UPDATE quiz_settings SET last_err=? WHERE chat_id=?', array(mb_substr($e, 0, 255), $cid));
        return array(false, $e);
    }
    if ($s['mode'] !== 'test') { $t = time(); q('UPDATE quiz_sessions SET message_id=?, started_at=?, ends_at=? WHERE id=?', array((int)$r['result']['message_id'], $t, $t + $sec, $sid)); }
    q('UPDATE quiz_questions SET used=used+1 WHERE id=?', array($qq['id']));
    q("UPDATE quiz_settings SET last_err='' WHERE chat_id=?", array($cid));
    q('UPDATE quiz_settings SET q_done=q_done+1 WHERE chat_id=? AND enabled=1 AND q_total>0', array($cid));   /* o'yindagi savollar hisobi */
    return array(true, '');
}
/* Savolni yakunlash; o'yindagi oxirgi savol bo'lsa — TOP-10 g'oliblar */
function quiz_finish($sid) {
    if (!quiz_finish0($sid)) return false;
    $cid = q('SELECT chat_id FROM quiz_sessions WHERE id=?', array($sid))->fetchColumn();
    if ($cid !== false) quiz_round_end($cid);
    return true;
}
/* O'yin (N ta savol) tugadi: shu o'yindagi TOP-10 g'oliblar kanal/guruhga yuboriladi, avtomatik viktorina o'chadi */
function quiz_round_end($cid) {
    $s = q('SELECT enabled, q_total, q_done, round_from FROM quiz_settings WHERE chat_id=?', array($cid))->fetch();
    if (!$s || !(int)$s['enabled'] || (int)$s['q_total'] < 1 || (int)$s['q_done'] < (int)$s['q_total']) return;
    if (q("SELECT 1 FROM quiz_sessions WHERE chat_id=? AND status='active' LIMIT 1", array($cid))->fetchColumn()) return;
    if (q('UPDATE quiz_settings SET enabled=0 WHERE chat_id=? AND enabled=1', array($cid))->rowCount() !== 1) return;   /* faqat bir marta */
    $R = q('SELECT a.user_id, MAX(p.name) name, SUM(a.points) pts, SUM(a.correct) ok FROM quiz_answers a LEFT JOIN quiz_participants p ON p.chat_id=a.chat_id AND p.user_id=a.user_id
        WHERE a.chat_id=? AND a.at>=? GROUP BY a.user_id HAVING pts>0 ORDER BY pts DESC, ok DESC, MIN(a.at) ASC LIMIT 10', array($cid, (int)$s['round_from']))->fetchAll();
    $md = array('🥇', '🥈', '🥉');
    $t = "🏁 <b>SAVOL-JAVOB YAKUNLANDI!</b>\n" . (int)$s['q_total'] . " ta savol berildi.\n\n🏆 <b>TOP-10 G'OLIBLAR</b>\n\n";
    foreach ($R as $i => $r) $t .= (isset($md[$i]) ? $md[$i] : ($i + 1) . '.') . ' <a href="tg://user?id=' . (int)$r['user_id'] . '">' . htmlspecialchars((string)$r['name'] !== '' ? (string)$r['name'] : 'ID ' . $r['user_id']) . '</a> — <b>' . (int)$r['pts'] . "</b> ochko (" . (int)$r['ok'] . " to'g'ri)\n";
    if (!$R) $t .= "Bu o'yinda ochko to'plagan qatnashchi bo'lmadi.\n";
    $t .= "\nQatnashganlarning barchasiga rahmat! 🎉";
    pr_call('sendMessage', array('chat_id' => $cid, 'text' => $t, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true));
}
/* Savolni yakunlash va natijani e'lon qilish — faqat bir marta (status='active' sharti bilan) */
function quiz_finish0($sid) {
    $now = time();
    if (q("UPDATE quiz_sessions SET status='finished', act=NULL, finished_at=? WHERE id=? AND status='active'", array($now, $sid))->rowCount() !== 1) return false;
    $s = q('SELECT s.*, q.answer, q.note FROM quiz_sessions s LEFT JOIN quiz_questions q ON q.id=s.question_id WHERE s.id=?', array($sid))->fetch();
    $ans = htmlspecialchars(mb_strtoupper((string)$s['answer'], 'UTF-8')); $cfg = quiz_cfg($s['chat_id']);
    if ((int)$cfg['q_total'] > 0 && (int)$cfg['q_done'] >= (int)$cfg['q_total']) $cfg['enabled'] = 0;   /* o'yindagi oxirgi savol: «keyingi savol» deyilmaydi */
    if ($s['kind'] === 'test') {   /* test: so'rovnoma o'zi yopiladi; guruhda qisqa natija, kanalda — faqat navbat */
        if ($cfg['enabled']) q('UPDATE quiz_settings SET next_at=? WHERE chat_id=?', array($now + max(1, (int)$cfg['interval_min']) * 60, $s['chat_id']));
        if ($cfg['channel']) return true;
        $st = q('SELECT COUNT(*) n, COALESCE(SUM(correct),0) ok FROM quiz_answers WHERE session_id=?', array($sid))->fetch();
        $t = "📊 <b>TEST NATIJASI</b>\n\n✅ To'g'ri javob: <b>" . ($s['correct_opt'] !== null ? 'ABCD'[(int)$s['correct_opt']] . ') ' : '') . htmlspecialchars((string)$s['answer']) . "</b>\n👥 Qatnashdi: " . (int)$st['n'] . ' · topdi: ' . (int)$st['ok']
            . ($s['winner_id'] ? "\n🏆 Birinchi topgan: <a href=\"tg://user?id=" . (int)$s['winner_id'] . '">' . htmlspecialchars($s['winner_name']) . '</a>' : '')
            . ((int)$st['ok'] ? "\n⭐ Har bir to'g'ri javob: +" . (int)$s['points'] . ' ochko' : '') . ($cfg['enabled'] ? "\n\nKeyingi savol tez orada yuboriladi!" : '');
        $p = array('chat_id' => $s['chat_id'], 'text' => $t, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true);
        if ($s['message_id']) $p['reply_parameters'] = array('message_id' => (int)$s['message_id'], 'allow_sending_without_reply' => true);
        pr_call('sendMessage', $p);
        return true;
    }
    if ($s['winner_id']) {
        $tot = (int)q('SELECT points FROM quiz_participants WHERE chat_id=? AND user_id=?', array($s['chat_id'], $s['winner_id']))->fetchColumn();
        $t = "✅ <b>TO'G'RI JAVOB: " . $ans . "</b>\n\n🏆 Birinchi topgan: <a href=\"tg://user?id=" . (int)$s['winner_id'] . '">' . htmlspecialchars($s['winner_name']) . "</a>\n⭐ +" . (int)$s['points'] . " ochko\n\n📊 Umumiy ochko: " . $tot;
    } else $t = "⏰ <b>Vaqt tugadi!</b>\n\n✅ To'g'ri javob: <b>" . $ans . '</b>';
    if (trim((string)$s['note']) !== '') $t .= "\n\n💡 " . htmlspecialchars($s['note']);
    if ($cfg['enabled']) { $t .= "\n\nKeyingi savol tez orada yuboriladi!"; q('UPDATE quiz_settings SET next_at=? WHERE chat_id=?', array($now + max(1, (int)$cfg['interval_min']) * 60, $s['chat_id'])); }
    $p = array('chat_id' => $s['chat_id'], 'text' => $t, 'parse_mode' => 'HTML', 'disable_web_page_preview' => true);
    if ($s['message_id']) $p['reply_parameters'] = array('message_id' => (int)$s['message_id'], 'allow_sending_without_reply' => true);
    pr_call('sendMessage', $p);
    return true;
}
function quiz_tick($lim = 10) {   /* muddati o'tgan savollarni yakunlash (cron bo'lmasa ham guruhdagi har xabarda) */
    $n = 0;
    foreach (q("SELECT id FROM quiz_sessions WHERE status='active' AND ends_at<=? ORDER BY ends_at LIMIT " . (int)$lim, array(time()))->fetchAll(PDO::FETCH_COLUMN) as $id) if (quiz_finish((int)$id)) $n++;
    return $n;
}
/* Cron: yakunlash + navbatdagi savollar. Shu daqiqa ichida tugaydigan savollarni kutib, o'z vaqtida yakunlaydi (≤ 52 soniya). */
function quiz_run() {
    $t0 = time(); $f = quiz_tick(20); $st = 0;
    $due = q("SELECT DISTINCT s.chat_id FROM quiz_settings s JOIN chats c ON c.chat_id=s.chat_id AND c.status='approved' AND c.blocked=0
        WHERE s.enabled=1 AND s.next_at<=? AND (s.q_total=0 OR s.q_done<s.q_total) AND NOT EXISTS (SELECT 1 FROM quiz_sessions x WHERE x.chat_id=s.chat_id AND x.status='active') LIMIT 20", array($t0))->fetchAll(PDO::FETCH_COLUMN);
    foreach ($due as $cid) {
        $r = quiz_start($cid);
        if ($r[0]) $st++; else q('UPDATE quiz_settings SET next_at=?, last_err=? WHERE chat_id=?', array(time() + 300, mb_substr($r[1], 0, 255), $cid));   /* xato — 5 daqiqadan keyin qayta */
    }
    for ($i = 0; $i < 10; $i++) {
        $e = (int)q("SELECT MIN(ends_at) FROM quiz_sessions WHERE status='active'")->fetchColumn();
        if (!$e || $e > $t0 + 52) break;
        if ($e > time()) sleep($e - time());
        $f += quiz_tick(20);
    }
    return $f . ' yakunlandi, ' . $st . ' yangi';
}
/* Guruhdagi oddiy xabar — faol savolga javob bo'lishi mumkin */
function quiz_on_msg($m) {
    $cid = $m['chat']['id']; $text = isset($m['text']) ? trim((string)$m['text']) : '';
    if (preg_match('~^/(viktorina|krossvord)(@\w+)?(\s|$)~i', $text)) { if (q('SELECT 1 FROM quiz_settings WHERE chat_id=?', array($cid))->fetchColumn()) quiz_top_msg($cid); return; }
    if ($text === '' || $text[0] === '/' || mb_strlen($text) > QZ_ANS_MAX) return;
    if (empty($m['from']['id']) || !empty($m['from']['is_bot']) || isset($m['sender_chat']) || isset($m['forward_origin']) || isset($m['forward_date']) || !empty($m['is_automatic_forward'])) return;
    $s = q("SELECT s.id, s.points, s.ends_at, q.answer, q.alts FROM quiz_sessions s JOIN quiz_questions q ON q.id=s.question_id WHERE s.chat_id=? AND s.status='active' AND s.kind='cw' LIMIT 1", array($cid))->fetch();
    if (!$s) return;
    $now = time();
    if ($now >= (int)$s['ends_at'] || (isset($m['date']) && (int)$m['date'] >= (int)$s['ends_at'])) { quiz_finish((int)$s['id']); return; }   /* vaqt tugagan — javob qabul qilinmaydi */
    $uid = (int)$m['from']['id']; $nm = uname($m['from']); $un = isset($m['from']['username']) ? (string)$m['from']['username'] : '';
    $ok = quiz_match($text, $s['answer'], $s['alts']); $db = db();
    $db->beginTransaction();
    try {
        q('INSERT INTO quiz_participants (chat_id,user_id,name,username,last_at) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name), username=VALUES(username), last_at=VALUES(last_at)', array($cid, $uid, $nm, $un, $now));
        $new = q('INSERT IGNORE INTO quiz_answers (session_id,chat_id,user_id,answer,correct,at) VALUES (?,?,?,?,0,?)', array($s['id'], $cid, $uid, mb_substr($text, 0, 100), $now))->rowCount() === 1;
        $was = (int)q('SELECT correct FROM quiz_answers WHERE session_id=? AND user_id=? FOR UPDATE', array($s['id'], $uid))->fetchColumn();
        q('UPDATE quiz_answers SET answer=?, correct=GREATEST(correct,?), tries=tries+? WHERE session_id=? AND user_id=?', array(mb_substr($text, 0, 100), $ok ? 1 : 0, $new ? 0 : 1, $s['id'], $uid));
        if ($new) q('UPDATE quiz_participants SET answered=answered+1 WHERE chat_id=? AND user_id=?', array($cid, $uid));
        if ($ok && !$was) {
            q('UPDATE quiz_participants SET correct=correct+1 WHERE chat_id=? AND user_id=?', array($cid, $uid));
            /* ochko — faqat birinchi to'g'ri javobga; bir vaqtda kelgan javoblardan faqat bittasi o'tadi */
            if (q("UPDATE quiz_sessions SET winner_id=?, winner_name=?, won_at=? WHERE id=? AND status='active' AND winner_id IS NULL AND ends_at>?", array($uid, $nm, $now, $s['id'], $now))->rowCount() === 1) {
                q('UPDATE quiz_answers SET points=? WHERE session_id=? AND user_id=?', array((int)$s['points'], $s['id'], $uid));
                q('UPDATE quiz_participants SET points=points+?, win_at=? WHERE chat_id=? AND user_id=?', array((int)$s['points'], $now, $cid, $uid));
            }
        }
        $db->commit();
    } catch (Exception $e) { if ($db->inTransaction()) $db->rollBack(); }
}
/* Reyting. $cid=0 — barcha guruhlar. mode: all | day | week | correct | people */
function quiz_rank($cid, $mode, $lim = 50) {
    $lim = (int)$lim;
    if ($mode === 'day' || $mode === 'week') {
        $from = strtotime(date('Y-m-d')) - ($mode === 'week' ? ((int)date('N') - 1) * 86400 : 0);
        return q('SELECT a.user_id, n.name, n.username, SUM(a.points) points, SUM(a.correct) correct, COUNT(*) answered FROM quiz_answers a
            LEFT JOIN (SELECT user_id, MAX(name) name, MAX(username) username FROM quiz_participants GROUP BY user_id) n ON n.user_id=a.user_id
            WHERE a.at>=?' . ($cid ? ' AND a.chat_id=?' : '') . ' GROUP BY a.user_id, n.name, n.username HAVING points>0 ORDER BY points DESC, correct DESC, MAX(CASE WHEN a.points>0 THEN a.at END) ASC LIMIT ' . $lim,
            $cid ? array($from, $cid) : array($from))->fetchAll();
    }
    $ord = $mode === 'correct' ? 'correct DESC, points DESC, win_at ASC' : ($mode === 'people' ? 'last_at DESC' : 'points DESC, correct DESC, win_at ASC');
    $hav = $mode === 'people' ? '' : ($mode === 'correct' ? ' HAVING correct>0' : ' HAVING points>0');
    if ($cid) return q('SELECT user_id, name, username, points, correct, answered, win_at, last_at FROM quiz_participants WHERE chat_id=?' . str_replace('HAVING', 'AND', $hav) . ' ORDER BY ' . $ord . ' LIMIT ' . $lim, array($cid))->fetchAll();
    return q('SELECT user_id, MAX(name) name, MAX(username) username, SUM(points) points, SUM(correct) correct, SUM(answered) answered, MAX(win_at) win_at, MAX(last_at) last_at FROM quiz_participants GROUP BY user_id' . $hav . ' ORDER BY ' . $ord . ' LIMIT ' . $lim)->fetchAll();
}
function quiz_top_msg($cid) {
    $R = quiz_rank($cid, 'all', 10); $md = array('🥇', '🥈', '🥉');
    $t = "🏆 <b>Savol-javob reytingi</b>\n\n";
    foreach ($R as $i => $r) $t .= (isset($md[$i]) ? $md[$i] : ($i + 1) . '.') . ' ' . htmlspecialchars($r['name']) . ' — <b>' . (int)$r['points'] . "</b> ochko\n";
    if (!$R) $t .= 'Hali ochko to\'plagan qatnashchi yo\'q.';
    pr_call('sendMessage', array('chat_id' => $cid, 'text' => trim($t), 'parse_mode' => 'HTML'));
}
/* AI: tanlangan bo'lim uchun test savollari (admin ko'rib chiqib saqlaydi) */
function quiz_ai($cat, $n, $lv) {
    if (!ai_on()) return array(null, 'AI kaliti kiritilmagan (index.php boshida AI_KEY)');
    q("INSERT INTO settings (k,v) VALUES (?, '1') ON DUPLICATE KEY UPDATE v=v+1", array('ai_n_' . date('Ymd'))); if (ai_used() > ai_limit()) return array(null, 'Kunlik AI limiti tugadi');
    $schema = array('type' => 'object', 'properties' => array('questions' => array('type' => 'array', 'items' => array('type' => 'object', 'properties' => array(
        'question' => array('type' => 'string'), 'answer' => array('type' => 'string'), 'wrong' => array('type' => 'array', 'items' => array('type' => 'string')), 'note' => array('type' => 'string')),
        'required' => array('question', 'answer', 'wrong', 'note'), 'additionalProperties' => false))), 'required' => array('questions'), 'additionalProperties' => false);
    $old = q('SELECT question FROM quiz_questions WHERE cat=? ORDER BY id DESC LIMIT 40', array($cat))->fetchAll(PDO::FETCH_COLUMN);
    $sys = "You write quiz questions for a Telegram quiz bot used by students in Uzbekistan. Write in Uzbek (Latin script, use ' for o', g'), except for foreign-language subjects where the question may be in that language. "
        . "Follow the official Uzbekistan curriculum for the given level. Every question must have exactly one unambiguously correct answer that is factually accurate; if unsure of a fact, choose a different question. "
        . "answer: short (1–5 words or a formula/number, max 60 characters). wrong: exactly 3 plausible but clearly incorrect options of similar form and length. note: one short explanation sentence (max 150 characters) or empty. Question max 250 characters. Do not repeat the existing questions.";
    $u = "Bo'lim: " . quiz_label($cat) . "\nQiyinlik: " . array(1 => 'oson', 2 => "o'rtacha", 3 => 'qiyin')[$lv] . "\nSoni: " . $n . ($old ? "\n\nMavjud savollar (takrorlamang):\n- " . implode("\n- ", array_map(function ($x) { return mb_substr($x, 0, 120); }, $old)) : '');
    $body = array('model' => AI_MODEL, 'max_tokens' => 6000, 'system' => $sys, 'output_config' => array('effort' => 'medium', 'format' => array('type' => 'json_schema', 'schema' => $schema)), 'messages' => array(array('role' => 'user', 'content' => $u)));
    $c = curl_init(AI_URL);
    curl_setopt_array($c, array(CURLOPT_POST => 1, CURLOPT_POSTFIELDS => json_encode($body), CURLOPT_HTTPHEADER => array('content-type: application/json', 'x-api-key: ' . AI_KEY, 'anthropic-version: 2023-06-01'), CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 90, CURLOPT_CONNECTTIMEOUT => 8));
    $r = curl_exec($c); $code = (int)curl_getinfo($c, CURLINFO_HTTP_CODE); curl_close($c); $j = $r ? json_decode($r, true) : null;
    if (!is_array($j)) return array(null, 'AI serveri bilan aloqa yo\'q');
    if ($code !== 200) return array(null, 'AI xatosi (HTTP ' . $code . '): ' . (isset($j['error']['message']) ? mb_substr((string)$j['error']['message'], 0, 160) : ''));
    foreach (isset($j['content']) ? $j['content'] : array() as $b) if (isset($b['type']) && $b['type'] === 'text') {
        $v = json_decode((string)$b['text'], true); if (!isset($v['questions']) || !is_array($v['questions'])) continue;
        $out = array(); foreach ($v['questions'] as $x) {
            $w = array_values(array_filter(array_map(function ($y) { return mb_substr(trim((string)$y), 0, 100); }, (array)$x['wrong']), 'strlen'));
            if (trim($x['question']) === '' || trim($x['answer']) === '' || count($w) < 3) continue;
            $out[] = array('question' => mb_substr(trim($x['question']), 0, 300), 'answer' => mb_substr(trim($x['answer']), 0, 60), 'opts' => implode('|', array_slice($w, 0, 3)), 'note' => mb_substr(trim($x['note']), 0, 200));
        }
        return array($out, '');
    }
    return array(null, 'AI javobi tushunarsiz');
}
/* Bot guruhdagi javoblarni ko'ra oladimi: privacy o'chirilgan yoki bot admin bo'lishi kerak */
function quiz_diag($cid, $mode = 'cw') {
    $me = pr_call('getMe'); $read = !empty($me['result']['can_read_all_group_messages']);
    $bm = pr_call('getChatMember', array('chat_id' => $cid, 'user_id' => (int)strtok(BOT_TOKEN, ':')));
    $st = isset($bm['result']['status']) ? (string)$bm['result']['status'] : ''; $adm = $st === 'administrator' || $st === 'creator';
    $in = $st !== '' && $st !== 'left' && $st !== 'kicked'; $tips = array();
    if (!$in) $tips[] = 'Bot bu guruhda yo\'q. Botni guruhga qo\'shing va administrator qiling.';
    elseif ($st === 'restricted' && empty($bm['result']['can_send_messages'])) $tips[] = 'Botga guruhda xabar yozish taqiqlangan — cheklovni olib tashlang.';
    if ($mode === 'test') $read = true;   /* test javoblari (poll_answer) privacy'dan qat'i nazar keladi */
    if ($in && !$read && !$adm) $tips[] = "Bot guruhdagi oddiy xabarlarni ko'rmaydi, shuning uchun javoblarni tekshira olmaydi. Yechim: botni guruhga administrator qiling (eng oson) yoki @BotFather → /mybots → Bot Settings → Group Privacy → Turn off, so'ng botni guruhdan chiqarib qayta qo'shing.";
    return array('ok' => $in && ($read || $adm) && !($st === 'restricted' && empty($bm['result']['can_send_messages'])), 'admin' => $adm, 'read_all' => $read, 'status' => $st, 'tips' => $tips);
}

