function ago_txt($ts) { if (!$ts) return "ma'lumot yo'q"; $d = time() - $ts; return $d < 90 ? 'hozirgina' : ($d < 3600 ? round($d / 60) . ' daqiqa oldin' : ($d < 86400 ? round($d / 3600) . ' soat oldin' : round($d / 86400) . ' kun oldin')); }
function holat_items() {   /* ochiq «bot holati» — maxfiy ma'lumotsiz */
    $cm = strtotime((string)setting('cron_min_at', '')) ?: 0; $lo = strtotime((string)setting('last_ok', '')) ?: 0;
    $I = array(array('Bot va avtomatik xabarlar', $cm > time() - 300, ago_txt($cm)), array('Dollar kurslari yangilandi', $lo > time() - 3 * 3600, ago_txt($lo)));
    foreach (array('dp_last' => 'Tongi xabar', 'wx_last' => 'Ob-havo', 'ev_last' => 'Kechki xabar') as $k => $n) { $v = (string)setting($k, ''); if ($v !== '') $I[] = array($n, true, 'oxirgisi ' . $v); }
    $st = json_decode((string)setting('mon_st', ''), true);
    if (is_array($st)) foreach ($st as $u => $x) $I[] = array('Manba: ' . preg_replace('/^www\./', '', (string)parse_url($u, PHP_URL_HOST)), !empty($x['ok']), !empty($x['ok']) ? 'ishlayapti' : 'javob bermayapti');
    return $I;
}
function holat_text() {
    $t = "🧪 TartibOn holati — " . date('d.m.Y H:i') . "\n\n";
    foreach (holat_items() as $x) $t .= ($x[1] ? '✅ ' : '⚠️ ') . $x[0] . ' — ' . $x[2] . "\n";
    return $t . "\n🌐 " . APP_URL . '?holat';
}
function tg_doc($chat, $data, $name, $cap = '') {   /* fayl yuborish (CSV) */
    $bd = '----up' . md5(uniqid('', true)); $b = "--$bd\r\nContent-Disposition: form-data; name=\"chat_id\"\r\n\r\n$chat\r\n";
    if ($cap !== '') $b .= "--$bd\r\nContent-Disposition: form-data; name=\"caption\"\r\n\r\n$cap\r\n";
    $b .= "--$bd\r\nContent-Disposition: form-data; name=\"document\"; filename=\"$name\"\r\nContent-Type: text/csv\r\n\r\n" . $data . "\r\n--$bd--\r\n";
    $c = curl_init('https://api.telegram.org/bot' . BOT_TOKEN . '/sendDocument');
    curl_setopt_array($c, array(CURLOPT_POST => 1, CURLOPT_POSTFIELDS => $b, CURLOPT_HTTPHEADER => array('Content-Type: multipart/form-data; boundary=' . $bd), CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 30));
    $r = curl_exec($c); curl_close($c); $j = $r ? json_decode($r, true) : null; return is_array($j) ? $j : array('ok' => false);
}
function csv_make($rows) {   /* Excel o'qiydigan CSV: UTF-8 BOM, nuqtali vergul */
    $o = "\xEF\xBB\xBF"; foreach ($rows as $r) $o .= implode(';', array_map(function ($v) { $v = (string)$v; return preg_match('/[;"\n\r]/', $v) ? '"' . str_replace('"', '""', $v) . '"' : $v; }, $r)) . "\r\n";
    return $o;
}
function kk_run() {   /* kun kanali: har kuni bitta qatnashuvchi kanal boshqa qatnashuvchilarda tavsiya etiladi (24 soatda o'chadi) */
    if (setting('kk_gon', '1') !== '1') return 'o\'chiq';
    $today = date('Y-m-d'); if (setting('kk_date', '') === $today || date('H:i') < setting('kk_time', '12:00')) return 0;
    setset('kk_date', $today);
    $mem = "(SELECT s.members FROM chat_stats s WHERE s.chat_id=c.chat_id AND s.members>0 ORDER BY s.day DESC LIMIT 1)";
    $c = q("SELECT c.id, c.chat_id, c.username, c.vz_cat, c.vz_desc, $mem AS members FROM chats c WHERE c.kk_on=1 AND c.ctype='Kanal' AND c.status='approved' AND c.blocked=0 AND c.paused<" . time() . " AND c.username LIKE '@%' AND (c.kk_last IS NULL OR c.kk_last<?) ORDER BY RAND() LIMIT 1", array(date('Y-m-d', time() - 20 * 86400)))->fetch();
    if (!$c) return 0;
    q('UPDATE chats SET kk_last=? WHERE id=?', array($today, $c['id']));
    $h = function ($x) { return htmlspecialchars((string)$x, ENT_QUOTES, 'UTF-8'); };
    $t = "📣 <b>Kun kanali</b>\n\n" . $h($c['username']) . ($c['vz_desc'] !== '' ? "\n" . $h($c['vz_desc']) : ($c['vz_cat'] !== '' ? "\n" . $h($c['vz_cat']) . " mavzusida" : '')) . ($c['members'] ? "\n👥 " . number_format((int)$c['members'], 0, '.', ' ') . ' obunachi' : '') . "\n\n#KunKanali #TartibOn";
    $kb = array('inline_keyboard' => array(array(array('text' => "➕ Obuna bo'lish", 'url' => 'https://t.me/' . ltrim($c['username'], '@')))));
    $n = 0; $rows = q("SELECT id, chat_id FROM chats WHERE kk_on=1 AND status='approved' AND blocked=0 AND paused<" . time() . " AND id<>? LIMIT 300", array($c['id']))->fetchAll();
    foreach (array_chunk($rows, 20) as $k => $ch) {
        if ($k) sleep(1); $items = array(); foreach ($ch as $x) $items[$x['id']] = array('chat_id' => $x['chat_id'], 'text' => $t, 'parse_mode' => 'HTML', 'reply_markup' => $kb, 'disable_web_page_preview' => true);
        foreach (tg_multi('sendMessage', $items) as $id => $r) { if (!empty($r['ok'])) { $n++; autodel_add($items[$id]['chat_id'], $r['result']['message_id'], 24); } elseif (isset($r['description'])) chat_lost($id, $r['description']); }
    }
    $own = q('SELECT owner FROM chats WHERE id=?', array($c['id']))->fetchColumn();
    if ($own && $n) pr_call('sendMessage', array('chat_id' => $own, 'text' => '🎉 Bugun ' . $c['username'] . " «Kun kanali» bo'ldi — " . $n . " ta kanal va guruhda tavsiya etildi!"));
    return $n;
}
function best_hour($cid) {   /* guruh faolligi (yoki umumiy TartibOn guruhlari) bo'yicha eng faol soat, 7:00–22:00 */
    $H = array(); $src = 'own';
    if ($cid) foreach (q('SELECT h, n FROM act_hours WHERE chat_id=?', array($cid))->fetchAll() as $r) $H[(int)$r['h']] = (int)$r['n'];
    if (array_sum($H) < 100) { $H = array(); $src = 'all'; foreach (q('SELECT h, SUM(n) n FROM act_hours GROUP BY h')->fetchAll() as $r) $H[(int)$r['h']] = (int)$r['n']; }
    $best = 20; $mx = -1; for ($h = 7; $h <= 22; $h++) { $v = isset($H[$h]) ? $H[$h] : 0; if ($v > $mx) { $mx = $v; $best = $h; } }
    if ($mx <= 0) $src = 'def';
    return array($best, $src);
}
function inl_num($s) {
    $s = str_replace(array(' ', "\xC2\xA0", "'"), '', $s);
    if (strpos($s, ',') !== false && strpos($s, '.') !== false) $s = str_replace(',', '', $s); elseif (preg_match('/,\d{1,2}$/', $s)) $s = str_replace(',', '.', $s); else $s = str_replace(',', '', $s);
    return (float)$s;
}
function inl_handle($iq) {   /* inline: @TartibOnBot 100$ — istalgan chatda kurs bo'yicha hisob */
    $q = mb_strtolower(trim((string)$iq['query'])); $B = array();
    foreach (rates_data() as $c) {
        $by = 0; $sl = 0; $bb = ''; $bs = '';
        foreach ($c['banks'] as $b) { if (!empty($b['stale']) || $b['buy'] <= 0 || $b['sell'] <= 0) continue; if ($b['buy'] > $by) { $by = (float)$b['buy']; $bb = $b['bank']; } if (!$sl || $b['sell'] < $sl) { $sl = (float)$b['sell']; $bs = $b['bank']; } }
        if ($by || $c['official']) $B[$c['code']] = array('buy' => $by, 'sell' => $sl, 'bb' => $bb, 'bs' => $bs, 'off' => $c['official'] ? (float)$c['official']['official'] : 0);
    }
    $f = function ($n) { return number_format($n, $n >= 100 ? 0 : 2, ',', ' '); }; $res = array(); $tag = "\n\n📲 @" . BOT_USERNAME;
    $art = function ($id, $title, $desc, $text) use (&$res) { $res[] = array('type' => 'article', 'id' => $id, 'title' => $title, 'description' => $desc, 'input_message_content' => array('message_text' => $text)); };
    $cur = array('$' => 'USD', 'usd' => 'USD', 'dollar' => 'USD', 'доллар' => 'USD', '€' => 'EUR', 'eur' => 'EUR', 'yevro' => 'EUR', 'evro' => 'EUR', 'euro' => 'EUR', '₽' => 'RUB', 'rub' => 'RUB', 'rubl' => 'RUB', 'рубль' => 'RUB', 'руб' => 'RUB');
    $code = ''; $sum = false;
    if (preg_match('/([\d][\d\s.,\']*)/u', $q, $m)) $amt = inl_num($m[1]); else $amt = 0;
    foreach ($cur as $k => $v) if (mb_strpos($q, $k) !== false) { $code = $v; break; }
    if (!$code && preg_match('/(so\'?m|sum|сум|uzs)/u', $q)) $sum = true;
    if ($amt > 0 && !$code && !$sum) $code = $amt >= 50000 ? '' : 'USD';
    if ($amt > 0 && !$code && !$sum) $sum = true;
    if ($amt > 0 && $code && isset($B[$code])) {
        $x = $B[$code]; $sym = array('USD' => '$', 'EUR' => '€', 'RUB' => '₽')[$code];
        if ($x['buy']) $art('s' . $code, $f($amt) . ' ' . $sym . ' = ' . $f($amt * $x['buy']) . " so'm", "Bankka sotsangiz · eng yaxshi: " . $x['bb'], '💵 ' . $f($amt) . ' ' . $sym . ' → ' . $f($amt * $x['buy']) . " so'm\n🏦 Bankka sotish: " . $f($x['buy']) . ' (' . $x['bb'] . ')' . "\n🛒 Sotib olish uchun kerak: " . $f($amt * $x['sell']) . " so'm (" . $f($x['sell']) . ', ' . $x['bs'] . ')' . ($x['off'] ? "\n🏛 Markaziy bank: " . $f($x['off']) : '') . "\n📅 " . date('d.m.Y H:i') . $tag);
        if ($x['sell']) $art('b' . $code, $f($amt) . ' ' . $sym . ' olish uchun: ' . $f($amt * $x['sell']) . " so'm", "Eng arzon sotuvchi: " . $x['bs'], '🛒 ' . $f($amt) . ' ' . $sym . ' sotib olish: ' . $f($amt * $x['sell']) . " so'm\n🏦 Eng arzon: " . $x['bs'] . ' — ' . $f($x['sell']) . "\n📅 " . date('d.m.Y H:i') . $tag);
    } elseif ($amt > 0 && $sum && isset($B['USD']) && $B['USD']['sell']) {
        $x = $B['USD']; $art('u', $f($amt) . " so'm = " . $f($amt / $x['sell']) . ' $', "Eng arzon kurs bilan dollar olsangiz · " . $x['bs'], '💵 ' . $f($amt) . " so'm → " . $f($amt / $x['sell']) . " $\n🛒 Kurs: " . $f($x['sell']) . ' (' . $x['bs'] . ')' . "\n📅 " . date('d.m.Y H:i') . $tag);
    }
    if (!$res) {
        $t = "💵 Bugungi valyuta kurslari — " . date('d.m.Y') . "\n"; $d = array();
        foreach (array('USD' => '🇺🇸 Dollar', 'EUR' => '🇪🇺 Yevro', 'RUB' => '🇷🇺 Rubl') as $k => $n) if (isset($B[$k]) && $B[$k]['buy']) { $t .= "\n" . $n . ': olish ' . $f($B[$k]['buy']) . ' · sotish ' . $f($B[$k]['sell']); $d[] = $k . ' ' . $f($B[$k]['buy']) . '/' . $f($B[$k]['sell']); }
        $art('all', '💵 Bugungi kurslar', $d ? implode(' · ', $d) : 'Kurslar hozircha yo\'q', $t . $tag);
        $art('help', 'ℹ️ Hisoblash: «100$», «50 eur», «1 000 000 so\'m»', 'Summani va valyutani yozing', "ℹ️ @" . BOT_USERNAME . " 100$ — dollarni so'mga hisoblash\n@" . BOT_USERNAME . " 1000000 so'm — so'mni dollarga" . $tag);
    }
    pr_call('answerInlineQuery', array('inline_query_id' => $iq['id'], 'results' => $res, 'cache_time' => 300, 'is_personal' => false));
}
/* chat_member yangilanishi: statistika (kirdi/chiqdi) va taklif havolasi orqali kelganlar */
function ext_member($cm) {
    $cid = $cm['chat']['id']; $old = isset($cm['old_chat_member']['status']) ? $cm['old_chat_member']['status'] : ''; $new = isset($cm['new_chat_member']['status']) ? $cm['new_chat_member']['status'] : '';
    $in = function ($s, $x) { return in_array($s, array('member', 'administrator', 'creator'), true) || ($s === 'restricted' && !empty($x['is_member'])); };
    $was = $in($old, $cm['old_chat_member']); $is = $in($new, $cm['new_chat_member']);
    $by = isset($cm['from']) ? $cm['from'] : null; $tu = $cm['new_chat_member']['user'];
    if ($by && empty($by['is_bot']) && (int)$by['id'] !== (int)$tu['id']) {   /* admin qo'lda qilgan ish — jurnalga */
        if ($new === 'kicked') alog($cid, $by, 'ban', $tu, ''); elseif ($old === 'kicked') alog($cid, $by, 'unban', $tu, '');
        elseif ($new === 'restricted' && empty($cm['new_chat_member']['can_send_messages'])) alog($cid, $by, 'mute', $tu, '');
        elseif ($was && $new === 'left') alog($cid, $by, 'kick', $tu, ''); elseif ($new === 'administrator' && $old !== 'administrator') alog($cid, $by, 'admin+', $tu, '');
        elseif ($old === 'administrator' && $new !== 'administrator') alog($cid, $by, 'admin-', $tu, '');
    }
    if ($is && !$was && empty($tu['is_bot']) && gban_has((int)$tu['id'])) {
        $go = q('SELECT opts FROM group_guard WHERE chat_id=? AND enabled=1', array($cid))->fetchColumn(); $go = $go ? json_decode($go, true) + json_decode(GUARD_NEW, true) : array();
        if (!empty($go['gban']) && !empty(pr_call('banChatMember', array('chat_id' => $cid, 'user_id' => (int)$tu['id']))['ok']))
            say_tmp($cid, '🚫 ' . uname($tu) . " boshqa guruhlarda spam uchun bloklangan (umumiy qora ro'yxat) — guruhdan chiqarildi.", 60);
    }
    if ($was === $is) return;
    q('INSERT INTO chat_stats (chat_id,day,' . ($is ? 'joins' : 'lefts') . ') VALUES (?,?,1) ON DUPLICATE KEY UPDATE ' . ($is ? 'joins=joins+1' : 'lefts=lefts+1'), array($cid, date('Y-m-d')));
    $uid = (int)$cm['new_chat_member']['user']['id'];
    if ($is && empty($cm['new_chat_member']['user']['is_bot'])) track_join($cid, $cm['new_chat_member']['user']);   /* yangi a'zo — 24 soatlik cheklov uchun qo'shilgan vaqti */
    if ($is && isset($cm['invite_link']['name']) && preg_match('/^ref_(\d+)$/', $cm['invite_link']['name'], $x) && (int)$x[1] !== $uid) {
        if (q('INSERT IGNORE INTO ref_joins (chat_id,user_id,ref_user,at) VALUES (?,?,?,?)', array($cid, $uid, (int)$x[1], date('Y-m-d H:i:s')))->rowCount() === 1)
            q('UPDATE ref_links SET joins=joins+1 WHERE chat_id=? AND user_id=?', array($cid, (int)$x[1]));
    }
}
/* ---- Rejalashtirilgan postlar ---- */
function post_send($p, $chat) {
    $kb = ($p['btn_text'] !== '' && $p['btn_url'] !== '') ? array('reply_markup' => array('inline_keyboard' => array(array(array('text' => $p['btn_text'], 'url' => $p['btn_url']))))) : array();
    $ref = $p['src'] !== '' ? dp_ref($p['src']) : null; $body = trim((string)$p['body']);
    if ($ref) { $m = 'copyMessage'; $prm = array('chat_id' => $chat, 'from_chat_id' => $ref[0], 'message_id' => $ref[1]); if ($body !== '') $prm += array('caption' => mb_substr($body, 0, 1024), 'parse_mode' => 'HTML'); }
    else { $m = 'sendMessage'; $prm = array('chat_id' => $chat, 'text' => mb_substr($body, 0, 4096), 'parse_mode' => 'HTML'); }
    $prm += $kb;
    $r = pr_call($m, $prm);
    if (empty($r['ok']) && isset($r['description']) && stripos($r['description'], 'parse entities') !== false) $r = pr_call($m, dp_plain($prm));
    $GLOBALS['POST_MID'] = isset($r['result']['message_id']) ? (int)$r['result']['message_id'] : 0;
    return !empty($r['ok']) ? '' : pr_tg_err($r);
}
function posts_run($lim) {
    $now = time(); $n = 0;
    foreach (q("SELECT p.*, c.chat_id AS cid FROM sched_posts p JOIN chats c ON c.id=p.chat_ref WHERE p.active=1 AND p.run_at<=? AND c.blocked=0 AND c.paused<" . time() . " ORDER BY p.run_at LIMIT " . (int)$lim, array(date('Y-m-d H:i:s', $now)))->fetchAll() as $p) {
        $step = $p['rep'] === 'daily' ? 86400 : ($p['rep'] === 'weekly' ? 604800 : 0); $t = strtotime($p['run_at']);
        if ($step) { while ($t <= $now) $t += $step; }
        if (q('UPDATE sched_posts SET run_at=?, active=?, last_at=? WHERE id=? AND run_at=? AND active=1', array(date('Y-m-d H:i:s', $t), $step ? 1 : 0, date('Y-m-d H:i:s'), $p['id'], $p['run_at']))->rowCount() !== 1) continue;   /* boshqa cron oldi */
        $e = (!$step && $now - strtotime($p['run_at']) > 86400) ? 'Vaqti 1 kundan ko\'p o\'tib ketgan (cron ishlamagan) — yuborilmadi' : post_send($p, $p['cid']);
        if ($e === '' && !empty($p['del_h'])) autodel_add($p['cid'], isset($GLOBALS['POST_MID']) ? $GLOBALS['POST_MID'] : 0, (int)$p['del_h']);   /* 1/24 */
        q('UPDATE sched_posts SET sent_n=sent_n+?, last_err=? WHERE id=?', array($e === '' ? 1 : 0, $e === '' ? null : mb_substr($e, 0, 255), $p['id']));
        $n++;
    }
    return $n;
}
/* ---- Statistika ---- */
function stats_fetch($ids) {
    foreach ($ids as $cid) {
        $r = pr_call('getChatMemberCount', array('chat_id' => $cid));
        q('INSERT INTO chat_stats (chat_id,day,members) VALUES (?,?,?) ON DUPLICATE KEY UPDATE members=VALUES(members)', array($cid, date('Y-m-d'), !empty($r['ok']) ? (int)$r['result'] : -1));
    }
}
function stats_run($lim) {
    stats_fetch(q("SELECT DISTINCT c.chat_id FROM chats c LEFT JOIN chat_stats s ON s.chat_id=c.chat_id AND s.day=? WHERE c.blocked=0 AND c.status IN ('approved','pending') AND s.members IS NULL LIMIT " . (int)$lim, array(date('Y-m-d')))->fetchAll(PDO::FETCH_COLUMN));
}
function stat_members($cid, $ago) {
    $v = q('SELECT members FROM chat_stats WHERE chat_id=? AND day<=? AND members>=0 ORDER BY day DESC LIMIT 1', array($cid, date('Y-m-d', time() - $ago * 86400)))->fetchColumn();
    return $v === false ? null : (int)$v;
}
function sgn($n) { return ($n > 0 ? '+' : '') . n0($n); }
function report_run($lim) {   /* dushanba 09:00 dan keyin — haftalik hisobot egasiga */
    if (date('N') !== '1' || date('H:i') < '09:00') return 0;
    $wk = date('o-W'); $n = 0;
    foreach (q("SELECT DISTINCT owner FROM chats WHERE blocked=0 AND status IN ('approved','pending')")->fetchAll(PDO::FETCH_COLUMN) as $own) {
        if ($n >= $lim) break;
        if (setting('wr_' . $own) === $wk || setting('wr_off_' . $own) === '1') continue;
        setset('wr_' . $own, $wk); $n++; $L = array();
        foreach (q("SELECT chat_id, username, ctype FROM chats WHERE owner=? AND blocked=0 AND status IN ('approved','pending')", array($own))->fetchAll() as $c) {
            $a = stat_members($c['chat_id'], 0); $b = stat_members($c['chat_id'], 7);
            $ms = (int)q('SELECT COALESCE(SUM(msgs),0) FROM chat_stats WHERE chat_id=? AND day>?', array($c['chat_id'], date('Y-m-d', time() - 7 * 86400)))->fetchColumn();
            $L[] = ($c['ctype'] === 'Kanal' ? '📢 ' : '👥 ') . $c['username'] . "\n    👤 " . ($a === null ? '—' : n0($a)) . ($a !== null && $b !== null ? ' (' . sgn($a - $b) . ' 7 kunda)' : '') . ($c['ctype'] === 'Guruh' ? ' · 💬 ' . n0($ms) . ' xabar' : '');
        }
        if ($L) pr_call('sendMessage', array('chat_id' => $own, 'text' => "📊 Haftalik hisobot\n\n" . implode("\n\n", $L) . "\n\nBatafsil: Menyu → 📊 Statistika"));
    }
    return $n;
}
/* ---- Konkurslar ---- */
function gw_text($g) {
    $req = json_decode($g['req'], true); $t = "🎁 KONKURS!\n\n" . $g['title'] . "\n\n📋 Shartlar:\n";
    foreach ($req as $r) $t .= '✅ ' . $r['name'] . " ga obuna bo'ling\n";
    return $t . "\n🏆 G'oliblar soni: " . $g['winners'] . "\n⏰ Yakunlanish: " . date('d.m.Y H:i', strtotime($g['ends_at'])) . "\n\n👇 Ishtirok etish uchun tugmani bosing";
}
function gw_kb($id, $label) { return array('inline_keyboard' => array(array(array('text' => $label, 'callback_data' => 'gw:' . $id)))); }
function gw_join($id, $u, $ans) {
    $g = q('SELECT * FROM giveaways WHERE id=?', array($id))->fetch();
    if (!$g || $g['status'] !== 'active' || strtotime($g['ends_at']) <= time()) { $ans('⏰ Bu konkurs yakunlangan', true); return; }
    $miss = array(); foreach (json_decode($g['req'], true) as $r) if (!is_member($r['chat_id'], $u['id'])) $miss[] = $r['name'];
    if ($miss) { $ans("❗ Avval obuna bo'ling:\n" . implode("\n", $miss), true); return; }
    if (q('INSERT IGNORE INTO gw_users (gw_id,user_id,name,username,at) VALUES (?,?,?,?,?)', array($id, $u['id'], uname($u), isset($u['username']) ? mb_substr($u['username'], 0, 40) : '', date('Y-m-d H:i:s')))->rowCount() === 1) {
        q('UPDATE giveaways SET n=n+1 WHERE id=?', array($id)); $ans('✅ Siz konkurs ishtirokchisiz! Omad!', true);
    } else $ans('Siz allaqachon ishtirok etyapsiz ✅', true);
}
function gw_finish($id) {
    if (q("UPDATE giveaways SET status='done' WHERE id=? AND status='active'", array($id))->rowCount() !== 1) return false;
    $g = q('SELECT * FROM giveaways WHERE id=?', array($id))->fetch(); $req = json_decode($g['req'], true); $win = array(); $tries = 0;
    foreach (q('SELECT * FROM gw_users WHERE gw_id=? ORDER BY RAND()', array($id))->fetchAll() as $x) {
        if (count($win) >= (int)$g['winners'] || ++$tries > 80) break;
        $ok = true; foreach ($req as $r) if (!is_member($r['chat_id'], $x['user_id'])) { $ok = false; break; }   /* obunadan chiqqanlar g'olib bo'lmaydi */
        if ($ok) $win[] = $x;
    }
    $t = "🎉 KONKURS YAKUNLANDI!\n\n" . mb_substr($g['title'], 0, 300) . "\n\n👥 Ishtirokchilar: " . (int)$g['n'] . "\n";
    if ($win) { $t .= "🏆 G'oliblar:\n"; foreach ($win as $i => $w) $t .= ($i + 1) . '. ' . $w['name'] . ($w['username'] !== '' ? ' (@' . $w['username'] . ')' : '') . "\n"; }
    else $t .= "😔 Shartlarni bajargan ishtirokchi topilmadi.";
    pr_call('sendMessage', array('chat_id' => $g['chat_id'], 'text' => $t, 'reply_parameters' => array('message_id' => (int)$g['msg_id'], 'allow_sending_without_reply' => true)));
    pr_call('editMessageReplyMarkup', array('chat_id' => $g['chat_id'], 'message_id' => (int)$g['msg_id'], 'reply_markup' => gw_kb($id, '✅ Konkurs yakunlandi (' . (int)$g['n'] . ')')));
    foreach ($win as $w) pr_call('sendMessage', array('chat_id' => $w['user_id'], 'text' => "🎉 Tabriklaymiz! Siz konkursda g'olib bo'ldingiz!\n\n" . mb_substr($g['title'], 0, 300)));
    q('UPDATE giveaways SET result=? WHERE id=?', array(json_encode($win), $id));
    return true;
}
function gw_run($lim) {
    foreach (q("SELECT id FROM giveaways WHERE status='active' AND ends_at<=? LIMIT " . (int)$lim, array(date('Y-m-d H:i:s')))->fetchAll(PDO::FETCH_COLUMN) as $id) gw_finish($id);
    foreach (q("SELECT id, chat_id, msg_id, n FROM giveaways WHERE status='active' AND n<>shown_n LIMIT " . (int)$lim)->fetchAll() as $g) {   /* tugmadagi sonni yangilash */
        pr_call('editMessageReplyMarkup', array('chat_id' => $g['chat_id'], 'message_id' => (int)$g['msg_id'], 'reply_markup' => gw_kb($g['id'], '🎁 Ishtirok etish (' . (int)$g['n'] . ')')));
        q('UPDATE giveaways SET shown_n=? WHERE id=?', array($g['n'], $g['id']));
    }
}
/* ---- Taklif havolalari reytingi ---- */
function ref_top($cid, $lim) {
    return q('SELECT r.user_id, r.joins, COALESCE(NULLIF(u.name, \'\'), CONCAT(\'ID \', r.user_id)) AS name, u.username FROM ref_links r LEFT JOIN users u ON u.id=r.user_id WHERE r.chat_id=? AND r.joins>0 ORDER BY r.joins DESC, r.created_at LIMIT ' . (int)$lim, array($cid))->fetchAll();
}
function ref_top_text($cid) {
    $top = ref_top($cid, 10); if (!$top) return "🔗 Taklif havolalari reytingi hali bo'sh.\n\nShaxsiy havolangizni olish: @" . BOT_USERNAME . " → Menyu → 🔗 Taklif havolalari";
    $t = "🏆 Eng ko'p odam taklif qilganlar:\n\n"; $md = array('🥇', '🥈', '🥉');
    foreach ($top as $i => $r) $t .= (isset($md[$i]) ? $md[$i] : ($i + 1) . '.') . ' ' . $r['name'] . ' — ' . (int)$r['joins'] . " ta\n";
    return $t . "\nShaxsiy havolangiz: @" . BOT_USERNAME . " → Menyu → 🔗 Taklif havolalari";
}
/* ---- Hijriy sana (API bo'lmasa — arifmetik hisob, 1 kun farq bo'lishi mumkin) ---- */
function hijri_calc($ymd) {
    list($y, $m, $d) = array_map('intval', explode('-', $ymd));
    $a = intdiv(14 - $m, 12); $yy = $y + 4800 - $a; $mm = $m + 12 * $a - 3;
    $jd = $d + intdiv(153 * $mm + 2, 5) + 365 * $yy + intdiv($yy, 4) - intdiv($yy, 100) + intdiv($yy, 400) - 32045;
    $l = $jd - 1948440 + 10632; $n = intdiv($l - 1, 10631); $l = $l - 10631 * $n + 354;
    $j = intdiv(10985 - $l, 5316) * intdiv(50 * $l, 17719) + intdiv($l, 5670) * intdiv(43 * $l, 15238);
    $l = $l - intdiv(30 - $j, 15) * intdiv(17719 * $j, 50) - intdiv($j, 16) * intdiv(15238 * $j, 43) + 29;
    $hm = intdiv(24 * $l, 709); $hd = $l - intdiv(709 * $hm, 24); $hy = 30 * $n + $j - 30;
    $M = array(1 => 'Muharram', 'Safar', 'Rabiul avval', 'Rabiul oxir', 'Jumodul avval', 'Jumodul oxir', 'Rajab', 'Sha\'bon', 'Ramazon', 'Shavvol', 'Zulqa\'da', 'Zulhijja');
    return $hd . ' ' . $M[$hm] . ' ' . $hy . ' h.';
}
function hijri_today() {
    $h = q('SELECT hijri FROM prayer_cache WHERE region=? AND day=? AND hijri<>\'\'', array('Toshkent', date('Y-m-d')))->fetchColumn();
    return $h ? (string)$h : hijri_calc(date('Y-m-d'));
}
/* Bosh sahifa: 12 viloyat markazi + Toshkent va Nukus — bitta namoz vaqti. Namoz kirganidan 30 daqiqa o'tgach keyingisi ko'rsatiladi (Toshkent vaqti bo'yicha) */
define('PR_HOME', "Toshkent,Andijon,Namangan,Farg'ona,Guliston,Jizzax,Samarqand,Navoiy,Buxoro,Qarshi,Termiz,Urganch");   /* bosh sahifada faqat 12 viloyat (markaz shahri vaqti bilan); shaharlar — «Namoz vaqtlari» da hudud tanlab */
$PR_HOME_VIL = array('Guliston' => 'Sirdaryo', 'Qarshi' => 'Qashqadaryo', 'Termiz' => 'Surxondaryo', 'Urganch' => 'Xorazm');   /* markaz shahri => viloyat nomi */
function pr_home() {
    global $PR_K, $PR_REG, $PR_HOME_VIL;
    $regs = array(); foreach (explode(',', PR_HOME) as $w) foreach ($PR_REG as $v => $l) foreach ($l as $k => $n) if ($n === $w) $regs[$k] = isset($PR_HOME_VIL[$n]) ? $PR_HOME_VIL[$n] : $n;
    $now = time(); $today = date('Y-m-d'); $ref = pr_get('Toshkent', $today);
    if (!$ref['ok']) return array('ok' => false, 'msg' => $ref['error']);
    $kind = null; $day = $today;
    foreach (array('bomdod', 'peshin', 'asr', 'shom', 'xufton') as $k) {
        if ($now < strtotime($today . ' ' . $ref['times'][$k]) + 1800) { $kind = $k; break; }
    }
    if ($kind === null) { $kind = 'bomdod'; $day = date('Y-m-d', $now + 86400); }   /* Xuftondan keyin — ertangi Bomdod */
    $rows = array(); $calc = false; $tt = null;
    foreach ($regs as $r => $n) {
        $pt = pr_get($r, $day); if (!$pt['ok']) continue;
        $rows[] = array('r' => $r, 'n' => $n, 't' => $pt['times'][$kind]); $calc = $calc || !empty($pt['calc']);
        if ($r === 'Toshkent') $tt = strtotime($day . ' ' . $pt['times'][$kind]);
    }
    if ($tt === null) $tt = strtotime($today . ' ' . $ref['times'][$kind]);
    return array('ok' => true, 'kind' => $kind, 'name' => $PR_K[$kind][0], 'icon' => $PR_K[$kind][1], 'tomorrow' => $day !== $today, 'started' => $now >= $tt,
        'mins' => (int)ceil(abs($tt - $now) / 60), 'rows' => $rows, 'calc' => $calc, 'date' => date('d.m.Y', strtotime($day)));
}
/* Har bir namoz kirganidan 30 daqiqa o'tgach (Toshkent vaqti) — «🕌 Namoz vaqtlari» yoqilgan chatlarga rasm. Har chatga har vaqtda bir marta. */
function pimg_run($lim) {
    $today = date('Y-m-d'); $ref = pr_get('Toshkent', $today); if (!$ref['ok']) return 0;
    $now = time(); $slot = null;
    foreach (array('bomdod', 'peshin', 'asr', 'shom', 'xufton') as $k) { $t = strtotime($today . ' ' . $ref['times'][$k]) + 1800; if ($now >= $t && $now < $t + 1200) $slot = $today . ':' . $k; }
    if ($slot === null) return 0;   /* cron 20 daqiqadan ko'p kechiksa — o'tkazib yuboriladi */
    $rows = q("SELECT id, chat_id, owner FROM chats WHERE send_c=1 AND status='approved' AND blocked=0 AND paused<" . time() . " AND (pi_key IS NULL OR pi_key<>?) ORDER BY id LIMIT " . (int)$lim, array($slot))->fetchAll();
    if (!$rows) return 0;
    $h = pr_home(); $png = png_prayer($h); if ($png === false) return 0;
    $cap = pimg_cap($h); $fid = null; $n = 0;
    foreach ($rows as $c) {
        if (q('UPDATE chats SET pi_key=? WHERE id=? AND (pi_key IS NULL OR pi_key<>?)', array($slot, $c['id'], $slot))->rowCount() !== 1) continue;
        $cc = owner_cap($c['owner'], 'c', $cap, array('{namoz}' => ($h['tomorrow'] ? 'Ertaga ' : '') . $h['name'], '{sana}' => $h['date']));
        $r = $fid ? pr_call('sendPhoto', array('chat_id' => $c['chat_id'], 'photo' => $fid) + ($cc !== '' ? array('caption' => $cc) : array())) : tg_photo($c['chat_id'], $png, $cc);
        if (!empty($r['ok']) && !$fid && !empty($r['result']['photo'])) { $p = end($r['result']['photo']); $fid = $p['file_id']; }   /* keyingilariga qayta yuklamasdan */
        q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($c['id'], !empty($r['ok']) ? 1 : 0, mb_substr('namoz rasmi' . (!empty($r['ok']) ? '' : ': ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi')), 0, 255)));
        if (empty($r['ok']) && isset($r['description'])) chat_lost($c['id'], $r['description']);
        if (!empty($r['ok'])) $n++;
        usleep(200000);
    }
    return $n;
}
/* Har daqiqalik cron: namoz + postlar + kapcha + vaqtinchalik xabarlar + statistika + hisobot + konkurslar */
/* Bot kanal/guruhga administrator qilinsa — avtomatik ro'yxatga olinadi va tasdiqlanadi; chiqarilsa — to'xtatiladi */
function bot_member($cm) {
    $ch = $cm['chat']; $type = isset($ch['type']) ? $ch['type'] : '';
    if (!in_array($type, array('channel', 'group', 'supergroup'), true)) return;
    $cid = $ch['id']; $ctype = $type === 'channel' ? 'Kanal' : 'Guruh';
    $st = isset($cm['new_chat_member']['status']) ? $cm['new_chat_member']['status'] : ''; $nm = $cm['new_chat_member'];
    $title = !empty($ch['username']) ? '@' . $ch['username'] : mb_substr(trim(isset($ch['title']) ? (string)$ch['title'] : ''), 0, 40) . ' (' . $cid . ')';
    if (in_array($st, array('left', 'kicked'), true) || ($st === 'administrator' && $ctype === 'Kanal' && empty($nm['can_post_messages']))) {
        if (q("UPDATE chats SET status='noperm', auto_on=0 WHERE chat_id=? AND status IN ('approved','pending')", array($cid))->rowCount() > 0)
            chat_alert($title, in_array($st, array('left', 'kicked'), true) ? 'bot chiqarib yuborildi' : 'botdan «Xabar joylash» huquqi olindi');
        q('UPDATE group_guard SET enabled=0 WHERE chat_id=?', array($cid));
        return;
    }
    if ($st !== 'administrator') return;   /* oddiy a'zo qilib qo'shilsa — kutiladi */
    $uid = isset($cm['from']['id']) ? (int)$cm['from']['id'] : 0; $fu = isset($cm['from']) ? $cm['from'] : array();
    if (!$uid || !empty($fu['is_bot'])) {   /* anonim admin qo'shgan bo'lsa — egasi (creator) olinadi */
        $ad = pr_call('getChatAdministrators', array('chat_id' => $cid)); $uid = 0;
        foreach (!empty($ad['ok']) ? $ad['result'] : array() as $x) if ($x['status'] === 'creator' && empty($x['user']['is_bot'])) { $uid = (int)$x['user']['id']; $fu = $x['user']; }
        if (!$uid) return;
    }
    q('INSERT IGNORE INTO users (id,username,name,created_at,last_seen) VALUES (?,?,?,NOW(),NOW())', array($uid, isset($fu['username']) ? $fu['username'] : '', uname($fu)));
    $old = q('SELECT id, status, blocked FROM chats WHERE chat_id=?', array($cid))->fetchAll();
    foreach ($old as $o) if ($o['status'] === 'rejected' || $o['blocked']) return;   /* admin rad etgan yoki bloklagan bo'lsa — avtomatik tasdiqlanmaydi */
    if ($old) q("UPDATE chats SET status='approved', username=?, auto_on=IF(last_post_at IS NULL OR send_a=1 OR send_b=1,1,0) WHERE chat_id=?", array($title, $cid));
    else q("INSERT INTO chats (owner,chat_id,username,ctype,status,auto_on,interval_h,send_a,send_b,send_c,dp_on,wx_on,bt_on,ev_on,created_at) VALUES (?,?,?,?,'approved',1,3,1,1,1,1,1,1,1,NOW())", array($uid, $cid, $title, $ctype));   /* faqat admin qilish orqali ulangan yangi chat — barcha xabarlar yoqiq */
    if ($ctype === 'Guruh') q('INSERT INTO group_guard (chat_id,enabled,opts,noad,updated_at) VALUES (?,1,?,1,?) ON DUPLICATE KEY UPDATE enabled=1', array($cid, json_encode(guard_def()), date('Y-m-d H:i:s')));
    if (!$old) {
        pr_call('sendMessage', array('chat_id' => $uid, 'text' => '✅ ' . ($ctype === 'Kanal' ? 'Kanal' : 'Guruh') . ' ' . $title . " botga ulandi va tasdiqlandi!\n\n" . "Avtomatik yoqildi:\n🏛 Dollar kursi + 📋 Markaziy bank kurslari (har 3 soatda)\n🕌 Namoz vaqtlari (har namozdan 30 daqiqa keyin)\n🌅 Ertalabki post (har kuni 6:00)" . ($ctype === 'Kanal' ? '' : "\n🛡 Guruh himoyasi") . "\n\nKeraksizini o'chirish yoki oraliqni o'zgartirish — ilovada «⚙️ Sozlash».",
            'reply_markup' => array('inline_keyboard' => array(array(array('text' => '⚙️ Sozlash', 'web_app' => array('url' => APP_URL)))))));
        notify_admins('🆕 Yangi ' . mb_strtolower($ctype) . ' avtomatik ulandi: ' . $title . "\n👤 " . uname($fu) . (isset($fu['username']) ? ' (@' . $fu['username'] . ')' : '') . ' · ID ' . $uid);
    }
}
/* Admin Telegram'da tugma bosdi: to'lovni tasdiqlash/rad etish, e'lonni yuborish/rad etish */
function ad_send_step($id, $upl, $audit = null) {   /* e'lonning navbatdagi 30 ta qabul qiluvchisiga yuboradi */
    $o = q('SELECT * FROM ad_orders WHERE id=?', array($id))->fetch(); if (!$o) return array('ok' => false, 'error' => 'Topilmadi', 'code' => 404);
    if ($o['status'] === 'pending') {
        if (q("UPDATE ad_orders SET status='sending' WHERE id=? AND status='pending'", array($id))->rowCount() === 1 && $audit) $audit('ad_send', '#' . $id . ' ' . $o['kind']);
        $o = q('SELECT * FROM ad_orders WHERE id=?', array($id))->fetch();
    }
    if ($o['status'] !== 'sending') return array('ok' => false, 'error' => 'Bu buyurtmani yuborib bo\'lmaydi', 'code' => 409);
    $aud = ad_aud($o['kind']); $total = (int)q('SELECT COUNT(*) ' . $aud[0])->fetchColumn(); $B = 30; $t0 = microtime(true);
    $ids = q('SELECT ' . $aud[1] . ' ' . $aud[0] . ' ORDER BY id LIMIT ' . $B . ' OFFSET ' . (int)$o['done'])->fetchAll(PDO::FETCH_COLUMN);
    $sent = 0; $failed = 0; $done = (int)$o['done'];
    $cap = mb_substr("📢 E'lon\n\n" . $o['body'], 0, 1024); $hasImg = !empty($o['image']);
    if ($ids && $hasImg && empty($o['file_id'])) {
        /* rasm bir marta adminga yuklanadi (nusxa), keyin hammaga file_id bilan ketadi */
        $r = tg_photo($upl, base64_decode($o['image']), $cap, 'jpg');
        if (empty($r['ok']) || empty($r['result']['photo'])) return array('ok' => false, 'error' => 'Rasm yuklanmadi: ' . (isset($r['description']) ? $r['description'] : 'xato') . '. Botga /start bosganingizni tekshiring.', 'code' => 502);
        $ph = $r['result']['photo']; $last = end($ph); $o['file_id'] = $last['file_id'];
        q('UPDATE ad_orders SET file_id=? WHERE id=?', array($o['file_id'], $id));
    }
    if ($ids) {
        if (q('UPDATE ad_orders SET done=done+? WHERE id=? AND done=?', array(count($ids), $id, $done))->rowCount() === 1) {
            $items = array();
            foreach ($ids as $i => $cid) $items[$i] = $hasImg ? array('chat_id' => $cid, 'photo' => $o['file_id'], 'caption' => $cap) : array('chat_id' => $cid, 'text' => $cap, 'disable_web_page_preview' => true);
            $dh = $o['kind'] !== 'users' ? (int)setting('ad_del_h', '0') : 0;
            foreach (tg_multi($hasImg ? 'sendPhoto' : 'sendMessage', $items) as $k => $r) { if (!empty($r['ok'])) { $sent++; if ($dh && isset($r['result']['message_id'])) autodel_add($items[$k]['chat_id'], $r['result']['message_id'], $dh); } else $failed++; }
            q('UPDATE ad_orders SET sent_n=sent_n+?, fail_n=fail_n+? WHERE id=?', array($sent, $failed, $id));
            $done += count($ids);
        }
    }
    $fin = !$ids || $done >= $total;
    if ($fin) {
        q("UPDATE ad_orders SET status='sent', decided_at=NOW() WHERE id=?", array($id));
        $f = q('SELECT sent_n,fail_n FROM ad_orders WHERE id=?', array($id))->fetch();
        /* e'lon beruvchiga soni aytilmaydi — faqat «yuborildi» va e'lon namunasi (foydalanuvchilarga e'londa u o'zi ham oladi) */
        tg('sendMessage', array('chat_id' => $o['user_id'], 'text' => "✅ E'lon buyurtmangiz #" . $id . " yuborildi." . ($o['kind'] !== 'users' ? "\n\nQuyida e'loningiz namunasi 👇" : '')));
        if ($o['kind'] !== 'users') {
            if (!empty($o['file_id'])) tg('sendPhoto', array('chat_id' => $o['user_id'], 'photo' => $o['file_id'], 'caption' => $cap));
            elseif ($hasImg) tg_photo($o['user_id'], base64_decode($o['image']), $cap, 'jpg');
            else tg('sendMessage', array('chat_id' => $o['user_id'], 'text' => $cap, 'disable_web_page_preview' => true));
        }
    } else { $el = microtime(true) - $t0; if ($el < 1.05) usleep((int)((1.05 - $el) * 1000000)); }
    $f = q('SELECT sent_n,fail_n FROM ad_orders WHERE id=?', array($id))->fetch();
    return array('ok' => true, 'total' => $total, 'done' => $done, 'sent' => (int)$f['sent_n'], 'failed' => (int)$f['fail_n'], 'finished' => $fin);
}
/* ---------- Guruhda majburiy obuna: yozish uchun kanalga obuna bo'lish shart ---------- */
function fs_install() {
    db()->exec("CREATE TABLE IF NOT EXISTS group_fsub (chat_ref INT PRIMARY KEY, ch_id BIGINT NOT NULL, ch_user VARCHAR(64) NOT NULL, ch_title VARCHAR(120) NOT NULL DEFAULT '', on_ TINYINT NOT NULL DEFAULT 1, blocked_n INT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    db()->exec("CREATE TABLE IF NOT EXISTS fsub_ok (ch BIGINT NOT NULL, uid BIGINT NOT NULL, at INT NOT NULL DEFAULT 0, warn_at INT NOT NULL DEFAULT 0, PRIMARY KEY (ch, uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
function fs_member($ch, $uid) {   /* true — obunachi, false — yo'q, null — tekshirib bo'lmadi (bot kanalda admin emas) */
    $r = pr_call('getChatMember', array('chat_id' => $ch, 'user_id' => $uid)); if (empty($r['ok'])) return null;
    $s = $r['result']['status']; return in_array($s, array('creator', 'administrator', 'member'), true) || ($s === 'restricted' && !empty($r['result']['is_member']));
}
function fs_handle($m) {   /* true — xabar o'chirildi (obuna bo'lmagan) */
    $cid = $m['chat']['id']; $from = isset($m['from']['id']) ? (int)$m['from']['id'] : 0;
    if (!$from || !empty($m['from']['is_bot']) || !empty($m['is_automatic_forward']) || isset($m['sender_chat']) || !empty($m['new_chat_members']) || !empty($m['left_chat_member']) || $from === 136817688 || $from === 777000) return false;
    $f = q("SELECT f.* FROM group_fsub f JOIN chats c ON c.id=f.chat_ref WHERE c.chat_id=? AND f.on_=1 AND c.status='approved' AND c.blocked=0 LIMIT 1", array($cid))->fetch(); if (!$f) return false;
    $c = q('SELECT at, warn_at FROM fsub_ok WHERE ch=? AND uid=?', array($f['ch_id'], $from))->fetch();
    if ($c && (int)$c['at'] > time() - 1800) return false;   /* obunasi 30 daqiqa eslab qolinadi */
    if (guard_is_admin($cid, $from)) return false;   /* guruh adminlariga tegilmaydi */
    $mem = fs_member($f['ch_id'], $from); if ($mem === null) return false;   /* tekshirib bo'lmasa — xabarga tegilmaydi */
    if ($mem) { q('INSERT INTO fsub_ok (ch,uid,at) VALUES (?,?,?) ON DUPLICATE KEY UPDATE at=VALUES(at)', array($f['ch_id'], $from, time())); return false; }
    pr_call('deleteMessage', array('chat_id' => $cid, 'message_id' => $m['message_id'])); $GLOBALS['GUARD_DEL'] = 1;
    q('UPDATE group_fsub SET blocked_n=blocked_n+1 WHERE chat_ref=?', array($f['chat_ref']));
    if (!$c || (int)$c['warn_at'] < time() - 120) {   /* bir odamga ogohlantirish — 2 daqiqada bir marta */
        q('INSERT INTO fsub_ok (ch,uid,at,warn_at) VALUES (?,?,0,?) ON DUPLICATE KEY UPDATE warn_at=VALUES(warn_at)', array($f['ch_id'], $from, time()));
        $nm = trim((isset($m['from']['first_name']) ? $m['from']['first_name'] : '') . ' ' . (isset($m['from']['last_name']) ? $m['from']['last_name'] : ''));
        say_tmp($cid, '👋 ' . ($nm !== '' ? $nm : 'Hurmatli a\'zo') . ", guruhda yozish uchun avval " . ($f['ch_title'] !== '' && ltrim($f['ch_title'], '@') !== $f['ch_user'] ? $f['ch_title'] . ' (@' . $f['ch_user'] . ')' : '@' . $f['ch_user']) . " kanaliga obuna bo'ling.", 120,
            array('reply_markup' => array('inline_keyboard' => array(array(array('text' => '📢 Obuna bo\'lish', 'url' => 'https://t.me/' . $f['ch_user'])), array(array('text' => '✅ Obuna bo\'ldim', 'callback_data' => 'fs:' . $f['chat_ref'] . ':' . $from))))));
    }
    return true;
}
function fs_cb($cq, $ref, $uid, $ans) {   /* «✅ Obuna bo'ldim» tugmasi */
    if ((int)$cq['from']['id'] !== $uid) { $ans('Bu tugma siz uchun emas', true); return; }
    $f = q('SELECT * FROM group_fsub WHERE chat_ref=?', array($ref))->fetch(); if (!$f) { $ans(''); return; }
    if (fs_member($f['ch_id'], $uid)) {
        q('INSERT INTO fsub_ok (ch,uid,at) VALUES (?,?,?) ON DUPLICATE KEY UPDATE at=VALUES(at)', array($f['ch_id'], $uid, time()));
        if (isset($cq['message']['message_id'])) pr_call('deleteMessage', array('chat_id' => $cq['message']['chat']['id'], 'message_id' => $cq['message']['message_id']));
        $ans('✅ Rahmat! Endi guruhda yozishingiz mumkin.');
    } else $ans("❗ Hali obuna bo'lmagansiz. Avval «📢 Obuna bo'lish» ni bosing.", true);
}
/* ---------- Guruh boshqaruvi: /report, /yop, /och, /ishonch, /eslat, /reyting; qora ro'yxat; sekin rejim; media vaqti; kalit so'z; admin jurnali ---------- */
function chat_mgrs($cid) {   /* guruh/kanal egasi va hamkor adminlari (botga /start bosganlar) */
    $ids = array();
    foreach (q("SELECT id, owner FROM chats WHERE chat_id=? AND blocked=0", array($cid))->fetchAll() as $c) {
        $ids[(string)$c['owner']] = 1;
        foreach (q('SELECT user_id FROM chat_admins WHERE chat_ref=?', array($c['id']))->fetchAll(PDO::FETCH_COLUMN) as $x) $ids[(string)$x] = 1;
    }
    return array_keys($ids);
}
function grp_admin_ids($cid) {   /* shikoyat oladiganlar: egasi, hamkorlari va guruh adminlari */
    guard_is_admin($cid, 0); $ids = array_flip(chat_mgrs($cid));
    $row = q('SELECT ids FROM guard_admins WHERE chat_id=?', array($cid))->fetchColumn();
    foreach (explode(',', (string)$row) as $x) if ($x !== '' && $x !== (string)(int)strtok(BOT_TOKEN, ':')) $ids[$x] = 1;
    return array_slice(array_keys($ids), 0, 15);
}
function msg_link($chat, $mid) {
    if (!empty($chat['username'])) return 'https://t.me/' . $chat['username'] . '/' . $mid;
    $id = (string)$chat['id']; return strpos($id, '-100') === 0 ? 'https://t.me/c/' . substr($id, 4) . '/' . $mid : '';
}
function dur_txt($sec) { return $sec >= 86400 ? round($sec / 86400, 1) . ' kun' : ($sec >= 3600 ? round($sec / 3600, 1) . ' soat' : round($sec / 60) . ' daqiqa'); }
function alog($cid, $by, $act, $tu, $detail) {   /* adminlar harakati jurnali */
    q('INSERT INTO admin_log (chat_id,admin_id,admin_name,action,target_id,target_name,detail,at) VALUES (?,?,?,?,?,?,?,?)',
        array($cid, isset($by['id']) ? (int)$by['id'] : 0, mb_substr(uname($by ?: array()), 0, 80), $act, $tu && isset($tu['id']) ? (int)$tu['id'] : null, $tu ? mb_substr(uname($tu), 0, 80) : '', mb_substr((string)$detail, 0, 200), time()));
    if (mt_rand(1, 200) === 1) q('DELETE FROM admin_log WHERE at<?', array(time() - 90 * 86400));
}
function gban_has($uid) { return (bool)q('SELECT 1 FROM gban WHERE user_id=?', array((int)$uid))->fetchColumn(); }
function gban_add($uid, $name, $cid, $why) { q('INSERT INTO gban (user_id,name,chat_id,reason,at) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)', array((int)$uid, mb_substr($name, 0, 80), $cid, mb_substr($why, 0, 120), time())); }
function guard_trusted($cid, $uid) { return (bool)q('SELECT 1 FROM guard_trust WHERE chat_id=? AND user_id=?', array($cid, (int)$uid))->fetchColumn(); }
function guard_slow($cid, $uid, $cfg) {   /* oxirgi qabul qilingan xabardan beri sekin rejim vaqti o'tmagan */
    $l = (int)q('SELECT last_at FROM guard_members WHERE chat_id=? AND user_id=?', array($cid, (int)$uid))->fetchColumn();
    return $l && time() - $l < max(5, (int)$cfg['slow_s']) && !guard_is_admin($cid, $uid);
}
function guard_media_any($m) { foreach (array('photo', 'video', 'animation', 'sticker', 'document', 'audio', 'voice', 'video_note') as $k) if (isset($m[$k])) return true; return false; }
function in_win($f, $t) { $n = date('H:i'); if ($f === $t) return false; return $f < $t ? ($n >= $f && $n < $t) : ($n >= $f || $n < $t); }
function week_msg($cid, $u) {   /* haftalik TOP-10 uchun */
    if (empty($u['id']) || !empty($u['is_bot'])) return;
    q('INSERT INTO member_week (chat_id,user_id,wk,n,name) VALUES (?,?,?,1,?) ON DUPLICATE KEY UPDATE n=n+1, name=VALUES(name)', array($cid, (int)$u['id'], date('o-W'), mb_substr(uname($u), 0, 80)));
}
function grp_unlock($cid) {
    $l = json_decode((string)setting('lock_' . $cid, ''), true);
    $p = is_array($l) && !empty($l['p']) ? $l['p'] : array_fill_keys(array('can_send_messages', 'can_send_audios', 'can_send_documents', 'can_send_photos', 'can_send_videos', 'can_send_video_notes', 'can_send_voice_notes', 'can_send_polls', 'can_send_other_messages', 'can_add_web_page_previews'), true);
    $r = pr_call('setChatPermissions', array('chat_id' => $cid, 'permissions' => $p, 'use_independent_chat_permissions' => true));
    q('DELETE FROM settings WHERE k=?', array('lock_' . $cid));
    if (!empty($r['ok'])) pr_call('sendMessage', array('chat_id' => $cid, 'text' => '🔓 Guruh ochildi. Endi hamma yoza oladi.'));
    return !empty($r['ok']);
}
function lock_run() {   /* muddatli /yop — vaqti kelganda o'zi ochiladi */
    $n = 0; foreach (q("SELECT k, v FROM settings WHERE k LIKE 'lock\\_%'")->fetchAll() as $r) { $l = json_decode($r['v'], true); if (is_array($l) && !empty($l['u']) && $l['u'] <= time()) { grp_unlock(substr($r['k'], 5)); $n++; } }
    return $n;
}
function rem_next($rep, $hm, $from) {   /* takrorlanuvchi eslatmaning keyingi vaqti */
    $t = strtotime(date('Y-m-d', $from) . ' ' . $hm);
    if ($rep === 'day') { while ($t <= $from) $t += 86400; return $t; }
    $d = (int)$rep; while ($t <= $from || (int)date('N', $t) !== $d) $t += 86400; return $t;
}
function rem_run() {
    $n = 0;
    foreach (q('SELECT * FROM reminders WHERE active=1 AND run_at<=? ORDER BY run_at LIMIT 30', array(time()))->fetchAll() as $r) {
        if ($r['rep'] === '') { if (q('UPDATE reminders SET active=0 WHERE id=? AND active=1', array($r['id']))->rowCount() !== 1) continue; }
        elseif (q('UPDATE reminders SET run_at=? WHERE id=? AND run_at=?', array(rem_next($r['rep'], $r['hm'], time()), $r['id'], $r['run_at']))->rowCount() !== 1) continue;
        $x = pr_call('sendMessage', array('chat_id' => $r['chat_id'], 'text' => "⏰ Eslatma\n\n" . $r['body'], 'disable_web_page_preview' => true));
        if (!empty($x['ok'])) $n++; elseif (isset($x['description']) && preg_match('/kicked|not found|not a member/i', $x['description'])) q('UPDATE reminders SET active=0 WHERE chat_id=?', array($r['chat_id']));
    }
    return $n;
}
function rem_when($r) { $W = array(1 => 'dushanba', 'seshanba', 'chorshanba', 'payshanba', 'juma', 'shanba', 'yakshanba'); return $r['rep'] === 'day' ? 'har kuni ' . $r['hm'] : ($r['rep'] !== '' ? 'har ' . $W[(int)$r['rep']] . ' ' . $r['hm'] : date('d.m H:i', $r['run_at'])); }
function rem_parse($arg) {   /* "30m matn" | "2s matn" | "1k matn" | "18:00 matn" | "har kuni 09:00 matn" | "har dushanba 09:00 matn" -> array(run_at, rep, hm, matn) yoki xato matni */
    $W = array('dushanba' => 1, 'seshanba' => 2, 'chorshanba' => 3, 'payshanba' => 4, 'juma' => 5, 'shanba' => 6, 'yakshanba' => 7);
    $a = trim($arg);
    if (preg_match('~^har\s+(kuni|dushanba|seshanba|chorshanba|payshanba|juma|shanba|yakshanba)\s+([01]?\d|2[0-3]):([0-5]\d)\s+(.+)$~isu', $a, $x)) {
        $rep = strtolower($x[1]) === 'kuni' ? 'day' : (string)$W[strtolower($x[1])]; $hm = sprintf('%02d:%s', $x[2], $x[3]);
        return array(rem_next($rep, $hm, time()), $rep, $hm, trim($x[4]));
    }
    if (preg_match('~^([01]?\d|2[0-3]):([0-5]\d)\s+(.+)$~su', $a, $x)) { $t = strtotime(date('Y-m-d') . ' ' . sprintf('%02d:%s', $x[1], $x[2])); if ($t <= time()) $t += 86400; return array($t, '', '', trim($x[3])); }
    if (preg_match('~^(\d{1,4})\s*(m|min|daq|daqiqa|s|soat|h|k|kun)\b\.?\s+(.+)$~isu', $a, $x)) {
        $u = strtolower($x[2]); $sec = (int)$x[1] * (in_array($u, array('m', 'min', 'daq', 'daqiqa'), true) ? 60 : (in_array($u, array('s', 'soat', 'h'), true) ? 3600 : 86400));
        if ($sec < 60 || $sec > 366 * 86400) return 'Muddat 1 daqiqadan 1 yilgacha bo\'lsin';
        return array(time() + $sec, '', '', trim($x[3]));
    }
    return "Format: /eslat 30m matn · /eslat 2s matn · /eslat 1k matn · /eslat 18:00 matn · /eslat har kuni 09:00 matn · /eslat har dushanba 09:00 matn\n(m — daqiqa, s — soat, k — kun)";
}
function grp_cmd($m) {   /* true — buyruq bajarildi */
    $t = isset($m['text']) ? trim((string)$m['text']) : '';
    if (!preg_match('~^/(report|yop|och|jim|ishonch|ishonchsiz|eslat|eslatmalar|eslat_ochir|reyting|manzil)(?:@(\w+))?(?:\s+(.*))?$~isu', $t, $x)) return false;
    if (!empty($x[2]) && strcasecmp($x[2], BOT_USERNAME) !== 0) return false;
    if (!isset($m['chat']['type']) || !in_array($m['chat']['type'], array('group', 'supergroup'), true)) return false;
    $cid = $m['chat']['id']; if (!q("SELECT 1 FROM chats WHERE chat_id=? AND status='approved' AND blocked=0", array($cid))->fetchColumn()) return false;   /* faqat botga ulangan guruhlar */
    $from = isset($m['from']['id']) ? (int)$m['from']['id'] : 0; $cmd = strtolower($x[1]); $arg = isset($x[3]) ? trim($x[3]) : '';
    $adm = (isset($m['sender_chat']['id']) && (string)$m['sender_chat']['id'] === (string)$cid) || ($from && guard_is_admin($cid, $from));
    $rt = isset($m['reply_to_message']) ? $m['reply_to_message'] : null; $tu = $rt && isset($rt['from']) ? $rt['from'] : null;
    tmp_add($cid, $m['message_id'], 5);   /* buyruq xabari tozalanadi */
    if ($cmd === 'report') {
        if (!$tu) { say_tmp($cid, 'ℹ️ Shikoyat uchun yomon xabarga javob (reply) qilib /report yozing.', 30); return true; }
        if ((int)setting('rpt_' . $cid . '_' . $from, '0') > time() - 60) return true; setset('rpt_' . $cid . '_' . $from, (string)time());
        $ln = msg_link($m['chat'], $rt['message_id']);
        $txt = "🚨 Shikoyat — " . (isset($m['chat']['title']) ? $m['chat']['title'] : $cid) . "\n👤 Kim: " . uname(isset($m['from']) ? $m['from'] : array()) . "\n🎯 Kimga: " . uname($tu) . ' (ID ' . (int)$tu['id'] . ")\n💬 " . mb_substr(msg_desc($rt), 0, 400) . ($arg !== '' ? "\n📝 Izoh: " . mb_substr($arg, 0, 200) : '') . ($ln !== '' ? "\n🔗 " . $ln : '');
        $n = 0; foreach (grp_admin_ids($cid) as $aid) { $r = pr_call('sendMessage', array('chat_id' => $aid, 'text' => $txt, 'disable_web_page_preview' => true)); if (!empty($r['ok'])) $n++; }
        say_tmp($cid, $n ? '✅ Shikoyat adminlarga yuborildi. Rahmat!' : "⚠️ Adminlarga yetkazib bo'lmadi — adminlar botga /start bosmagan.", 30);
        return true;
    }
    if ($cmd === 'reyting') { say_tmp($cid, rep_top_text($cid), 120); return true; }
    if ($cmd === 'manzil') {
        if ((int)setting('mz_' . $cid, '0') > time() - 30) return true; setset('mz_' . $cid, (string)time());
        $c = gcfg(q('SELECT cfg FROM group_guard WHERE chat_id=?', array($cid))->fetchColumn() ?: null);
        if (trim($c['addr']) === '' && trim($c['addr_geo']) === '') { say_tmp($cid, "ℹ️ Manzil hali kiritilmagan. Guruh egasi: ilova → 🛡 Guruh himoyasi → ⚙️ sozlamalar → 📍 Manzil.", 30); return true; }
        $tt = '📍 ' . (isset($m['chat']['title']) ? $m['chat']['title'] : 'Manzil') . (trim($c['addr']) !== '' ? "\n🏠 " . trim($c['addr']) : '') . (trim($c['addr_tel']) !== '' ? "\n📞 " . trim($c['addr_tel']) : '');
        if (preg_match('/(-?\d{1,2}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/', $c['addr_geo'], $gg)) {
            $r = pr_call('sendVenue', array('chat_id' => $cid, 'latitude' => (float)$gg[1], 'longitude' => (float)$gg[2], 'title' => mb_substr(isset($m['chat']['title']) ? $m['chat']['title'] : 'Manzil', 0, 60), 'address' => mb_substr(trim($c['addr']) !== '' ? trim($c['addr']) : $gg[1] . ', ' . $gg[2], 0, 120)));
            if (!empty($r['ok'])) tmp_add($cid, $r['result']['message_id'], 600);
        }
        say_tmp($cid, $tt, 600); return true;
    }
    if (!$adm) { if ($cmd !== 'eslatmalar') say_tmp($cid, 'ℹ️ Bu buyruq faqat guruh adminlari uchun.', 15); return true; }
    if ($cmd === 'yop' || $cmd === 'jim') {
        $sec = $cmd === 'jim' ? 600 : 0; if (preg_match('/^(\d{1,4})\s*(m|min|daq|s|soat|h|k|kun)\b/i', $arg, $y)) { $u = strtolower($y[2]); $sec = (int)$y[1] * (in_array($u, array('m', 'min', 'daq'), true) ? 60 : (in_array($u, array('s', 'soat', 'h'), true) ? 3600 : 86400)); $sec = max(60, min($sec, 30 * 86400)); }
        $txt = $cmd === 'jim' ? '🤐 Guruh ' . dur_txt($sec) . " jim rejimida — hamma biroz tinchlansin.\nVaqt tugagach o'zi ochiladi. Ochish: /och"
            : '🔒 Guruh vaqtincha yopildi' . ($sec ? ' (' . dur_txt($sec) . ', keyin o\'zi ochiladi)' : '') . ".\nHozircha faqat adminlar yoza oladi. Ochish: /och";
        if (!grp_lock($cid, $sec, $txt)) { say_tmp($cid, "⚠️ Yopib bo'lmadi: botga «Foydalanuvchilarni bloklash» huquqini bering.", 60); return true; }
        alog($cid, isset($m['from']) ? $m['from'] : array(), $cmd, null, $sec ? dur_txt($sec) : '');
        return true;
    }
    if ($cmd === 'och') { if (!grp_unlock($cid)) say_tmp($cid, "⚠️ Ochib bo'lmadi: botga «Foydalanuvchilarni bloklash» huquqini bering.", 60); alog($cid, isset($m['from']) ? $m['from'] : array(), 'och', null, ''); return true; }
    if ($cmd === 'ishonch' || $cmd === 'ishonchsiz') {
        if (!$tu || !empty($tu['is_bot'])) { say_tmp($cid, 'ℹ️ Kerakli odamning xabariga javob (reply) qilib /' . $cmd . ' yozing.', 30); return true; }
        if ($cmd === 'ishonch') { q('INSERT INTO guard_trust (chat_id,user_id,name,at) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)', array($cid, (int)$tu['id'], mb_substr(uname($tu), 0, 80), time())); say_tmp($cid, '✅ ' . uname($tu) . " ishonchli a'zolar ro'yxatiga qo'shildi — himoya uning xabarlariga tegmaydi.", 60); }
        else { q('DELETE FROM guard_trust WHERE chat_id=? AND user_id=?', array($cid, (int)$tu['id'])); say_tmp($cid, '☑️ ' . uname($tu) . " ishonchli a'zolar ro'yxatidan olindi.", 60); }
        alog($cid, isset($m['from']) ? $m['from'] : array(), $cmd, $tu, ''); return true;
    }
    if ($cmd === 'eslat') {
        $p = rem_parse($arg); if (is_string($p)) { say_tmp($cid, 'ℹ️ ' . $p, 90); return true; }
        if ($p[3] === '' || mb_strlen($p[3]) > 1000) { say_tmp($cid, 'ℹ️ Eslatma matni 1–1000 belgi bo\'lsin.', 30); return true; }
        if ((int)q('SELECT COUNT(*) FROM reminders WHERE chat_id=? AND active=1', array($cid))->fetchColumn() >= 20) { say_tmp($cid, 'ℹ️ Bir guruhda 20 tagacha faol eslatma bo\'ladi. /eslatmalar — ro\'yxat.', 30); return true; }
        q('INSERT INTO reminders (chat_id,run_at,rep,hm,body,by_user) VALUES (?,?,?,?,?,?)', array($cid, $p[0], $p[1], $p[2], $p[3], $from)); $rid = db()->lastInsertId();
        say_tmp($cid, '⏰ Eslatma #' . $rid . ' saqlandi: ' . rem_when(array('rep' => $p[1], 'hm' => $p[2], 'run_at' => $p[0])) . '. Ro\'yxat: /eslatmalar', 60);
        return true;
    }
    if ($cmd === 'eslatmalar') {
        $L = q('SELECT * FROM reminders WHERE chat_id=? AND active=1 ORDER BY run_at', array($cid))->fetchAll();
        say_tmp($cid, $L ? "⏰ Eslatmalar:\n" . implode("\n", array_map(function ($r) { return '#' . $r['id'] . ' · ' . rem_when($r) . ' — ' . mb_substr($r['body'], 0, 60); }, $L)) . "\n\nO'chirish: /eslat_ochir RAQAM" : 'ℹ️ Faol eslatma yo\'q. Qo\'shish: /eslat 18:00 matn', 120);
        return true;
    }
    if ($cmd === 'eslat_ochir') { $n = q('UPDATE reminders SET active=0 WHERE id=? AND chat_id=?', array((int)$arg, $cid))->rowCount(); say_tmp($cid, $n ? '🗑 Eslatma #' . (int)$arg . " o'chirildi." : 'ℹ️ Bunday eslatma topilmadi.', 30); return true; }
    return true;
}
function watch_handle($m) {   /* kuzatiladigan kalit so'z yozilsa — egasi va hamkorlariga shaxsan xabar */
    $text = isset($m['text']) ? (string)$m['text'] : (isset($m['caption']) ? (string)$m['caption'] : '');
    if ($text === '' || $text[0] === '/' || !empty($m['from']['is_bot']) || isset($m['sender_chat'])) return;
    $cid = $m['chat']['id']; $cfg = q('SELECT cfg FROM group_guard WHERE chat_id=?', array($cid))->fetchColumn(); if (!$cfg) return;
    $w = trim((string)gcfg($cfg)['watch']); if ($w === '') return;
    $low = mb_strtolower($text); $hit = '';
    foreach (preg_split('/[\n,]+/u', $w) as $k) { $k = trim(mb_strtolower($k)); if ($k !== '' && mb_strpos($low, $k) !== false) { $hit = $k; break; } }
    if ($hit === '' || guard_is_admin($cid, (int)$m['from']['id'])) return;
    $ln = msg_link($m['chat'], $m['message_id']);
    $t = "🗣 Kalit so'z «" . $hit . "» — " . (isset($m['chat']['title']) ? $m['chat']['title'] : $cid) . "\n👤 " . uname($m['from']) . (isset($m['from']['username']) ? ' (@' . $m['from']['username'] . ')' : '') . "\n💬 " . mb_substr($text, 0, 500) . ($ln !== '' ? "\n🔗 " . $ln : '');
    foreach (chat_mgrs($cid) as $aid) pr_call('sendMessage', array('chat_id' => $aid, 'text' => $t, 'disable_web_page_preview' => true));
}
/* ---------- Reputatsiya, haftalik TOP-10, a'zolar marrasi ---------- */
function rep_handle($m) {   /* «rahmat» yoki «+» javobi — javob olgan a'zoga ball */
    $text = isset($m['text']) ? trim((string)$m['text']) : '';
    if ($text === '' || mb_strlen($text) > 60 || empty($m['reply_to_message']['from']) || empty($m['from']['id'])) return false;
    if (!preg_match('~^(\+1?|👍|🙏|🤝|(katta\s+)?ra[hx]mat(lar)?|tashakkur|рахмат|раҳмат|катта рахмат|спасибо|спс|thanks?( you)?)(?=$|[\s!.,)👍🙏🤝❤])~iu', mb_strtolower($text))) return false;
    $cid = $m['chat']['id']; $o = q('SELECT opts FROM group_guard WHERE chat_id=? AND enabled=1', array($cid))->fetchColumn(); $o = $o ? json_decode($o, true) : array();
    if (empty($o['rep'])) return false;
    $giver = (int)$m['from']['id']; $tu = $m['reply_to_message']['from']; $rid = (int)$tu['id'];
    if (!empty($m['from']['is_bot']) || !empty($tu['is_bot']) || $rid === $giver || in_array($rid, array(777000, 136817688, 1087968824), true)) return false;
    $last = (int)q('SELECT at FROM rep_give WHERE chat_id=? AND giver=? AND receiver=?', array($cid, $giver, $rid))->fetchColumn();
    if ($last > time() - 3600) return true;   /* bir odamga soatiga bir marta */
    q('INSERT INTO rep_give (chat_id,giver,receiver,at) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE at=VALUES(at)', array($cid, $giver, $rid, time()));
    q('INSERT INTO rep (chat_id,user_id,name,n) VALUES (?,?,?,1) ON DUPLICATE KEY UPDATE n=n+1, name=VALUES(name)', array($cid, $rid, mb_substr(uname($tu), 0, 80)));
    $n = (int)q('SELECT n FROM rep WHERE chat_id=? AND user_id=?', array($cid, $rid))->fetchColumn();
    say_tmp($cid, '⭐ ' . uname($tu) . ' +1 (jami ' . $n . ')', 20);
    return true;
}
function rep_top_text($cid) {
    $L = q('SELECT name, n FROM rep WHERE chat_id=? ORDER BY n DESC LIMIT 10', array($cid))->fetchAll();
    if (!$L) return "⭐ Reputatsiya reytingi hali bo'sh.\nFoydali xabarga «rahmat» yoki «+» deb javob bering — muallifga ball qo'shiladi.";
    $md = array('🥇', '🥈', '🥉'); $t = "⭐ Reputatsiya reytingi:\n";
    foreach ($L as $i => $x) $t .= "\n" . (isset($md[$i]) ? $md[$i] : ($i + 1) . '.') . ' ' . $x['name'] . ' — ' . (int)$x['n'];
    return $t;
}
function top10_run() {   /* har dushanba 10:00 dan keyin — o'tgan haftaning eng faol a'zolari */
    if (date('N') !== '1' || date('H:i') < '10:00') return 0;
    $wk = date('o-W', strtotime('-7 days')); $n = 0;
    foreach (q("SELECT g.chat_id, g.opts FROM group_guard g JOIN chats c ON c.chat_id=g.chat_id AND c.status='approved' AND c.blocked=0 WHERE g.enabled=1 GROUP BY g.chat_id, g.opts")->fetchAll() as $g) {
        $o = json_decode($g['opts'], true); if (empty($o['top10'])) continue;
        $k = 'top_' . $g['chat_id'] . '_' . $wk; if (setting($k, '') !== '') continue; setset($k, '1');
        $L = q('SELECT user_id, name, n FROM member_week WHERE chat_id=? AND wk=? ORDER BY n DESC LIMIT 10', array($g['chat_id'], $wk))->fetchAll(); if (count($L) < 3) continue;
        $md = array('🥇', '🥈', '🥉'); $t = "🏆 <b>O'tgan haftaning eng faol a'zolari</b>\n";
        foreach ($L as $i => $x) $t .= "\n" . (isset($md[$i]) ? $md[$i] : ($i + 1) . '.') . ' <a href="tg://user?id=' . (int)$x['user_id'] . '">' . htmlspecialchars($x['name'], ENT_QUOTES, 'UTF-8') . '</a> — ' . (int)$x['n'] . ' ta xabar';
        $t .= "\n\nFaolligingiz uchun rahmat! 💬 Keyingi haftada TOP-10 da siz ham bo'ling!";
        if (!empty(pr_call('sendMessage', array('chat_id' => $g['chat_id'], 'text' => $t, 'parse_mode' => 'HTML'))['ok'])) $n++;
        if ($n >= 40) break;
    }
    if (mt_rand(1, 10) === 1) q('DELETE FROM member_week WHERE wk<?', array(date('o-W', strtotime('-8 weeks'))));
    return $n;
}
function ms_run() {   /* kanal/guruh a'zolari marrasi — 1 000, 5 000, 10 000 ... ga yetganda tabrik */
    $T = array(100, 250, 500, 1000, 2000, 3000, 5000, 7500, 10000, 15000, 20000, 25000, 30000, 40000, 50000, 75000, 100000, 150000, 200000, 300000, 500000, 1000000); $n = 0;
    foreach (q("SELECT c.id, c.chat_id, c.ctype, c.ms_last, s.members FROM chats c JOIN chat_stats s ON s.chat_id=c.chat_id AND s.day=? WHERE c.ms_on=1 AND c.status='approved' AND c.blocked=0 AND c.paused<" . time() . " AND s.members>0", array(date('Y-m-d')))->fetchAll() as $c) {
        $hit = 0; foreach ($T as $x) if ((int)$c['members'] >= $x) $hit = $x;
        if ($hit <= (int)$c['ms_last']) continue;
        if (q('UPDATE chats SET ms_last=? WHERE id=? AND ms_last<?', array($hit, $c['id'], $hit))->rowCount() !== 1) continue;
        if ((int)$c['ms_last'] === 0) continue;   /* birinchi tekshiruv — hozirgi marra eslab qolinadi, e'lon qilinmaydi */
        $k = $c['ctype'] === 'Kanal';
        $t = "🎉 <b>Tabriklaymiz! " . ($k ? 'Kanalimiz' : 'Guruhimiz') . ' ' . number_format($hit, 0, '.', ' ') . ' ' . ($k ? 'obunachi' : "a'zo") . "ga yetdi!</b> 🥳\n\nHar biringizga katta rahmat — birga yanada ko'pmiz! 🤝\nYaqinlaringizni ham taklif qiling 👇";
        $r = pr_call('sendMessage', array('chat_id' => $c['chat_id'], 'text' => $t, 'parse_mode' => 'HTML'));
        q('INSERT INTO post_logs (chat_id,ok,info,at) VALUES (?,?,?,NOW())', array($c['id'], !empty($r['ok']) ? 1 : 0, mb_substr('marra ' . $hit . (!empty($r['ok']) ? '' : ': ' . (isset($r['description']) ? $r['description'] : 'yuborilmadi')), 0, 255)));
        if (!empty($r['ok'])) $n++;
    }
    return $n;
}
/* ---------- Guruhda /kurs va /namoz buyruqlari ---------- */
function cmd_handle($m) {   /* true — buyruq bajarildi */
    $text = isset($m['text']) ? trim((string)$m['text']) : '';
    if (!preg_match('~^/(kurs|namoz)(?:@(\w+))?(?:\s|$)~i', $text, $x)) return false;
    if (!empty($x[2]) && strcasecmp($x[2], BOT_USERNAME) !== 0) return false;   /* boshqa botga yozilgan */
    $cid = $m['chat']['id']; $c = strtolower($x[1]); $k = 'cmd_' . $c . '_' . $cid;
    if ((int)setting($k, '0') > time() - 60) return true; setset($k, (string)time());   /* bir chatda daqiqasiga bir marta */
    $rp = array('reply_parameters' => array('message_id' => $m['message_id'], 'allow_sending_without_reply' => true));
    if ($c === 'kurs') { $sig = rates_sig('a') . setting('card_style', 'C'); $cap = frame_cap('a'); $mk = function () { return png_card(); }; }
    else { $h = pr_home(); if (empty($h['ok'])) { pr_call('sendMessage', array('chat_id' => $cid, 'text' => '🕌 Namoz vaqtlari hozircha olinmadi, birozdan keyin urinib ko\'ring.') + $rp); return true; }
        $sig = md5(json_encode($h)); $cap = pimg_cap($h); $mk = function () use ($h) { return png_prayer($h); }; }
    $fid = (string)setting('cmd_' . $c . '_fid', '');
    if ($fid !== '' && setting('cmd_' . $c . '_sig', '') === $sig) {   /* rasm o'zgarmagan — qayta chizilmaydi */
        $r = pr_call('sendPhoto', array('chat_id' => $cid, 'photo' => $fid) + ($cap !== '' ? array('caption' => $cap) : array()) + $rp);
        if (!empty($r['ok'])) return true;
    }
    $png = $mk();
    if ($png === false) { pr_call('sendMessage', array('chat_id' => $cid, 'text' => $c === 'kurs' ? '💵 Kurslar hali yuklanmagan.' : '🕌 Namoz vaqtlari hozircha olinmadi.') + $rp); return true; }
    $r = tg_photo($cid, $png, $cap);
    if (!empty($r['result']['photo'])) { $p = end($r['result']['photo']); setset('cmd_' . $c . '_fid', $p['file_id']); setset('cmd_' . $c . '_sig', $sig); }
    return true;
}
/* ---------- Guruhda avto-javob: kalit so'z yozilsa — bot o'zi javob beradi ---------- */
function ar_install() { db()->exec("CREATE TABLE IF NOT EXISTS auto_replies (id INT AUTO_INCREMENT PRIMARY KEY, chat_ref INT NOT NULL, kw VARCHAR(100) NOT NULL, reply TEXT NOT NULL, hits INT NOT NULL DEFAULT 0, last_at INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, KEY k (chat_ref)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); }
function ar_norm($s) { return ' ' . trim(preg_replace('/[^\p{L}\p{N}\']+/u', ' ', mb_strtolower(strtr((string)$s, array('‘' => "'", '’' => "'", 'ʻ' => "'", 'ʼ' => "'", '`' => "'"))))) . ' '; }
function ar_handle($m) {
    $text = isset($m['text']) ? (string)$m['text'] : ''; if ($text === '' || $text[0] === '/' || !empty($m['from']['is_bot']) || !empty($m['is_automatic_forward'])) return;
    $ref = q("SELECT id FROM chats WHERE chat_id=? AND status='approved' AND blocked=0 LIMIT 1", array($m['chat']['id']))->fetchColumn(); if (!$ref) return;
    $L = q('SELECT id,kw,reply,last_at FROM auto_replies WHERE chat_ref=? ORDER BY id', array($ref))->fetchAll(); if (!$L) return;
    $t = ar_norm($text);
    foreach ($L as $r) foreach (explode(',', $r['kw']) as $k) {
        $k = trim(ar_norm($k)); if ($k === '' || mb_strpos($t, ' ' . $k . ' ') === false) continue;
        if (time() - (int)$r['last_at'] < 60) return;   /* bir qoida — daqiqasiga bir marta (spam bo'lmasin) */
        q('UPDATE auto_replies SET hits=hits+1, last_at=? WHERE id=?', array(time(), $r['id']));
        pr_call('sendMessage', array('chat_id' => $m['chat']['id'], 'text' => $r['reply'], 'reply_parameters' => array('message_id' => $m['message_id'], 'allow_sending_without_reply' => true)));
        return;
    }
}
/* ---------- Kanal imzosi: kanalga yangi post joylansa — bot tagiga imzo qo'shadi (formatlash saqlanadi) ---------- */
function u16len($s) { return (int)(strlen(mb_convert_encoding((string)$s, 'UTF-16LE', 'UTF-8')) / 2); }
function ps_handle($m) {
    $c = q("SELECT id, ps_text FROM chats WHERE chat_id=? AND ps_on=1 AND status='approved' AND blocked=0 LIMIT 1", array($m['chat']['id']))->fetch(); if (!$c) return;
    $sig = trim((string)$c['ps_text']); if ($sig === '') return;
    if (isset($m['forward_origin']) || isset($m['forward_from_chat']) || isset($m['via_bot'])) return;   /* forward postlarni tahrirlab bo'lmaydi */
    $isText = isset($m['text']);
    if (!$isText && !(isset($m['photo']) || isset($m['video']) || isset($m['document']) || isset($m['animation']) || isset($m['audio']) || isset($m['voice']))) return;   /* stiker, so'rovnoma va h.k. */
    $body = $isText ? (string)$m['text'] : (isset($m['caption']) ? (string)$m['caption'] : '');
    if (isset($m['media_group_id'])) {   /* albom — faqat matnli (caption) rasmga, bir marta */
        if ($body === '') return;
        if (q('INSERT IGNORE INTO ps_mg (mg,at) VALUES (?,?)', array((string)$m['media_group_id'], time()))->rowCount() !== 1) return;
        if (mt_rand(1, 50) === 1) q('DELETE FROM ps_mg WHERE at<?', array(time() - 86400));
    }
    $bt = rtrim($body); if ($bt !== '' && mb_substr($bt, -mb_strlen($sig)) === $sig) return;   /* imzo allaqachon bor */
    $new = ($bt === '' ? '' : $bt . "\n\n") . $sig;
    if (mb_strlen($new) > ($isText ? 4096 : 1024)) { q('UPDATE chats SET ps_err=? WHERE id=?', array('Post juda uzun — imzo sig\'madi', $c['id'])); return; }
    $ents = isset($m[$isText ? 'entities' : 'caption_entities']) ? $m[$isText ? 'entities' : 'caption_entities'] : array(); $bl = u16len($bt);
    foreach ($ents as $i => $e) { if ($e['offset'] >= $bl) unset($ents[$i]); elseif ($e['offset'] + $e['length'] > $bl) $ents[$i]['length'] = $bl - $e['offset']; }
    $base = u16len($bt === '' ? '' : $bt . "\n\n");
    if (preg_match_all('~@[A-Za-z][A-Za-z0-9_]{3,31}|https?://\S+|t\.me/\S+~u', $sig, $mm, PREG_OFFSET_CAPTURE))   /* imzodagi @kanal va havolalar bosiladigan bo'lsin */
        foreach ($mm[0] as $x) $ents[] = array('type' => $x[0][0] === '@' ? 'mention' : 'url', 'offset' => $base + u16len(substr($sig, 0, $x[1])), 'length' => u16len($x[0]));
    $p = array('chat_id' => $m['chat']['id'], 'message_id' => $m['message_id']);
    if (!empty($m['reply_markup'])) $p['reply_markup'] = $m['reply_markup'];   /* post tugmalari saqlanadi */
    if ($isText) { $p['text'] = $new; if ($ents) $p['entities'] = array_values($ents); if (!empty($m['link_preview_options'])) $p['link_preview_options'] = $m['link_preview_options']; $r = pr_call('editMessageText', $p); }
    else { $p['caption'] = $new; if ($ents) $p['caption_entities'] = array_values($ents); $r = pr_call('editMessageCaption', $p); }
    $err = empty($r['ok']) ? (isset($r['description']) ? $r['description'] : 'tahrirlanmadi') : null;
    if ($err !== null && preg_match('/rights|not enough|can.t be edited|CHAT_ADMIN_REQUIRED|MESSAGE_AUTHOR_REQUIRED/i', $err)) $err = 'Botga kanalda «Xabarlarni tahrirlash» huquqini bering';
    q('UPDATE chats SET ps_err=? WHERE id=?', array($err === null ? null : mb_substr($err, 0, 200), $c['id']));
}
function cb_admin($cq, $t, $act, $id, $ans) {
    $uid = (int)$cq['from']['id'];
    if (!in_array((string)$uid, array_map('trim', explode(',', ADMIN_IDS)), true)) { $ans('Bu tugma faqat admin uchun', true); return; }
    $res = ''; $pdo = db();
    if ($t === 'tp') {
        $tp = q('SELECT * FROM topups WHERE id=?', array($id))->fetch(); if (!$tp) { $ans('Topilmadi', true); return; }
        try {
            $pdo->beginTransaction();
            $st = q("UPDATE topups SET status=?, decided_at=NOW(), decided_by=? WHERE id=? AND status='pending'", array($act === 'ok' ? 'approved' : 'rejected', $uid, $id));
            if ($st->rowCount() !== 1) { $pdo->rollBack(); $res = 'ℹ️ Allaqachon ko\'rib chiqilgan'; }
            else {
                if ($act === 'ok') q('UPDATE users SET balance=balance+? WHERE id=?', array($tp['amount'], $tp['user_id']));
                $pdo->commit();
                q('INSERT INTO audit_logs (admin,action,detail,at) VALUES (?,?,?,NOW())', array($uid, 'topup_' . ($act === 'ok' ? 'approve' : 'reject'), '#' . $id . ' ' . $tp['user_id'] . ' ' . $tp['amount'] . ' (Telegram)'));
                topup_done($tp, $act === 'ok');
                $res = $act === 'ok' ? '✅ Tasdiqlandi — balansga ' . money($tp['amount']) . ' qo\'shildi' : '❌ Rad etildi';
            }
        } catch (Exception $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $ans('Xatolik, qayta urinib ko\'ring', true); return; }
    } else {
        $o = q('SELECT * FROM ad_orders WHERE id=?', array($id))->fetch(); if (!$o) { $ans('Topilmadi', true); return; }
        if ($act === 'ok') {
            if (q("UPDATE ad_orders SET status='sending' WHERE id=? AND status='pending'", array($id))->rowCount() === 1) {
                q('INSERT INTO audit_logs (admin,action,detail,at) VALUES (?,?,?,NOW())', array($uid, 'ad_send', '#' . $id . ' ' . $o['kind'] . ' (Telegram)'));
                $res = '📤 Yuborish boshlandi — tugagach xabar keladi';
            } else $res = 'ℹ️ Allaqachon ko\'rib chiqilgan';
        } else {
            try {
                $pdo->beginTransaction();
                $st = q("UPDATE ad_orders SET status='rejected', decided_at=NOW() WHERE id=? AND status='pending'", array($id));
                if ($st->rowCount() !== 1) { $pdo->rollBack(); $res = 'ℹ️ Allaqachon ko\'rib chiqilgan'; }
                else {
                    q('UPDATE users SET balance=balance+? WHERE id=?', array($o['price'], $o['user_id'])); $pdo->commit();
                    q('INSERT INTO audit_logs (admin,action,detail,at) VALUES (?,?,?,NOW())', array($uid, 'ad_reject', '#' . $id . ' qaytarildi ' . $o['price'] . ' (Telegram)'));
                    tg('sendMessage', array('chat_id' => $o['user_id'], 'text' => "❌ E'lon buyurtmangiz #" . $id . " qabul qilinmadi. " . money($o['price']) . " balansingizga qaytarildi."));
                    $res = '❌ Rad etildi — ' . money($o['price']) . ' qaytarildi';
                }
            } catch (Exception $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $ans('Xatolik, qayta urinib ko\'ring', true); return; }
        }
    }
    $ans(mb_substr($res, 0, 190));
    if (isset($cq['message']['message_id'])) pr_call('editMessageCaption', array('chat_id' => $cq['message']['chat']['id'], 'message_id' => $cq['message']['message_id'],
        'caption' => mb_substr((isset($cq['message']['caption']) ? $cq['message']['caption'] : '') . "\n\n" . $res . ' · ' . uname($cq['from']), 0, 1024), 'reply_markup' => array('inline_keyboard' => array())));
}
/* Telegram'da «Yuborish» bosilgan e'lonlar — har daqiqada cron orqali bo'laklab yuboriladi (admin panel ochilmasa ham) */
function ad_cron() {
    $ids = q("SELECT id FROM ad_orders WHERE status='sending' ORDER BY id LIMIT 3")->fetchAll(PDO::FETCH_COLUMN); if (!$ids) return 'yo\'q';
    $adm = trim(explode(',', ADMIN_IDS)[0]); $t0 = time(); $n = 0;
    foreach ($ids as $id) while (time() - $t0 < 40) { $r = ad_send_step((int)$id, $adm); $n++; if (!$r['ok'] || $r['finished']) { if ($r['ok']) notify_admins("✅ E'lon #" . $id . " yuborildi: " . $r['sent'] . ' ta' . ($r['failed'] ? ', yetmadi: ' . $r['failed'] : '')); else notify_admins("⚠️ E'lon #" . $id . ": " . $r['error']); break; } }
    return 'qadam ' . $n;
}
function cb_handle($cq) {
    $d = isset($cq['data']) ? (string)$cq['data'] : ''; $uid = (int)$cq['from']['id'];
    $ans = function ($t, $alert = false) use ($cq) { pr_call('answerCallbackQuery', array('callback_query_id' => $cq['id'], 'text' => $t, 'show_alert' => $alert)); };
    if (preg_match('/^cap:(\d+)$/', $d, $x) && isset($cq['message']['chat']['id'])) {
        $cid = $cq['message']['chat']['id'];
        if ((int)$x[1] !== $uid) { $ans('Bu tugma siz uchun emas', true); return; }
        q('DELETE FROM guard_captcha WHERE chat_id=? AND user_id=?', array($cid, $uid));
        unmute($cid, $uid);
        pr_call('deleteMessage', array('chat_id' => $cid, 'message_id' => $cq['message']['message_id']));
        $ans('✅ Rahmat! Endi yozishingiz mumkin.'); return;
    }
    if (preg_match('/^gq:(\d+):(\d)$/', $d, $x) && isset($cq['message']['chat']['id'])) {
        $cid = $cq['message']['chat']['id'];
        if ((int)$x[1] !== $uid) { $ans('Bu savol siz uchun emas', true); return; }
        $c = q('SELECT ans FROM guard_captcha WHERE chat_id=? AND user_id=?', array($cid, $uid))->fetch();
        if (!$c || q('DELETE FROM guard_captcha WHERE chat_id=? AND user_id=?', array($cid, $uid))->rowCount() !== 1) { $ans(''); return; }
        pr_call('deleteMessage', array('chat_id' => $cid, 'message_id' => $cq['message']['message_id']));
        if ((int)$c['ans'] === (int)$x[2]) { unmute($cid, $uid); $ans("✅ To'g'ri! Endi yozishingiz mumkin."); return; }
        $r = pr_call('banChatMember', array('chat_id' => $cid, 'user_id' => $uid)); if (!empty($r['ok'])) pr_call('unbanChatMember', array('chat_id' => $cid, 'user_id' => $uid, 'only_if_banned' => true));
        q('INSERT INTO guard_log (chat_id,kind,user_id,ok,at,txt,uname) VALUES (?,?,?,?,?,?,?)', array($cid, 'captcha', $uid, !empty($r['ok']) ? 1 : 0, date('Y-m-d H:i:s'), "[test savoliga noto'g'ri javob — chiqarildi]", uname($cq['from'])));
        $ans("❌ Noto'g'ri javob. Guruh qoidalari bilan tanishib, qayta qo'shiling.", true); return;
    }
    if (preg_match('/^gw:(\d+)$/', $d, $x)) { gw_join((int)$x[1], $cq['from'], $ans); return; }
    if (preg_match('/^fs:(\d+):(\d+)$/', $d, $x)) { fs_cb($cq, (int)$x[1], (int)$x[2], $ans); return; }
    if (preg_match('/^(tp|ad):(ok|no):(\d+)$/', $d, $x)) { cb_admin($cq, $x[1], $x[2], (int)$x[3], $ans); return; }
    if (preg_match('/^au:(ok|no):(\d+)$/', $d, $x)) {   /* reklama birjasi: kanal egasi qarori */
        $o = q('SELECT owner FROM auc_orders WHERE id=?', array((int)$x[2]))->fetch();
        if (!$o || (string)$o['owner'] !== (string)$uid) { $ans('Bu tugma kanal egasi uchun', true); return; }
        $res = auc_decide((int)$x[2], $x[1] === 'ok', $uid); $ans(mb_substr($res, 0, 190));
        if (isset($cq['message']['message_id'])) { $m2 = $cq['message']; $f = isset($m2['caption']) ? 'editMessageCaption' : 'editMessageText'; pr_call($f, array('chat_id' => $m2['chat']['id'], 'message_id' => $m2['message_id'], ($f === 'editMessageCaption' ? 'caption' : 'text') => mb_substr((isset($m2['caption']) ? $m2['caption'] : (isset($m2['text']) ? $m2['text'] : '')) . "\n\n" . $res, 0, 1000), 'reply_markup' => array('inline_keyboard' => array()))); }
        return;
    }
    $ans('');
}
/* Eski bot qoldiqlarini tozalash: yangi bot administrator bo'lmagan kanal/guruhlar va yangi botni ishga tushirmagan foydalanuvchilar o'chiriladi.
   Faqat Telegram aniq javob bersa (400/403: chat yo'q, bot chiqarilgan, bloklangan) o'chiriladi; tarmoq xatosida to'xtab, keyinroq davom etadi. */
function cl_st() { $s = json_decode(setting('cl_st', ''), true); return is_array($s) ? $s : array('c' => 0, 'cd' => 0, 'u' => 0, 'ud' => 0, 'a' => 0, 'ad' => 0, 'err' => ''); }
function cl_del_chat($c) {
    q('DELETE FROM chats WHERE id=?', array($c['id'])); q('DELETE FROM post_logs WHERE chat_id=?', array($c['id']));
    foreach (array('group_guard', 'guard_admins', 'quiz_settings') as $t) { try { q("DELETE FROM $t WHERE chat_id=?", array($c['chat_id'])); } catch (Exception $e) {} }
    foreach (array('sched_posts', 'giveaways', 'chat_admins') as $t) { try { q("DELETE FROM $t WHERE chat_ref=?", array($c['id'])); } catch (Exception $e) {} }
}
function cl_drop_user($id) {
    if (is_admin($id)) return false;
    $has = function ($sql) use ($id) { try { return (bool)q($sql, array($id))->fetchColumn(); } catch (Exception $e) { return false; } };
    if ($has('SELECT 1 FROM chats WHERE owner=? LIMIT 1') || $has('SELECT 1 FROM topups WHERE user_id=? LIMIT 1') || $has('SELECT 1 FROM ad_orders WHERE user_id=? LIMIT 1')) return false;   /* kanal egasi, to'lov/e'lon tarixi — saqlanadi */
    $n = q('DELETE FROM users WHERE id=?', array($id))->rowCount() + q('DELETE FROM azo_import WHERE id=?', array($id))->rowCount();
    return $n > 0;
}
function cl_finish() {
    setset('cl_on', '0'); setset('cl_done', date('d.m.Y H:i'));
    $ids = q('SELECT id FROM users UNION SELECT id FROM azo_import')->fetchAll(PDO::FETCH_COLUMN);   /* azo_dat.txt dan ham eski IDlar olib tashlanadi (qayta «Yuklash»da qaytmasin) */
    $f = __DIR__ . '/azo_dat.txt';
    if (is_file($f)) { $keep = array_flip(array_map('strval', $ids)); $h = @fopen($f, 'c+');
        if ($h && flock($h, LOCK_EX)) { $out = array(); foreach (preg_split('/\R/', (string)stream_get_contents($h)) as $l) { $l = trim($l); if ($l !== '' && isset($keep[$l])) $out[$l] = 1; }
            ftruncate($h, 0); rewind($h); fwrite($h, $out ? implode("\n", array_keys($out)) . "\n" : ''); flock($h, LOCK_UN); }
        if ($h) fclose($h); }
}
function cleanup_run($sec) {
    if (setting('cl_on', '') !== '1') return 'off';
    if (!db()->query("SELECT GET_LOCK('kp_clean',0)")->fetchColumn()) return 'band';
    db()->exec('CREATE TABLE IF NOT EXISTS azo_import (id BIGINT UNSIGNED PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');   /* eski ro'yxat hech yuklanmagan bo'lsa ham */
    $t0 = microtime(true); $s = cl_st(); $bot = (int)strtok(BOT_TOKEN, ':');
    $gone = function ($r) { return empty($r['ok']) && isset($r['error_code']) && in_array((int)$r['error_code'], array(400, 403), true); };
    $why = function ($r) { return isset($r['description']) ? mb_substr((string)$r['description'], 0, 120) : 'tarmoq xatosi'; };
    try {
        while (microtime(true) - $t0 < $sec) {
            $ph = setting('cl_ph', 'c'); $cur = setting('cl_cur', '0'); $stop = false; $s['err'] = '';
            if ($ph === 'c') {   /* 1) kanal va guruhlar: yangi bot administratormi */
                $rows = q('SELECT id, chat_id, ctype, status FROM chats WHERE id > ? ORDER BY id LIMIT 25', array((int)$cur))->fetchAll();
                if (!$rows) { setset('cl_ph', 'u'); setset('cl_cur', '0'); continue; }
                $items = array(); foreach ($rows as $k => $c) $items[$k] = array('chat_id' => $c['chat_id'], 'user_id' => $bot);
                $res = tg_multi('getChatMember', $items);
                foreach ($rows as $k => $c) {
                    $r = $res[$k];
                    if (!empty($r['ok'])) {
                        $m = $r['result'];
                        if ($m['status'] === 'creator' || ($m['status'] === 'administrator' && ($c['ctype'] !== 'Kanal' || !empty($m['can_post_messages'])))) {
                            if ($c['status'] === 'noperm') q("UPDATE chats SET status='approved', auto_on=IF(send_a=1 OR send_b=1,1,0) WHERE id=?", array($c['id']));
                            $s['c']++; setset('cl_cur', $c['id']); continue;
                        }
                        if ($m['status'] === 'administrator') {   /* admin, lekin kanalda «Xabar joylash» yo'q — o'chirilmaydi, sozlamalar saqlanadi */
                            q("UPDATE chats SET status='noperm' WHERE id=?", array($c['id'])); $s['c']++; setset('cl_cur', $c['id']); continue;
                        }
                    } elseif (!$gone($r)) { $stop = true; $s['err'] = $why($r); break; }
                    cl_del_chat($c); $s['c']++; $s['cd']++; setset('cl_cur', $c['id']);
                }
            } elseif ($ph === 'u' || $ph === 'a') {   /* 2) foydalanuvchilar, 3) eski /start ro'yxati: yangi botni ishga tushirganmi */
                $ids = q('SELECT id FROM ' . ($ph === 'u' ? 'users' : 'azo_import') . ' WHERE id > ? ORDER BY id LIMIT 30', array($cur))->fetchAll(PDO::FETCH_COLUMN);
                if (!$ids) { if ($ph === 'u') { setset('cl_ph', 'a'); setset('cl_cur', '0'); continue; } setset('cl_st', json_encode($s)); cl_finish(); break; }
                $items = array(); foreach ($ids as $k => $id) $items[$k] = array('chat_id' => $id);
                $res = tg_multi('getChat', $items);
                foreach ($ids as $k => $id) {
                    $r = $res[$k];
                    if (empty($r['ok']) && !$gone($r)) { $stop = true; $s['err'] = $why($r); break; }
                    if (empty($r['ok']) && cl_drop_user($id)) $s[$ph . 'd']++;
                    $s[$ph]++; setset('cl_cur', $id);
                }
            } else break;
            setset('cl_st', json_encode($s));
            if ($stop) break;
        }
    } finally { db()->query("SELECT RELEASE_LOCK('kp_clean')"); }
    return 'kanal/guruh ' . $s['cd'] . ', foydalanuvchi ' . ($s['ud'] + $s['ad']) . " o'chirildi";
}
function cl_info() { return array('on' => setting('cl_on', '') === '1', 'ph' => setting('cl_ph', 'c'), 'st' => cl_st(), 'done' => setting('cl_done', ''),
    'tot' => array('c' => (int)q('SELECT COUNT(*) FROM chats')->fetchColumn(), 'u' => (int)q('SELECT COUNT(*) FROM users')->fetchColumn(), 'a' => azo_n())); }
function cron_minute() {
    setset('cron_min_at', date('Y-m-d H:i:s'));   /* admin panelda «cron ishlayaptimi» ko'rinishi uchun */
    $o = array();
    foreach (array('Tongi xabar' => function () { return cron_daily(); }, 'Bayram' => function () { return bt_run(); }, 'Kechki xabar' => function () { return ev_run(); }, 'Ob-havo ogohlantirishi' => function () { return wa_run(); }, 'Avto-o\'chirish' => function () { return autodel_run(); }, 'Namoz' => function () { return cron_prayer(); }, 'Postlar' => function () { return posts_run(30); }, 'Kapcha' => function () { captcha_expire(50); tmp_run(50); return 'ok'; },
        'Bank kurslari' => function () { return xb_fetch(); }, 'Statistika' => function () { stats_run(30); return 'ok'; }, 'Marra' => function () { return ms_run(); }, 'TOP-10' => function () { return top10_run(); }, 'Hisobot' => function () { return report_run(20); }, 'Konkurs' => function () { gw_run(10); return 'ok'; }, 'Bosh sahifa' => function () { $h = pr_home(); return $h['ok'] ? 'ok' : 'xato'; }, 'Namoz rasmi' => function () { return pimg_run(40); }, 'Ob-havo' => function () { return cron_weather(); }, 'Krossvord' => function () { return quiz_run(); }, 'Tozalash' => function () { return cleanup_run(25); }, 'Ogohlantirish' => function () { alert_run(); return 'ok'; }, 'Eslatmalar' => function () { return rem_run(); }, 'Guruh ochish' => function () { return lock_run(); }, 'Juma sukuti' => function () { return juma_run(); }, 'RSS' => function () { return rss_run(); }, 'Pullik obuna' => function () { return pc_run(); }, 'Reklama birjasi' => function () { return auc_run(); }, 'Monitoring' => function () { return mon_run(); }, 'Kun kanali' => function () { return kk_run(); }, 'Sanoq' => function () { return cd_run(); }, 'E\'lonlar' => function () { return ad_cron(); }) as $k => $f) {
        try { $o[] = $k . ': ' . $f(); } catch (Exception $e) { $o[] = $k . ': xato'; }
    }
    return implode(' | ', $o);
}

