        if ($a === 'post_test') { $e = post_send($p, $u['id']); out(array('ok' => $e === '', 'error' => $e)); }
        $t = strtotime(str_replace('T', ' ', (string)(isset($in['run_at']) ? $in['run_at'] : '')));
