            $l = $r['result']['invite_link'];
            q('INSERT INTO ref_links (chat_id,user_id,link,created_at) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE link=VALUES(link)', array($c['chat_id'], $u['id'], $l, date('Y-m-d H:i:s')));
        }
        out(array('ok' => true, 'link' => $l));
