        if (!$g) out(array('ok' => false, 'error' => 'Faol konkurs topilmadi'), 404);
        if ($a === 'gw_finish') { gw_finish($g['id']); out(array('ok' => true)); }
        q("UPDATE giveaways SET status='cancel' WHERE id=?", array($g['id']));
