        $okBot = !empty($bm['ok']) && in_array($bm['result']['status'], array('administrator', 'creator'), true) && ($type === 'Guruh' || !empty($bm['result']['can_post_messages']) || $bm['result']['status'] === 'creator');
        $iv = max(3, min(12, (int)(isset($in['interval']) ? $in['interval'] : 3)));
        q('INSERT INTO chats (owner,chat_id,username,ctype,status,interval_h,created_at) VALUES (?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE username=VALUES(username), interval_h=IF(?=1,VALUES(interval_h),interval_h), status=IF(status IN ("approved","rejected"),status,VALUES(status))', array($u['id'], $cid, $un, $type, $okBot ? 'approved' : 'noperm', $iv, isset($in['interval']) ? 1 : 0));
