            if ($sel && (!$c || !in_array($sel, array_column($groups, 'id'), true))) { $sel = 0; $c = null; }
            $cid = $c ? $c['chat_id'] : 0; $now = time();
            $r = array('ok' => true, 'now' => $now, 'chat' => $sel, 'groups' => $groups, 'tree' => quiz_tree(), 'counts' => q('SELECT cat, COUNT(*) n FROM quiz_questions GROUP BY cat')->fetchAll(PDO::FETCH_KEY_PAIR), 'admin' => $adm, 'manage' => $c ? $c['manage'] : false);
            if ($c) {
                $cfg = quiz_cfg($cid);
                $r['cfg'] = array('on' => (int)$cfg['enabled'], 'cat' => (string)$cfg['cat'], 'label' => quiz_label((string)$cfg['cat']), 'interval' => (int)$cfg['interval_min'], 'sec' => (int)$cfg['answer_sec'], 'points' => (int)$cfg['points'],
                    'next' => (int)$cfg['next_at'], 'err' => (string)$cfg['last_err'], 'mode' => $cfg['mode'], 'ch' => (int)$cfg['channel'], 'count' => (int)$cfg['q_total'], 'done' => (int)$cfg['q_done']);
                $r['link'] = $c['username'] !== '' && $c['username'][0] === '@' ? 'https://t.me/' . substr($c['username'], 1) : '';
                $cur = q("SELECT s.subject, s.points, s.ends_at, s.kind, s.opts, q.question, q.answer FROM quiz_sessions s JOIN quiz_questions q ON q.id=s.question_id WHERE s.chat_id=? AND s.status='active' LIMIT 1", array($cid))->fetch();
                if ($cur) {
                    $bx = $cur['kind'] === 'test' ? array('', '📝 Test · variantlardan birini tanlang') : quiz_boxes($cur['answer']);
                    $r['cur'] = array('subject' => $cur['subject'], 'question' => $cur['question'], 'boxes' => $bx[0], 'info' => $bx[1], 'points' => (int)$cur['points'], 'ends' => (int)$cur['ends_at'],
                        'opts' => $cur['kind'] === 'test' ? json_decode((string)$cur['opts'], true) : null);
                }
            }
            $w = $cid ? ' AND s.chat_id=?' : ''; $p = $cid ? array($cid) : array();
            $r['last'] = q("SELECT s.subject, q.question, q.answer, s.winner_name, s.points, s.finished_at FROM quiz_sessions s JOIN quiz_questions q ON q.id=s.question_id WHERE s.status='finished'" . $w . ' ORDER BY s.id DESC LIMIT 5', $p)->fetchAll();
            $r['subj'] = q("SELECT s.subject, COUNT(*) n, SUM(s.winner_id IS NOT NULL) won FROM quiz_sessions s WHERE s.status='finished'" . $w . ' GROUP BY s.subject ORDER BY n DESC', $p)->fetchAll();
            $me = $cid ? q('SELECT points, correct, answered FROM quiz_participants WHERE chat_id=? AND user_id=?', array($cid, $u['id']))->fetch()
                : q('SELECT SUM(points) points, SUM(correct) correct, SUM(answered) answered FROM quiz_participants WHERE user_id=?', array($u['id']))->fetch();
            $mp = $me ? (int)$me['points'] : 0;
            $place = $cid ? (int)q('SELECT COUNT(*)+1 FROM quiz_participants WHERE chat_id=? AND points>?', array($cid, $mp))->fetchColumn()
                : (int)q('SELECT COUNT(*)+1 FROM (SELECT user_id FROM quiz_participants GROUP BY user_id HAVING SUM(points)>?) t', array($mp))->fetchColumn();
            $r['me'] = array('points' => $mp, 'correct' => $me ? (int)$me['correct'] : 0, 'answered' => $me ? (int)$me['answered'] : 0, 'place' => $mp > 0 ? $place : 0,
                'total' => (int)q('SELECT COALESCE(SUM(points),0) FROM quiz_participants WHERE user_id=?', array($u['id']))->fetchColumn());
            $r['rank'] = quiz_rank($cid, 'all', 20);
            if ($adm) { $r['qn'] = (int)q('SELECT COUNT(*) FROM quiz_questions')->fetchColumn(); $r['dg'] = setting('quiz_dg', '1') === '1'; }
            out($r);
        }
        if ($a === 'qz_rank') {
            $mode = isset($in['mode']) ? (string)$in['mode'] : 'all'; if (!in_array($mode, array('all', 'day', 'week', 'correct', 'people'), true)) $mode = 'all';
            $cid = 0;
            if (!empty($in['chat'])) {
                $c = $qzc($in['chat']); if (!$c) out(array('ok' => false, 'error' => 'Guruh topilmadi'), 404);
                if (!$c['manage'] && !q('SELECT 1 FROM quiz_participants WHERE chat_id=? AND user_id=?', array($c['chat_id'], $u['id']))->fetchColumn()) out(array('ok' => false, 'error' => 'Ruxsat yo\'q'), 403);
                $cid = $c['chat_id'];
            }
            out(array('ok' => true, 'mode' => $mode, 'rows' => quiz_rank($cid, $mode, $mode === 'people' ? 200 : 50)));
        }
        if (in_array($a, array('qz_set', 'qz_send', 'qz_diag', 'qz_toggle'), true)) {
            $c = $qzc(isset($in['chat']) ? $in['chat'] : 0);
            if (!$c) out(array('ok' => false, 'error' => 'Guruh topilmadi'), 404);
            if (!$c['manage']) out(array('ok' => false, 'error' => 'Faqat guruhni qo\'shgan egasi yoki admin boshqaradi'), 403);
            if ($a === 'qz_diag') { $cf = quiz_cfg($c['chat_id']); out(array('ok' => true, 'diag' => quiz_diag($c['chat_id'], $cf['mode']))); }
            if ($a === 'qz_send') { $r = quiz_start($c['chat_id']); out(array('ok' => $r[0], 'error' => $r[1])); }
            if ($a === 'qz_toggle') {   /* «Kanal va guruhlarim» ro'yxatidan: yoqilsa birinchi savol keyingi daqiqada (next_at enabled'dan oldin hisoblanadi) */
                q('INSERT INTO quiz_settings (chat_id,enabled,next_at,updated_at,mode) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE next_at=IF(VALUES(enabled)=1 AND enabled=0, VALUES(next_at), next_at), q_done=IF(VALUES(enabled)=1 AND enabled=0, 0, q_done), round_from=IF(VALUES(enabled)=1 AND enabled=0, VALUES(updated_at), round_from), enabled=VALUES(enabled), updated_at=VALUES(updated_at)',
                    array($c['chat_id'], !empty($in['on']) ? 1 : 0, time(), time(), 'test'));
                out(array('ok' => true));
            }
            $cat = trim((string)(isset($in['cat']) ? $in['cat'] : ''), '/'); if (quiz_path($cat) === null) out(array('ok' => false, 'error' => 'Bo\'lim noto\'g\'ri'), 422);
            if ($cat !== '' && !(int)q('SELECT COUNT(*) FROM quiz_questions WHERE cat=? OR cat LIKE ?', array($cat, $cat . '/%'))->fetchColumn()) out(array('ok' => false, 'error' => '«' . quiz_label($cat) . '» bo\'limida hali savol yo\'q — boshqasini tanlang yoki adminga yozing'), 422);
            $iv = (int)(isset($in['interval']) ? $in['interval'] : 10); $sec = (int)(isset($in['sec']) ? $in['sec'] : 60); $pts = (int)(isset($in['points']) ? $in['points'] : 10);
            if ($iv < 1 || $iv > 1440) out(array('ok' => false, 'error' => 'Interval 1–1440 daqiqa bo\'lsin'), 422);
            if ($sec < 15 || $sec > 600) out(array('ok' => false, 'error' => 'Javob vaqti 15–600 soniya bo\'lsin'), 422);
            if ($pts < 1 || $pts > 1000) out(array('ok' => false, 'error' => 'Ochko 1–1000 bo\'lsin'), 422);
            $on = !empty($in['on']) ? 1 : 0; $old = quiz_cfg($c['chat_id']);
            $mode = 'test';
            $next = $on && !(int)$old['enabled'] ? time() : (int)$old['next_at'];   /* yoqilganda birinchi savol darhol (keyingi cron) */
            $cnt = (int)$old['q_total'];
            if (isset($in['count'])) { $cnt = (int)$in['count']; if ($cnt < 10 || $cnt > 30) out(array('ok' => false, 'error' => 'Savollar soni 10–30 bo\'lsin'), 422); }
            $fresh = $on && !(int)$old['enabled'];   /* yangi o'yin: hisob noldan */
            $qd = $fresh ? 0 : (int)$old['q_done']; $rf = $fresh ? time() : (int)$old['round_from'];
            q('INSERT INTO quiz_settings (chat_id,enabled,cat,interval_min,answer_sec,points,next_at,updated_at,mode,q_total,q_done,round_from) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled), cat=VALUES(cat),
                interval_min=VALUES(interval_min), answer_sec=VALUES(answer_sec), points=VALUES(points), next_at=VALUES(next_at), updated_at=VALUES(updated_at), mode=VALUES(mode), q_total=VALUES(q_total), q_done=VALUES(q_done), round_from=VALUES(round_from)', array($c['chat_id'], $on, $cat, $iv, $sec, $pts, $next, time(), $mode, $cnt, $qd, $rf));
            out(array('ok' => true));
        }
        if (!$adm) out(array('ok' => false, 'error' => 'Ruxsat yo\'q'), 403);
        /* ---- savollar bazasi: faqat admin ---- */
        if ($a === 'qz_q_list') {
            $f = trim((string)(isset($in['f']) ? $in['f'] : ''), '/'); if (quiz_path($f) === null) $f = ''; $sq = trim((string)(isset($in['s']) ? $in['s'] : '')); $pg = max(0, (int)(isset($in['p']) ? $in['p'] : 0));
            $w = array(); $p = array();
            if ($f !== '') { $w[] = '(cat=? OR cat LIKE ?)'; $p[] = $f; $p[] = $f . '/%'; }
            if ($sq !== '') { $w[] = '(question LIKE ? OR answer LIKE ?)'; $p[] = '%' . $sq . '%'; $p[] = '%' . $sq . '%'; }
            $wh = $w ? ' WHERE ' . implode(' AND ', $w) : '';
            $n = (int)q('SELECT COUNT(*) FROM quiz_questions' . $wh, $p)->fetchColumn();
            $rows = q('SELECT id, cat, level, question, answer, alts, opts, note, letters, used FROM quiz_questions' . $wh . ' ORDER BY id DESC LIMIT 20 OFFSET ' . ($pg * 20), $p)->fetchAll();
            foreach ($rows as $i => $x) $rows[$i]['label'] = quiz_label($x['cat']);
            out(array('ok' => true, 'n' => $n, 'p' => $pg, 'rows' => $rows, 'counts' => q('SELECT cat, COUNT(*) n FROM quiz_questions GROUP BY cat')->fetchAll(PDO::FETCH_KEY_PAIR)));
        }
        if ($a === 'qz_ai') {   /* AI bilan savollar — avval ko'rib chiqiladi, keyin saqlanadi */
            $cat = trim((string)(isset($in['cat']) ? $in['cat'] : ''), '/'); if (!quiz_leaf($cat)) out(array('ok' => false, 'error' => 'Bo\'limni oxirigacha tanlang (fan darajasigacha)'), 422);
            @set_time_limit(120); list($L, $e) = quiz_ai($cat, max(3, min(20, (int)(isset($in['n']) ? $in['n'] : 10))), max(1, min(3, (int)(isset($in['level']) ? $in['level'] : 2))));
            if ($L === null) out(array('ok' => false, 'error' => $e), 502);
            foreach ($L as $i => $x) $L[$i]['dup'] = (bool)q('SELECT 1 FROM quiz_questions WHERE qhash=?', array(md5(quiz_norm($x['question']))))->fetchColumn();
            $audit('quiz_ai', quiz_label($cat) . ': ' . count($L) . ' ta'); out(array('ok' => true, 'list' => $L));
        }
        if ($a === 'qz_ai_save') {
            $cat = trim((string)(isset($in['cat']) ? $in['cat'] : ''), '/'); $add = 0; $err = array();
            foreach (array_slice((array)(isset($in['list']) ? $in['list'] : array()), 0, 30) as $x) { $e = quiz_q_save(array('cat' => $cat, 'question' => isset($x['question']) ? $x['question'] : '', 'answer' => isset($x['answer']) ? $x['answer'] : '', 'opts' => isset($x['opts']) ? $x['opts'] : '', 'note' => isset($x['note']) ? $x['note'] : '', 'level' => isset($in['level']) ? $in['level'] : 2)); if ($e === '') $add++; elseif ($e !== 'dup') $err[] = $e; }
            out(array('ok' => true, 'added' => $add, 'errors' => array_slice(array_unique($err), 0, 5)));
        }
        if ($a === 'qz_tpl') {   /* CSV namunasi va barcha bo'limlar kodlari — admin botiga fayl */
            $rows = array(array("Bo'lim", 'Savol', "To'g'ri javob", "Noto'g'ri variantlar (| bilan)", 'Izoh', 'Muqobil javoblar (| bilan)', 'Daraja (1-3)'), array('maktab/5/matematika', 'Eng kichik tub son qaysi?', '2', '1|3|5', '', '', '1'), array('Maktab > 7-sinf > Fizika', 'Kuchning SI birligi?', 'Nyuton', 'Joul|Vatt|Paskal', '', '', '1'));
            $walk = function ($n, $pre, $lab) use (&$walk, &$rows) { foreach ($n as $k => $c) { $p = $pre === '' ? $k : $pre . '/' . $k; $l = $lab === '' ? $c['t'] : $lab . ' › ' . $c['t']; if (empty($c['k'])) $rows[] = array($p, '— ' . $l, '', '', '', '', ''); else $walk($c['k'], $p, $l); } };
            $walk(quiz_tree(), '', '');
            $r = tg_doc($u['id'], csv_make($rows), 'savollar_namuna.csv', "📄 Savollar uchun namuna. Birinchi ustunga bo'lim kodini (masalan maktab/5/matematika) yoki nomini (Maktab > 5-sinf > Matematika) yozing. Pastda barcha bo'limlar kodlari.");
            out(array('ok' => !empty($r['ok']), 'error' => !empty($r['ok']) ? '' : 'Fayl yuborilmadi — botga /start bosing'));
        }
        if ($a === 'qz_q_save') {
            $e = quiz_q_save($in, (int)(isset($in['id']) ? $in['id'] : 0));
            if ($e !== '') out(array('ok' => false, 'error' => $e === 'dup' ? 'Bunday savol bazada bor' : $e), 422);
            $audit('quiz_q', (!empty($in['id']) ? 'tahrir #' . (int)$in['id'] : 'yangi')); out(array('ok' => true));
        }
        if ($a === 'qz_q_del') {
            $id = (int)(isset($in['id']) ? $in['id'] : 0);
            if (q("SELECT 1 FROM quiz_sessions WHERE question_id=? AND status='active'", array($id))->fetchColumn()) out(array('ok' => false, 'error' => 'Bu savol hozir guruhda berilmoqda — tugagach o\'chiring'), 409);
            q('DELETE FROM quiz_questions WHERE id=?', array($id)); $audit('quiz_q', 'o\'chirildi #' . $id); out(array('ok' => true));
        }
        if ($a === 'qz_q_import') {
            $csv = (string)(isset($in['csv']) ? $in['csv'] : ''); if (strlen($csv) > 3000000) out(array('ok' => false, 'error' => 'Fayl 3 MB dan katta'), 422);
            $r = quiz_import($csv); if ($r['ok']) $audit('quiz_import', $r['added'] . ' ta qo\'shildi'); out($r, $r['ok'] ? 200 : 422);
        }
        if ($a === 'qz_mode') {
            setset('quiz_dg', !empty($in['dg']) ? '1' : '0');
            foreach (q('SELECT id, answer FROM quiz_questions')->fetchAll() as $x) { $c = quiz_cells($x['answer'], !empty($in['dg'])); q('UPDATE quiz_questions SET letters=? WHERE id=?', array($c['n'], $x['id'])); }
            out(array('ok' => true));
        }
        out(array('ok' => false, 'error' => 'Noma\'lum amal'), 404);
    }
    if ($a === 'wx') out(array('ok' => true, 'date' => date('d.m.Y'), 'rows' => wx_data()));
    if ($a === 'wx_my') {
        $r = array('ok' => true, 'on' => setting('wx_on', '1') === '1', 'time' => setting('wx_time', '07:00'),
            'chats' => q("SELECT id,username,ctype,wx_on FROM chats WHERE owner=? AND status='approved' AND blocked=0 ORDER BY id DESC", array($u['id']))->fetchAll());
        if ($adm) $r['cfg'] = wx_cfg();
        out($r);
    }
    if ($a === 'sample') {   /* namuna: xabar foydalanuvchining o'ziga (bot bilan shaxsiy chat) xuddi kanal/guruhga boradigandek — o'sha rasm va o'sha matn */
        $k = isset($in['k']) ? (string)$in['k'] : ''; $me = $u['id'];
        if (!in_array($k, array('a', 'b', 'c', 'w', 'dp'), true)) out(array('ok' => false, 'error' => 'Noto\'g\'ri tur'), 422);
        if (time() - (int)setting('smp_' . $me, '0') < 15) out(array('ok' => false, 'error' => 'Biroz kuting — namuna 15 soniyada bir marta yuboriladi'), 429);
        setset('smp_' . $me, time()); @set_time_limit(60);
        if ($k === 'a' || $k === 'b') {
            $png = $k === 'a' ? png_card() : png_list();
            if ($png === false) out(array('ok' => false, 'error' => 'Rasm yaratilmadi: ' . (!empty($GLOBALS['CARD_ERR']) ? $GLOBALS['CARD_ERR'] : 'kurs hali olinmagan')));
            $r = tg_photo($me, $png, owner_cap($me, $k, frame_cap($k), array('{sana}' => date('d.m.Y'))));
        } elseif ($k === 'c') {
            $h = pr_home(); $png = !empty($h['ok']) ? png_prayer($h) : false;
            if ($png === false) out(array('ok' => false, 'error' => 'Namoz vaqtlari hozircha olinmadi, birozdan keyin urinib ko\'ring'));
            $r = tg_photo($me, $png, owner_cap($me, 'c', pimg_cap($h), array('{namoz}' => ($h['tomorrow'] ? 'Ertaga ' : '') . $h['name'], '{sana}' => $h['date'])));
        } elseif ($k === 'w') {
            $d = wx_data(); if (!$d) out(array('ok' => false, 'error' => 'Ob-havo ma\'lumoti hozircha olinmadi, birozdan keyin urinib ko\'ring'));
            $fid = null; $r = wx_photo($me, png_weather($d), owner_cap($me, 'w', wx_cap(), array('{sana}' => date('d.m.Y'))), $fid);
        } else {
            $it = dp_item((int)date('N')); if (!$it) out(array('ok' => false, 'error' => 'Bugungi tongi xabar hali sozlanmagan'));
            $p = $it[1] + array('chat_id' => $me); $r = pr_call($it[0], $p);
            if (empty($r['ok']) && isset($r['description']) && stripos($r['description'], 'parse entities') !== false) $r = pr_call($it[0], dp_plain($p));
        }
        if (empty($r['ok'])) { $d = isset($r['description']) ? (string)$r['description'] : '';
            out(array('ok' => false, 'error' => preg_match('/chat not found|blocked|initiate/i', $d) ? 'Avval @' . BOT_USERNAME . ' ga /start bosing, keyin qayta urinib ko\'ring' : 'Yuborilmadi: ' . ($d !== '' ? $d : 'tarmoq xatosi'))); }
        out(array('ok' => true));
    }
    if ($a === 'ucap') {   /* rasm tagidagi matn (k=a|b|c|w): text berilsa saqlanadi; bo'sh — namuna ishlatiladi */
        $k = isset($in['k']) ? (string)$in['k'] : '';
        if (!in_array($k, array('a', 'b', 'c', 'w'), true)) out(array('ok' => false, 'error' => 'Noto\'g\'ri tur'), 422);
        if (isset($in['text'])) {
            $tx = trim((string)$in['text']);
            if (mb_strlen($tx) > 1000) out(array('ok' => false, 'error' => 'Matn 1000 belgidan oshmasin'), 422);
            setset('ucap_' . $u['id'] . '_' . $k, $tx);
        }
        $def = $k === 'c' ? (string)setting('cap_c', DEF_CAP_C) : ($k === 'w' ? trim(setting('wx_head', DEF_WX_HEAD) . "\n\n" . setting('wx_foot', DEF_WX_FOOT)) : (string)setting('cap_' . $k, DEF_CAP));
        out(array('ok' => true, 'text' => (string)setting('ucap_' . $u['id'] . '_' . $k, ''), 'def' => strip_tags($def)));
    }
    if ($a === 'dp_day') {   /* tongi xabar: hafta kuni (1=Dushanba … 7=Yakshanba) — foydalanuvchining barcha ulangan chatlarida */
        $d = (int)(isset($in['d']) ? $in['d'] : 0);
        if ($d < 1 || $d > 7) out(array('ok' => false, 'error' => 'Kun noto\'g\'ri'), 422);
        foreach (q("SELECT id,dp_on,dp_days FROM chats WHERE owner=? AND status='approved'", array($u['id']))->fetchAll() as $c) {
            $m = !empty($c['dp_on']) ? ((string)$c['dp_days'] !== '' ? (string)$c['dp_days'] : '1111111') : '0000000';
            $m[$d - 1] = !empty($in['on']) ? '1' : '0';
            q('UPDATE chats SET dp_days=?, dp_on=? WHERE id=?', array($m, strpos($m, '1') !== false ? 1 : 0, $c['id']));
        }
        out(array('ok' => true));
    }
    if ($a === 'flag_all') {   /* bosh sahifa: namoz vaqtlari / ob-havo — barcha ulangan kanal va guruhlarda */
        $fm = array('pr' => 'send_c', 'wx' => 'wx_on', 'a' => 'send_a', 'b' => 'send_b', 'ev' => 'ev_on');
        $fk = isset($in['f']) ? (string)$in['f'] : ''; $f = isset($fm[$fk]) ? $fm[$fk] : 'send_c';
        q("UPDATE chats SET $f=? WHERE owner=? AND status='approved'", array(!empty($in['on']) ? 1 : 0, $u['id']));
        if ($f === 'send_a' || $f === 'send_b') q("UPDATE chats SET auto_on=IF(send_a=1 OR send_b=1,1,0) WHERE owner=? AND status='approved'", array($u['id']));
        out(array('ok' => true));
    }
    if ($a === 'wx_my_set') {
        q('UPDATE chats SET wx_on=? WHERE id=? AND owner=?', array(!empty($in['on']) ? 1 : 0, (int)(isset($in['id']) ? $in['id'] : 0), $u['id']));
        out(array('ok' => true));
    }
    if ($a === 'adm_wx' || $a === 'adm_wx_test') {
        if (!$adm) out(array('ok' => false, 'error' => 'Ruxsat yo\'q'), 403);
        if ($a === 'adm_wx_test') {
            $d = wx_data(); if (!$d) out(array('ok' => false, 'error' => 'Ob-havo ma\'lumoti olinmadi, birozdan keyin urinib ko\'ring'), 503);
            $fid = null; $r = wx_photo($u['id'], png_weather($d), wx_cap(), $fid);
            out(array('ok' => !empty($r['ok']), 'error' => !empty($r['ok']) ? '' : (isset($r['description']) ? $r['description'] : 'Yuborilmadi')));
        }
        $tm = isset($in['time']) ? (string)$in['time'] : '';
        if (!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $tm)) out(array('ok' => false, 'error' => 'Vaqt noto\'g\'ri (masalan 07:00)'), 422);
        $hd = trim((string)(isset($in['head']) ? $in['head'] : '')); $ft = trim((string)(isset($in['foot']) ? $in['foot'] : ''));
        if (mb_strlen($hd) + mb_strlen($ft) > 1000) out(array('ok' => false, 'error' => 'Rasm ostidagi matn (sarlavha + pastki matn) 1000 belgidan oshmasin'), 422);
        setset('wx_on', !empty($in['on']) ? '1' : '0'); setset('wx_time', $tm); setset('wx_head', $hd); setset('wx_foot', $ft);
        out(array('ok' => true, 'cfg' => wx_cfg()));
    }
    if ($a === 'wallet') {
        $cfg = pay_cfg();
        out(array('ok' => true, 'balance' => (int)q('SELECT balance FROM users WHERE id=?', array($u['id']))->fetchColumn(),
            'card' => $cfg['card'], 'holder' => $cfg['holder'], 'prices' => $cfg['prices'], 'min' => PAY_MIN, 'max' => PAY_MAX,
            'cnt' => array('Kanal' => (int)q('SELECT COUNT(*) ' . ad_aud('Kanal')[0])->fetchColumn() > 0 ? 1 : 0, 'Guruh' => (int)q('SELECT COUNT(*) ' . ad_aud('Guruh')[0])->fetchColumn() > 0 ? 1 : 0, 'users' => (int)q('SELECT COUNT(*) ' . ad_aud('users')[0])->fetchColumn() > 0 ? 1 : 0),   /* soni e'lon beruvchiga ko'rsatilmaydi — faqat bor/yo'q */
            'topups' => q('SELECT id,amount,status,created_at FROM topups WHERE user_id=? ORDER BY id DESC LIMIT 10', array($u['id']))->fetchAll(),
            'orders' => q('SELECT id,kind,price,status,created_at FROM ad_orders WHERE user_id=? ORDER BY id DESC LIMIT 10', array($u['id']))->fetchAll()));
    }
    if ($a === 'topup_new') {
