        $audit('bank_del', $cur . ' ' . $bank); out(array('ok' => true, 'banks' => bank_rows()));
    }
    if ($a === 'adm_banks') out(array('ok' => true, 'banks' => bank_rows(), 'mkb' => mkb_state(), 'tb' => tb_state(), 'xb' => xb_state()));
    if ($a === 'adm_cardstyle') {   /* kurs rasmi dizayni: A / B / C — tanlash va namuna */
        $sv = isset($in['s']) ? (string)$in['s'] : ''; if (!in_array($sv, array('A', 'B', 'C'), true)) $sv = setting('card_style', 'C');
        if (!empty($in['save'])) { setset('card_style', $sv); $audit('card_style', $sv); }
        $png = png_card($sv);
        out(array('ok' => true, 's' => setting('card_style', 'C'), 'img' => $png === false ? '' : 'data:image/png;base64,' . base64_encode($png), 'err' => $png === false ? (string)$GLOBALS['CARD_ERR'] : ''));
    }
    if ($a === 'adm_xbchk') {   /* barcha banklar saytini parallel tekshiradi — qaysi biridan USD olish/sotish kursi olinadi */
        @set_time_limit(90); $L = xb_list(); $urls = array(); foreach ($L as $b) foreach (array_slice($b, 1) as $u) $urls[] = $u;
        $res = multi_get($urls, 12); $ref = xb_ref(); $o = array(); $buys = array();
        foreach ($L as $id => $b) {   /* har bir manbadan alohida: bankning o'z sayti va bank.uz */
            $own = null; $agg = null; $err = ''; $pf = '';
            foreach (array_slice($b, 1) as $u) {
                list($html, $e) = $res[$u]; $isagg = strpos($u, 'bank.uz/uz/currency/bank/') !== false;
                if ($html === null) { if ($err === '') $err = parse_url($u, PHP_URL_HOST) . ': ' . $e; continue; }
                $p = mkb_parse($html, $ref);
                if (is_string($p)) { if ($pf === '') $pf = parse_url($u, PHP_URL_HOST) . ': sahifa ochildi, kurs topilmadi'; continue; }
                if ($isagg && !$agg) $agg = array($p[0], $p[1], $u); elseif (!$isagg && !$own) $own = array($p[0], $p[1], $u);
            }
            $use = $own ? $own : $agg;
            $r = array('id' => $id, 'name' => $b[0], 'ok' => (bool)$use, 'err' => $use ? '' : ($pf !== '' ? $pf : $err), 'grade' => '', 'note' => '');
            if ($use) {
                $r['buy'] = $use[0]; $r['sell'] = $use[1]; $r['url'] = $use[2]; $buys[] = $use[0];
                if ($own && $agg) {
                    $same = abs($own[0] - $agg[0]) <= 15 && abs($own[1] - $agg[1]) <= 15;
                    $r['grade'] = $same ? 'aniq' : 'farq';
                    $r['note'] = $same ? 'bank sayti va bank.uz bir xil' : 'bank sayti ' . n0($own[0]) . '/' . n0($own[1]) . ', bank.uz ' . n0($agg[0]) . '/' . n0($agg[1]);
                } else { $r['grade'] = 'bitta'; $r['note'] = 'faqat ' . ($own ? 'bank sayti' : 'bank.uz') . ' ochildi — solishtirib bo\'lmadi'; }
                $sp = $use[1] - $use[0];
                if ($sp < 25 || $sp > 400) { $r['grade'] = 'shubhali'; $r['note'] = 'olish va sotish farqi ' . n0($sp) . ' so\'m — odatdagi naqd kurs emas (karta yoki konversiya kursi bo\'lishi mumkin)'; }
            }
            $o[] = $r;
        }
        sort($buys); $med = $buys ? $buys[(int)floor(count($buys) / 2)] : 0;   /* boshqa banklardan keskin farq qilsa — shubhali */
        foreach ($o as &$r) if ($r['ok'] && $med && abs($r['buy'] - $med) / $med > 0.012) { $r['grade'] = 'shubhali'; $r['note'] = 'boshqa banklardan keskin farq qiladi (o\'rtacha olish ' . n0($med) . ')'; }
        unset($r);
        out(array('ok' => true, 'res' => $o));
    }
    if ($a === 'adm_alert') { setset('al_on', !empty($in['on']) ? '1' : '0'); out(array('ok' => true, 'on' => setting('al_on', '1') === '1')); }
    if ($a === 'adm_xbrun') out(array('ok' => true, 'msg' => xb_fetch(true), 'xb' => xb_state(), 'banks' => bank_rows()));   /* hozir yangilash */
    if ($a === 'adm_xbset') {   /* tanlangan banklarni saqlaydi va darrov yangilaydi */
        $L = xb_list(); $on = array();
        foreach ((array)(isset($in['on']) ? $in['on'] : array()) as $id) if (is_string($id) && isset($L[$id])) $on[] = $id;
        foreach ($L as $id => $b) if (!in_array($id, $on, true)) q("DELETE FROM rates WHERE kind='bank' AND manual=0 AND bank=?", array($b[0]));
        setset('xb_on', implode(',', $on)); $audit('xb_cfg', implode(',', $on));
        $msg = $on ? xb_fetch(true) : '';
        out(array('ok' => true, 'msg' => $msg, 'xb' => xb_state(), 'banks' => bank_rows()));
    }
    if ($a === 'adm_tb') {   /* Turonbank avtomatik: sozlash / hozir yangilash */
        $msg = '';
        if (isset($in['on'])) {
            $urls = array();
            foreach (preg_split('/\R/', (string)(isset($in['urls']) ? $in['urls'] : '')) as $u) { $u = trim($u); if (preg_match('#^https?://[^\s]+$#i', $u)) $urls[] = mb_substr($u, 0, 300); }
            setset('tb_on', !empty($in['on']) ? '1' : '0'); setset('tb_urls', $urls ? implode("\n", array_slice($urls, 0, 5)) : TB_URLS);
            setset('tb_int', (string)max(5, min(720, (int)(isset($in['int']) ? $in['int'] : 15))));
            $audit('tb_cfg', (!empty($in['on']) ? 'yoq' : 'ochiq') . ' ' . implode(' ', $urls));
        }
        if (!empty($in['run'])) $msg = tb_fetch(true);
        out(array('ok' => true, 'msg' => $msg, 'tb' => tb_state(), 'banks' => bank_rows()));
    }
    if ($a === 'adm_mkb') {
        $msg = '';
        if (isset($in['on'])) {
            $urls = array();
            foreach (preg_split('/\R/', (string)(isset($in['urls']) ? $in['urls'] : '')) as $u) { $u = trim($u); if (preg_match('#^https?://[^\s]+$#i', $u)) $urls[] = mb_substr($u, 0, 300); }
            setset('mkb_on', !empty($in['on']) ? '1' : '0'); setset('mkb_urls', $urls ? implode("\n", array_slice($urls, 0, 5)) : MKB_URLS);
            setset('mkb_int', (string)max(5, min(720, (int)(isset($in['int']) ? $in['int'] : 15))));
            $audit('mkb_cfg', (!empty($in['on']) ? 'yoq' : 'ochiq') . ' ' . implode(' ', $urls));
        }
        if (!empty($in['run'])) $msg = mkb_fetch(true);
        out(array('ok' => true, 'msg' => $msg, 'mkb' => mkb_state(), 'banks' => bank_rows()));
    }
    out(array('ok' => false, 'error' => 'Noma\'lum amal'), 404);
}

