.cbx{background:#f3f6fb;border-radius:14px;padding:12px 14px;margin:10px 0}.cp{border:0;background:#fff;border-radius:8px;width:30px;height:30px;display:flex;align-items:center;justify-content:center;padding:0;flex:none}.cp svg{width:16px;height:16px}
.cps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:8px}.chip{border:0;background:#f3f6fb;color:var(--ac);font-weight:600;font-size:11.5px;line-height:1.1;padding:7px 2px;margin:0;width:100%;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;white-space:nowrap;overflow:hidden}.chip i{font-style:normal;font-size:18px;line-height:1}.chip.on{background:var(--ac);color:#fff}
.up{display:block;background:#eef1f6;color:var(--ac);font-weight:600;text-align:center;padding:12px;border-radius:12px;margin:8px 0}
.dwh{display:flex;align-items:center;justify-content:space-between;padding:0 2px 10px 6px}.dwb{display:block;line-height:1}.ugl{display:flex;align-items:baseline;font-size:33px;font-weight:900;font-style:italic;letter-spacing:-1.2px;line-height:1.05}.ugl b{font-weight:900;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;padding:0 3px 2px 0}.ug1{background-image:linear-gradient(180deg,#0f172a 30%,#5b6b85)}html.dark .ug1{background-image:linear-gradient(180deg,#fff 35%,#c4cde0)}.ug2{background-image:linear-gradient(90deg,#14c8f5,#2563ff)}.ug3{background-image:linear-gradient(90deg,#7c4dff,#b15cff)}.ugt{margin-top:6px;padding-left:3px;font-size:12.5px;font-weight:600;letter-spacing:2.6px;color:var(--tx);opacity:.82}.dwx{border:0;background:transparent;width:34px;height:34px;display:flex;align-items:center;justify-content:center;padding:0}.dwx svg{width:22px;height:22px;stroke:#8e8e93;stroke-width:2;fill:none;stroke-linecap:round}
.dwc{background:#fff;border-radius:20px}.dwp{display:flex;align-items:center;gap:12px;padding:11px 14px;margin-bottom:8px}.dwa{position:relative;width:46px;height:46px;border-radius:50%;background:#7fe9d4;color:#fff;font-size:19px;font-weight:600;display:flex;align-items:center;justify-content:center;flex:none;overflow:hidden}.dwa img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.dwn{min-width:0}.dwn b{display:block;font-size:16px;font-weight:700;color:#000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dwn span{display:block;font-size:13px;color:#8e8e93;margin-top:1px}
.dws{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-bottom:8px}.dws>div{background:#fff;border-radius:18px;padding:9px 2px 8px;text-align:center}.dws i,.dwi{width:32px;height:32px;border-radius:50%;background:#e8f0fe;display:flex;align-items:center;justify-content:center;flex:none}.dws i{margin:0 auto 5px}.dws i svg,.dwi svg{width:17px;height:17px;stroke:#4a86e8;stroke-width:1.9;fill:none;stroke-linecap:round;stroke-linejoin:round}.dws b{display:block;font-size:16px;font-weight:700;color:#000;line-height:1.2}.dws span{display:block;font-size:11px;color:#8e8e93;margin-top:1px}
.dwm{display:flex;align-items:center;gap:11px;width:100%;border:0;background:#fff;border-radius:18px;padding:8px 12px;margin-bottom:6px;text-align:left;color:#000;font-size:15px;font-weight:600}.dwm>span:not(.dwi){flex:1}.dwm .ch{width:16px;height:16px;stroke:#c7c7cc;stroke-width:2.2;fill:none;stroke-linecap:round;stroke-linejoin:round;flex:none}

/* ===== Zamonaviy ko'rinish: yorug' va tungi tema (Telegram mavzusiga moslashadi) ===== */
:root{--bg:#f2f4f8;--cd:#fff;--in:#f1f3f7;--tx:#0f172a;--sub:#7b8494;--ln:#eceff4;--soft:#eaf1ff;--ac:#2f7cf6;--ac2:#5b5cf6;--sw:#d5d9e1;--sh:0 1px 2px rgba(16,24,40,.04),0 8px 24px rgba(16,24,40,.06)}
html.dark{--bg:#0e1116;--cd:#181c23;--in:#232934;--tx:#eef2f7;--sub:#97a1b3;--ln:#262c37;--soft:#1b2944;--ac:#4c8dff;--ac2:#7c7dff;--sw:#3a4150;--sh:0 1px 2px rgba(0,0,0,.35),0 10px 26px rgba(0,0,0,.28);color-scheme:dark}
body,.top,#gate,.md{background:var(--bg);color:var(--tx)}
body{font-family:-apple-system,"SF Pro Text",Inter,Roboto,"Segoe UI",Arial,sans-serif;-webkit-font-smoothing:antialiased}
h1{font-size:24px;font-weight:800;letter-spacing:-.4px}
.tt b,.dt,.dwb,.dwn b,.dws b,.dwm,.at,.tb{color:var(--tx)}
.card,.bk,.cbf,.mk,.rb,.qa,.dt,.bkb,.mb,.tb,.dwc,.dws>div,.dwm,.at{background:var(--cd);box-shadow:var(--sh)}
.card{border-radius:22px}.at{border-radius:22px}.at small,.dwn span,.dws span{color:var(--sub)}
input,select,textarea{background:var(--in);color:var(--tx);border:1.5px solid transparent;transition:border-color .15s,box-shadow .15s,background .15s}
input:focus,select:focus,textarea:focus{border-color:var(--ac);background:var(--cd);box-shadow:0 0 0 4px rgba(47,124,246,.16)}
input::placeholder,textarea::placeholder{color:var(--sub);opacity:.8}
.fl,.chip,.up,.cbx,.mi,.mh button,.qt,.lg,.rb .ri,.bh .ri2,.all{background:var(--in)}
.btn{background:linear-gradient(135deg,var(--ac),var(--ac2));box-shadow:0 8px 18px rgba(47,124,246,.28);transition:transform .12s,box-shadow .12s,opacity .12s}
.btn.s{background:var(--soft);color:var(--ac);box-shadow:none;font-weight:700}
.btn:disabled{opacity:.55}
.btn:active,.dwm:active,.at:active,.bkb:active,[onclick].card:active,[onclick].row:active,[onclick].card.row:active{transform:scale(.975)}
.tag{background:var(--in);color:var(--sub);font-weight:600;border-radius:999px}
.sk{background:linear-gradient(90deg,var(--cd),var(--in),var(--cd));background-size:200%;border-radius:22px}
.pg.on{animation:pgin .28s cubic-bezier(.2,.8,.2,1)}@keyframes pgin{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
#toast{border-radius:18px;background:rgba(22,24,30,.92);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);animation:pgin .2s}
details>summary{cursor:pointer;list-style:none;padding:6px 0}details>summary::-webkit-details-marker{display:none}
details>summary:before{content:'›';display:inline-block;width:14px;margin-right:4px;transition:transform .2s;color:var(--sub);font-weight:800}details[open]>summary:before{transform:rotate(90deg)}
/* iOS uslubidagi yoqish/o'chirish tugmachasi (ck) */
.sw{position:relative;display:inline-block;width:46px;height:28px;border-radius:28px;background:var(--sw);flex:none;order:9;margin-left:auto;transition:background .2s}
.sw:after{content:'';position:absolute;top:3px;left:3px;width:22px;height:22px;border-radius:50%;background:#fff;box-shadow:0 2px 5px rgba(0,0,0,.22);transition:transform .22s cubic-bezier(.2,.8,.2,1)}
.sw.on{background:#34c759}.sw.on:after{transform:translateX(18px)}
div:has(>.sw){flex:1}
.mo{background:rgba(8,12,20,.45)}
.dws i,.dwi{background:var(--soft)}.dwm{border-radius:16px}
nav a{background:rgba(255,255,255,.86)}html.dark nav a{background:rgba(24,28,35,.86);box-shadow:0 6px 24px rgba(0,0,0,.45)}nav a.on{background:var(--soft)}
html.dark .cp{background:var(--cd)}html.dark .dwx svg{stroke:var(--sub)}html.dark .dwm .ch{stroke:#4a5161}
html.dark .pl.gg{background:rgba(52,199,89,.16)}html.dark .pl.pp{background:rgba(255,59,48,.16)}
html.dark img{opacity:.96}
[style*="background:#eef1f6"],[style*="background:#f3f6fb"]{background:var(--in)!important;color:var(--tx)}
.md{box-shadow:none}.md.on{box-shadow:4px 0 24px rgba(0,0,0,.18)}
/* menyu: ixcham profil va statistika */.dwp{gap:10px;padding:8px 12px;margin-bottom:6px;border-radius:16px}.dwa{width:36px;height:36px;font-size:15px}.dwn b{font-size:15px;line-height:1.2}.dwn span{font-size:12px;margin-top:0}.dws{gap:6px;margin-bottom:6px}.dws>div{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto auto;column-gap:7px;align-items:center;padding:8px 9px 7px;border-radius:14px;text-align:left;min-width:0}.dws i{grid-row:1;width:24px;height:24px;margin:0}.dws b{grid-column:2}.dws span{grid-column:1/3;margin-top:4px!important}.dws i svg{width:13px;height:13px}.dws b{font-size:16px;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dws span{font-size:11px;line-height:1.2;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.abl{margin:10px 0 0;padding-left:0;list-style:none}.abl li{margin:0 0 9px;line-height:1.45;font-size:14px;color:var(--tx)}.abs{display:flex;gap:12px;align-items:flex-start;padding:12px 0 2px;border-top:1px solid var(--ln);margin-top:10px}.abs i{flex:none;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,#2f80ed,#5b5cf6);color:#fff;font-style:normal;font-weight:700;font-size:14px;display:flex;align-items:center;justify-content:center}.abs b{font-size:15px}.abs p{margin:3px 0 0;line-height:1.45}.abq{margin:10px 0 0;line-height:1.45}.abq b{color:var(--tx)}.abh{padding-top:18px;padding-bottom:16px}
/* ===== TartibOn dizayni ===== */
:root{--bg:#f2f5fa;--cd:#fff;--in:#f2f5fa;--tx:#0f1b2d;--sub:#7d8799;--ln:#edf0f5;--soft:#e7f1ff;--ac:#1d84f2;--ac2:#1a6fe0;--g:#22b35e;--r:#ef4444;--gs:#e3f8ea;--sh:0 1px 2px rgba(16,24,40,.04),0 6px 20px rgba(16,24,40,.05)}
html.dark{--bg:#0d1117;--cd:#171c24;--in:#212834;--tx:#eef2f7;--sub:#93a0b4;--ln:#252c38;--soft:#16294a;--ac:#3d93ff;--ac2:#2f7cf6;--gs:#173726;--sh:0 1px 2px rgba(0,0,0,.35),0 8px 22px rgba(0,0,0,.28)}
body{background:var(--bg)}
.sheet{padding:4px 14px calc(24px + env(safe-area-inset-bottom))}
h1{font-size:26px;font-weight:800;letter-spacing:-.5px;margin:6px 2px 14px}
.card,.bk{border-radius:20px}
.btn{background:var(--ac);box-shadow:0 6px 16px rgba(29,132,242,.28);border-radius:14px}
.bkb{background:none!important;box-shadow:none!important;padding:4px 2px;margin:0 0 6px;color:var(--ac);font-size:16px}
/* sarlavha */
.th{display:flex;align-items:center;gap:10px;padding:calc(10px + env(safe-area-inset-top)) 16px 10px;background:var(--bg)}
.ava{position:relative;width:42px;height:42px;border-radius:50%;border:0;padding:0;background:linear-gradient(135deg,#7cc4ff,#1d84f2);color:#fff;font-weight:800;font-size:17px;overflow:hidden;flex:none}
.ava img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.brand{flex:1;min-width:0;text-align:center}
.bl{display:inline-flex;align-items:center;gap:8px}
.bi{width:32px;height:32px;border-radius:9px;background:linear-gradient(135deg,#3aa0ff,#1d6fe8);display:flex;align-items:center;justify-content:center;box-shadow:0 4px 10px rgba(29,111,232,.35)}
.bi svg{width:19px;height:19px;stroke:#fff;stroke-width:2.2;fill:none;stroke-linecap:round;stroke-linejoin:round}
.wm{display:inline-flex;align-items:baseline;font-family:Poppins,Nunito,-apple-system,Roboto,sans-serif;font-weight:900;font-size:28px;letter-spacing:-.02em;line-height:1}
.wm .w1{color:var(--tx)}
.wm .w2{display:inline-flex;align-items:baseline;background:linear-gradient(180deg,#4ade63 20%,#10dcd8 90%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent}
.wm .pw{width:.798em;height:.894em;margin:0 .01em 0 .03em;fill:none;stroke:url(#tpw);stroke-width:24;stroke-linecap:round;transform:translateY(.04em);flex:none}
.wm.big{font-size:44px}.wm.big .pw{stroke-width:24}
.bs{font-size:12.5px;color:var(--sub);margin-top:5px}
.thsp{width:42px;height:42px;flex:none}.gear{width:42px;height:42px;border:0;background:none;display:flex;align-items:center;justify-content:center;padding:0;flex:none}
.gear svg{width:26px;height:26px;stroke:var(--sub);stroke-width:1.9;fill:none;stroke-linecap:round;stroke-linejoin:round}
/* asosiy kurs */
.hero{background:linear-gradient(180deg,#eaf3ff,#f6faff);border-radius:22px;padding:16px;margin:0 0 14px;text-align:center;position:relative;box-shadow:var(--sh)}
html.dark .hero{background:linear-gradient(180deg,#16263f,#141c29)}
.hero .hl1{font-size:13px;color:var(--ac);font-weight:600}
.hero .hb{font-size:38px;font-weight:800;letter-spacing:-1px;margin:6px 0 12px;color:var(--tx)}
.hero .hb small{font-size:.75em;font-weight:800}
.hpills{display:flex;gap:10px}
.hpills div{flex:1;border-radius:999px;padding:10px 8px;font-size:15px;font-weight:600;background:var(--cd);color:var(--tx);white-space:nowrap}
.hpills .hg{background:#bff0cf;color:#0b3d1f}html.dark .hpills .hg{background:#1d4a2e;color:#c9f5d8}
.hpills .hg i{font-style:normal;color:#14a34a;font-size:12px;margin-left:3px}
.hero .rfi{position:absolute;top:10px;right:10px;width:32px;height:32px;border:0;border-radius:50%;background:var(--cd);color:var(--ac);font-size:16px;box-shadow:var(--sh)}
.hero .hs{font-size:11.5px;color:var(--sub);margin-top:10px}
/* tezkor tugmalar */
.qk{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:0 0 16px}
.qk button{border:0;background:none;padding:0;display:flex;flex-direction:column;align-items:center;gap:7px;color:var(--tx);font-size:12.5px;font-weight:500}
.ti{width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 6px 14px rgba(16,24,40,.12)}
.ti svg,.tl svg,.lr .li svg,.sti svg{width:24px;height:24px;stroke:#fff;stroke-width:2;fill:none;stroke-linecap:round;stroke-linejoin:round}
.c1{background:linear-gradient(135deg,#3aa0ff,#1d6fe8)}.c2{background:linear-gradient(135deg,#34d399,#16a34a)}.c3{background:linear-gradient(135deg,#fbbf24,#f59e0b)}.c4{background:linear-gradient(135deg,#a78bfa,#7c3aed)}.c5{background:linear-gradient(135deg,#2dd4bf,#0d9488)}.c6{background:linear-gradient(135deg,#f472b6,#db2777)}.c7{background:linear-gradient(135deg,#f87171,#dc2626)}.c8{background:linear-gradient(135deg,#94a3b8,#64748b)}.c9{background:linear-gradient(135deg,#c084fc,#9333ea)}
/* bo'lim kartasi */
.sc{background:var(--cd);border-radius:20px;padding:12px 14px;margin:0 0 12px;box-shadow:var(--sh)}
.sh2{display:flex;align-items:center;gap:6px;margin:0 0 8px;font-weight:700;font-size:15px;color:var(--tx)}
.sh2:before{content:'';width:4px;height:14px;border-radius:2px;background:var(--g)}
.sh2 .sub{font-weight:500;font-size:13px}.sh2 .chv2{margin-left:auto;color:var(--sub);font-weight:400;font-size:20px;line-height:1}
.cu{display:flex;align-items:center;gap:10px;padding:7px 0}
.cb3{width:44px;height:28px;border-radius:9px;color:#fff;font-weight:700;font-size:12.5px;display:flex;align-items:center;justify-content:center;flex:none}
.cu .cn{flex:1;min-width:0;font-size:13px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cu .cv{font-weight:700;font-size:16px;color:var(--tx);white-space:nowrap}
.cu .cd2{width:72px;text-align:right;font-size:12.5px;font-weight:600;white-space:nowrap}
.up2{color:var(--g)}.dn2{color:var(--r)}
.ptb{display:grid;grid-template-columns:1fr 1fr;column-gap:22px}
.ptb div{display:flex;justify-content:space-between;padding:4px 0;font-size:13.5px;color:var(--tx)}
.ptb div b{font-weight:600}.ptb .me{color:var(--ac);font-weight:700}
.wgr{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.wgr>div{border:1px solid var(--ln);border-radius:12px;padding:6px 6px 5px;display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:4px;align-items:center}
.wgr .wi{grid-row:1/3;font-size:20px}.wgr .wn{font-size:10.5px;color:var(--tx);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.wgr .wt{font-size:12.5px;font-weight:700;white-space:nowrap}.wgr .wt span{color:var(--sub);font-weight:500;font-size:11px}
/* pastki menyu */
nav.tbar{position:fixed;left:0;right:0;bottom:0;display:flex;justify-content:space-around;padding:8px 6px calc(8px + env(safe-area-inset-bottom));background:color-mix(in srgb,var(--cd) 92%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border-top:1px solid var(--ln);pointer-events:auto;z-index:30}
nav.tbar a{flex:1;min-width:0;background:none!important;box-shadow:none!important;padding:4px 0;border-radius:0;color:var(--sub);font-size:11.5px;font-weight:500;display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer}
nav.tbar a svg{width:25px;height:25px;stroke:currentColor;stroke-width:1.8;fill:none;stroke-linecap:round;stroke-linejoin:round}
nav.tbar a.on{color:var(--ac);font-weight:700}nav.tbar a.on svg{fill:var(--ac);stroke:var(--ac)}nav.tbar a.on svg .k{stroke:#fff}
/* vositalar */
.phd{display:flex;align-items:center;justify-content:space-between;gap:10px}.phd h1{margin:6px 2px 14px}
.balp{background:var(--soft);color:var(--ac);font-weight:600;font-size:14px;border-radius:999px;padding:7px 14px;cursor:pointer;white-space:nowrap}
.tg2{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px 6px;padding:4px 0 6px}
.tg2 button{border:0;background:none;padding:0;display:flex;flex-direction:column;align-items:center;gap:7px;color:var(--tx);font-size:12px;line-height:1.2;text-align:center}
.tl{width:54px;height:54px;border-radius:16px;display:flex;align-items:center;justify-content:center;box-shadow:0 6px 14px rgba(16,24,40,.12)}
.tl svg{width:26px;height:26px}
/* ro'yxat qatorlari (admin, chat sozlamalari) */
.lr{display:flex;align-items:center;gap:12px;width:100%;border:0;background:var(--cd);border-radius:16px;padding:11px 12px;margin:0 0 8px;text-align:left;color:var(--tx);box-shadow:var(--sh)}
.lr .li{width:40px;height:40px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex:none}
.lr .lt{flex:1;min-width:0}.lr .lt b{display:block;font-size:15px;font-weight:600}.lr .lt span{display:block;font-size:12.5px;color:var(--sub);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lr .ch3{color:#b8c0cc;font-size:22px;line-height:1}
.lr.in{box-shadow:none;border-radius:0;background:none;padding:10px 0;margin:0;border-top:1px solid var(--ln)}.lr.in:first-of-type{border-top:0}
.stg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0 0 12px}
.stg>div{background:var(--cd);border-radius:18px;padding:12px;box-shadow:var(--sh);min-width:0}
.sti{width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;margin-bottom:8px}.sti svg{width:19px;height:19px}
.stg span{display:block;font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.stg b{display:block;font-size:22px;font-weight:800;color:var(--tx);margin-top:2px}.stg small{font-size:11.5px;color:var(--g);font-weight:600}
.chd{text-align:center;padding:6px 0 4px}
.chd .cav{width:84px;height:84px;border-radius:50%;margin:0 auto 10px;background:linear-gradient(135deg,#7cc4ff,#1d84f2);color:#fff;font-size:34px;font-weight:800;display:flex;align-items:center;justify-content:center}
.chd b{font-size:20px}.chd .cs{font-size:12.5px;color:var(--g);margin-top:4px}.chd .cs.no{color:#f59e0b}
/* switch (barcha checkboxlar) */
input[type=checkbox]{-webkit-appearance:none;appearance:none;position:relative;width:48px!important;height:29px;border-radius:29px;background:#d5dae2;margin:0 8px 0 0!important;padding:0;flex:none;vertical-align:middle;cursor:pointer;transition:background .2s;border:0!important;box-shadow:none!important}
html.dark input[type=checkbox]{background:#3a4150}
input[type=checkbox]:after{content:'';position:absolute;top:3px;left:3px;width:23px;height:23px;border-radius:50%;background:#fff;box-shadow:0 2px 5px rgba(0,0,0,.22);transition:transform .2s cubic-bezier(.2,.8,.2,1)}
input[type=checkbox]:checked{background:var(--ac)}input[type=checkbox]:checked:after{transform:translateX(19px)}
.lr input[type=checkbox]{margin:0!important}
.sw.on{background:var(--ac)}
#toast{top:auto;bottom:calc(24px + env(safe-area-inset-bottom))}
.bh{flex-wrap:nowrap}.bh b{white-space:nowrap}.bh .chip{width:auto;flex:none;flex-direction:row;margin-left:auto;padding:6px 10px;font-size:12px}
/* v2: bosh sahifa */
.hero{padding:18px 16px 14px}
.hero .hb{margin:4px 0 2px}.hero .hb .hdc{font-size:.5em;font-weight:700;color:var(--sub)}
.hdl{font-size:12.5px;font-weight:600;margin-bottom:12px}
.hmk{background:var(--cd);border-radius:18px;padding:12px;margin-top:12px;text-align:left}
.hmh{display:flex;justify-content:space-between;align-items:center;font-weight:700;font-size:14px;color:var(--tx);margin-bottom:10px}.hmh span{font-weight:500;font-size:12px;color:var(--sub)}
.hpills div{border-radius:14px;padding:9px 8px;font-size:20px;font-weight:800;text-align:center}
.hpills small{display:block;font-size:12px;font-weight:600;opacity:.8;margin-bottom:2px}
.hpills .hg{background:#dcf7e6;color:#13803d}.hpills .hr{background:#fde4e4;color:#c81e1e}
html.dark .hpills .hg{background:#173726;color:#7ee2a2}html.dark .hpills .hr{background:#3d1b1e;color:#ff9a9a}
.cu{padding:11px 0;border-top:1px solid var(--ln)}.sh2+.cu{border-top:0;padding-top:4px}
.fl2{width:38px;height:38px;border-radius:50%;background:var(--in);display:flex;align-items:center;justify-content:center;font-size:24px;flex:none;overflow:hidden}
.cu .cn{display:flex;flex-direction:column;font-size:12px}.cu .cn b{font-size:15px;color:var(--tx)}
.pgr{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.pgr>div{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:10px 12px;border-radius:14px;background:var(--in);font-size:14px;color:var(--tx)}
.pgr>div span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pgr>div b{font-size:16px;font-weight:700}
.pgr>.me{background:var(--soft);box-shadow:inset 0 0 0 1.5px var(--ac)}.pgr>.me span{color:var(--ac);font-weight:700}
.wgr{grid-template-columns:repeat(3,minmax(0,1fr))}.wgr .wn{font-size:12px}.wgr .wt{font-size:14px}
/* v3: Telegram uslubidagi och ko'k kartalar (yorug' tema) */
html:not(.dark){--bg:#e3effc;--cd:#fff;--in:#f1f6fd;--ln:#e5edf7;--soft:#dcebfd;--sh:0 1px 2px rgba(29,132,242,.05),0 6px 18px rgba(29,132,242,.07)}
html:not(.dark) .hero{background:linear-gradient(180deg,#fff,#f6faff)}
html:not(.dark) .hmk,html:not(.dark) .hero .rfi,html:not(.dark) .fl2{background:#eef5fd}
html:not(.dark) .wgr>div{background:#f2f7fd;border-color:#f2f7fd}
/* Bosh sahifa: Kanal / Guruh qo'shish kataklari */
.tq-add{display:flex;flex-direction:column;gap:10px;margin:0 0 12px}
.tq-a{display:flex;align-items:center;gap:14px;width:100%;padding:14px 16px;border:0;border-radius:20px;background:var(--cd);box-shadow:var(--sh);color:var(--tx);font:inherit;text-align:left;cursor:pointer;transition:transform .12s}
.tq-a:active{transform:scale(.98)}
.tq-i{width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;flex:none}
.tq-i svg{width:24px;height:24px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.tq-k{background:linear-gradient(135deg,#3aa0ff,#1d6fe8);box-shadow:0 4px 12px rgba(29,111,232,.3)}
.tq-g{background:linear-gradient(135deg,#34d17a,#12b39a);box-shadow:0 4px 12px rgba(18,179,120,.3)}
.tq-t{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}.tq-t b{font-size:16.5px;font-weight:700}.tq-t span{font-size:12.5px;color:var(--sub)}
.tq-c{font-size:26px;line-height:1;color:var(--sub);flex:none}
.tq-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.tq-s{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:1px;min-width:0;margin:0;padding:11px 12px;border:0;border-radius:18px;background:var(--cd);box-shadow:var(--sh);color:var(--tx);font:inherit;text-align:left;cursor:pointer;transition:transform .12s;-webkit-user-select:none;user-select:none}
.tq-s:active{transform:scale(.97)}.tq-s .tq-i{width:36px;height:36px;border-radius:11px;margin-bottom:7px}.tq-s .tq-i svg{width:20px;height:20px}
.tq-s b{font-size:15px;font-weight:700;line-height:1.25}.tq-u{font-size:12px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.tq-s .tq-c{position:absolute;top:13px;right:12px;font-size:24px}
.lr.tq-off .li,.lr.tq-off .lt{opacity:.5}.tq-badge{flex:none;padding:3px 8px;border-radius:9px;background:var(--soft);color:var(--ac);font-size:11px;font-weight:700}
.tq-hero{position:relative;overflow:hidden;margin:0 0 10px;padding:18px 18px 20px;border-radius:22px;background:linear-gradient(135deg,#168FFF,#0789F9 45%,#006DE5);color:#fff;box-shadow:0 8px 22px rgba(0,109,229,.28)}
.tq-hero b{position:relative;display:block;font-size:19px;font-weight:800;line-height:1.25;margin-right:60px}.tq-hero p{position:relative;margin:8px 0 0;font-size:14px;line-height:1.45;opacity:.92}
.tq-hp{position:absolute;right:-12px;top:-8px;width:110px;height:110px;fill:#fff;opacity:.13;transform:rotate(-12deg)}
.tq-st{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0 0 12px}.tq-st>div{display:flex;align-items:center;gap:8px;padding:9px 10px;border-radius:16px;background:var(--cd);box-shadow:var(--sh);min-width:0}
.tq-st .tq-i{width:30px;height:30px;border-radius:9px;margin:0;flex:none}.tq-st .tq-i svg{width:17px;height:17px}.tq-sv{display:flex;flex-direction:column;min-width:0;line-height:1.15}.tq-sv b{font-size:16px;font-weight:800;color:var(--tx);white-space:nowrap}.tq-sv span{font-size:11.5px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tq-ok{position:absolute;top:12px;right:12px;font-size:18px;line-height:1}
.tq-off{cursor:default}.tq-off:active{transform:none}.tq-off .tq-i,.tq-off b,.tq-off .tq-u{opacity:.5}.tq-soon{position:absolute;top:12px;right:10px;padding:3px 8px;border-radius:9px;background:var(--soft);color:var(--ac);font-size:11px;font-weight:700}
.tq-days{padding:4px 16px}.tq-days .lr.in:first-child{border-top:0}

.qzcd{background:var(--in);border-radius:16px;padding:12px 14px;cursor:pointer;display:flex;flex-direction:column;gap:3px;border:2px solid transparent}.qzcd b{font-size:15.5px}.qzcd span{font-size:13px;color:var(--sub);line-height:1.35}.qzcd i{font-style:normal;font-size:12px;color:var(--ac);font-weight:600}.qzcd.on{border-color:var(--ac)}
.qzch{border:0;background:var(--in);color:var(--ac);font-weight:600;font-size:13px;padding:7px 11px;border-radius:12px;cursor:pointer;width:auto;margin:0}.qzch.on{background:var(--ac);color:#fff}
.qzch2{border:0;background:var(--in);color:var(--tx);border-radius:12px;padding:9px 6px;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:2px;margin:0;width:100%;min-width:0}.qzch2 b{font-size:13.5px;line-height:1.2;text-align:center}.qzch2 small{font-size:11px;color:var(--sub)}
.qzsum{margin-top:12px;padding:10px 12px;border-radius:12px;background:var(--soft);font-weight:600;font-size:14px;line-height:1.4}
