if(U)t+='<div class="hl1">🏛 Markaziy bank · 1 AQSH dollari</div><div class="hb">'+f2(U.official).split(',')[0]+'<small class="hdc">,'+f2(U.official).split(',')[1]+'</small> <small>so\'m</small></div>'+(U.d==null||+U.d==0?'':'<div class="hdl '+(U.d>0?'up2':'dn2')+'">'+(U.d>0?'▲ +':'▼ −')+f2(Math.abs(U.d))+' kechagiga nisbatan</div>');else t+='<div class="hl1">🏦 Banklarda dollar kursi</div>';var BA=[];R.forEach(function(x){if(x.code==='USD')x.banks.forEach(function(b){if(+b.buy>0&&!b.stale&&b.src!=='qo\'lda kiritilgan')BA.push(b)})});BA.sort(function(a,b){return +b.buy-+a.buy});if(BA.length)t+='<div class="hmk"><div class="hmh">Bank<span>Olish · Sotish</span></div>'+BA.map(function(b){return '<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-top:1px solid #ffffff22"><span>'+esc(b.bank)+'</span><span><b style="color:#7dffb0">'+f(b.buy)+'</b> · <b style="color:#ffb3b3">'+f(b.sell)+'</b></span></div>'}).join('')+'</div>';


t+='</div>';
$('cbh').innerHTML=t;t='';
