function mg(t,id){var n='';if(t==='chat'){AD.chats.forEach(function(c){if(c.id==id)n=c.username})}else{AD.users.forEach(function(u){if(u.id==id)n=u.name||(u.username?'@'+u.username:'ID '+u.id)})}MSG={t:t,id:id,n:n};av(AV);window.scrollTo(0,0)}
function ma(k){var n=k==='Kanal'?'Hamma kanallar':k==='Guruh'?'Hamma guruhlar':'Barcha foydalanuvchilar';MSG={t:'all',k:k,n:n};av(AV);window.scrollTo(0,0)}
function bst(k,x,off,sent,fail,tr){api('adm_bcast',{k:k,text:x,off:off}).then(function(j){if(!j.ok){$('mst').textContent='Xato: '+(j.error||'');$('mtx').disabled=false;return}sent+=j.sent;fail+=j.failed;$('mst').textContent='Yuborilmoqda: '+j.done+' / '+j.total+'  (✅ '+sent+' · ❌ '+fail+')';if(j.finished){toast('Tugadi: ✅ '+sent+' · ❌ '+fail);MSG=null;setTimeout(function(){av(AV)},2500)}else bst(k,x,j.done,sent,fail,0)}).catch(function(){if(tr<3)setTimeout(function(){bst(k,x,off,sent,fail,tr+1)},2000);else{$('mst').textContent='Aloqa uzildi ('+off+' tagacha yuborilgan)';$('mtx').disabled=false}})}
function bcs(x){var q=MSG.n+' ga xabar yuborilsinmi?';var go=function(y){if(!y)return;$('mtx').disabled=true;$('mst').textContent='Boshlanmoqda...';bst(MSG.k,x,0,0,0,0)};try{tg.showConfirm(q,go)}catch(e){go(confirm(q))}}
function sm(){var x=$('mtx').value.trim();if(!x){toast('Matn yozing');return}if(MSG.t==='all'){bcs(x);return}api('adm_msg',{t:MSG.t,id:MSG.id,text:x}).then(function(j){toast(j.ok?'Yuborildi ✅':(j.error||'Xato'));if(j.ok){MSG=null;av(AV)}})}
function ac(id,a){api('adm_chat',{id:id,act:a}).then(function(j){toast(j.ok?'Bajarildi':(j.error||'Xato'));admin()})}
function fs(k){var c=$('fc_'+k).value,o=$('fo_'+k).checked;api('adm_cap',{k:k,cap:c,on:o}).then(function(j){if(j.ok){AD.frames[k].cap=c;AD.frames[k].on=o;toast('Saqlandi ✅')}})}
function ft(k){var c=$('fc_'+k).value,o=$('fo_'+k).checked;api('adm_cap',{k:k,cap:c,on:o}).then(function(j){if(!j.ok)return;AD.frames[k].cap=c;AD.frames[k].on=o;api('adm_cap_test',{k:k}).then(function(j){toast(j.ok?'Sizga yuborildi ✅':(j.error||'Xato'))})})}
var PRK2,PRA=null,PRE=0,PRH=0,PRR=null,PRK=[['daily','🕌','Kunlik jadval'],['bomdod','🌅','Bomdod'],['quyosh','☀️','Quyosh'],['peshin','🕛','Peshin'],['asr','🌤','Asr'],['shom','🌇','Shom'],['xufton','🌙','Xufton']],PST={sent:'✅',failed:'❌',sending:'⏳'};
PRK2=PRK.concat([['saharlik','🌙','Saharlik (Ramazon)'],['iftor','🌇','Iftorlik (Ramazon)']]);
function rgo(L,sel){return L.map(function(g){return '<optgroup label="'+esc(g.name)+'">'+g.items.map(function(x){return '<option value="'+esc(x[0])+'"'+(x[0]===sel?' selected':'')+'>'+esc(x[1])+'</option>'}).join('')+'</optgroup>'}).join('')}
function prl(){var r=$('prr'),reg=r.value;if(!reg)try{reg=localStorage.getItem('pr_reg')}catch(e){}reg=reg||'Toshkent';$('prb').innerHTML='<div class="sk"></div>';
api('pr_times',{region:reg,meta:PRR?0:1}).then(function(j){if(j.regions){PRR=j.regions;r.innerHTML=rgo(PRR,j.region)}
if(!j.region){$('prb').innerHTML='<div class="card"><b>⚠️ Aloqa xatosi</b><button class="btn s" style="margin-top:10px" onclick="prl()">⟳ Qayta urinish</button></div>';return}
r.value=j.region;try{localStorage.setItem('pr_reg',j.region)}catch(e){}
if(!j.ok){$('prb').innerHTML='<div class="card"><b>⚠️ Namoz vaqtlarini olib bo\'lmadi</b><div class="sub" style="margin-top:6px">'+esc(j.msg)+'</div><button class="btn s" style="margin-top:10px" onclick="prl()">⟳ Qayta urinish</button></div>';return}
var nx='';PRK.slice(1).forEach(function(k){if(!nx&&j.times[k[0]]>j.now)nx=k[0]});
$('prb').innerHTML='<div class="card"><b>📍 '+esc(j.name)+'</b><div class="sub" style="margin-top:4px">📅 '+esc(j.date)+(j.hijri?' · '+esc(j.hijri):'')+'</div></div><div class="card" style="padding:8px 16px">'+PRK.slice(1).map(function(k){var a=k[0]===nx;return '<div class="row" style="padding:12px '+(a?'10px;margin:0 -10px;border-radius:12px;background:var(--soft)':'0')+'"><span>'+k[1]+' '+(a?'<b>'+k[2]+'</b> <span class="sub">· keyingi</span>':k[2])+'</span><b style="font-size:20px">'+esc(j.times[k[0]])+'</b></div>'}).join('')+'</div><p class="sub" style="margin:0 4px 12px">'+(j.calc?'Manba: hisoblangan (islom.uz uslubi: Bomdod/Xufton 15,5°, Asr Hanafiy) — namoz vaqtlari serveri hozir javob bermayapti. Rasmiy jadvaldan 1–2 daqiqa farq qilishi mumkin':'Manba: islomapi.uz (islom.uz taqvimi asosida) · yangilangan '+esc(j.upd)+(j.stale?' · ⚠️ server hozir javob bermadi, oxirgi saqlangan ma\'lumot':''))+'. Masjiddagi jamoat namozi vaqti farq qilishi mumkin.</p>'})}
function pra(){api('adm_pr').then(function(j){if(j.ok){PRA=j;av('pr')}})}
function prd(d){var on=d.active==1,ks=PRK2.filter(function(k){return d.sch[k[0]].on}).map(function(k){return k[1]+' '+k[2]+(k[0]==='daily'?' '+d.sch.daily.time:'')}).join(' · ');
var h='<div class="card"><div class="row"><b>'+esc(d.title)+'</b><span class="tag">'+(on?'✅ Faol':'⛔ O\'chiq')+'</span></div><div class="sub">'+(d.chat_type==='channel'?'📢 Kanal':'👥 Guruh')+' · '+esc(d.chat_id)+'</div><div class="sub">📍 '+esc(d.region_name)+'</div><div class="sub">'+(ks||'Hech qanday xabar yoqilmagan')+'</div>'+(d.last_ok_at?'<div class="sub">✅ Oxirgi yuborilgan: '+esc(d.last_ok_at)+'</div>':'')+(d.last_err?'<div class="sub" style="color:var(--r)">⚠️ '+esc(d.last_err)+(d.last_err_at?' ('+esc(d.last_err_at)+')':'')+'</div>':'')
+'<div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px"><button class="btn s" onclick="PRE=PRE=='+d.id+'?0:'+d.id+';av(\'pr\')">⚙️ Sozlash</button><button class="btn s" onclick="prq(\'adm_pr_toggle\','+d.id+')">'+(on?'⛔ O\'chirish':'✅ Yoqish')+'</button><button class="btn s" onclick="prts('+d.id+')">🧪 Test</button><button class="btn s" onclick="PRH=PRH=='+d.id+'?0:'+d.id+';av(\'pr\')">📜 Tarix</button><button class="btn s" onclick="prdl('+d.id+')">🗑</button></div>';
if(PRH==d.id)h+='<div style="margin-top:10px">'+prlg(PRA.logs.filter(function(l){return l.dest_id==d.id}))+'</div>';
if(PRE==d.id)h+='<div style="margin-top:12px"><p class="sub" style="margin:0">Nomi</p><input id="pe_t" maxlength="80" value="'+esc(d.title)+'"><p class="sub" style="margin:0">Hudud</p><select id="pe_r">'+rgo(PRA.regions,d.region)+'</select>'+PRK2.map(function(k){var x=d.sch[k[0]];return '<div style="border-top:1px solid var(--ln);padding-top:10px;margin-top:10px"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" style="width:auto;margin:0" id="pe_o_'+k[0]+'" '+(x.on?'checked':'')+'><b>'+k[1]+' '+k[2]+'</b></label>'+(k[0]==='daily'?'<p class="sub" style="margin:6px 0 0">Yuborish vaqti</p><input id="pe_tm" type="time" value="'+esc(x.time)+'">':'<div class="sub">'+(k[0]==='quyosh'?'Quyosh chiqqanda (ixtiyoriy) yuboriladi':k[0]==='saharlik'?'Bomdoddan 10 daqiqa oldin — faqat Ramazon oyida yoqing':k[0]==='iftor'?'Shom vaqtida — faqat Ramazon oyida yoqing':'Namoz vaqti kirganda yuboriladi')+'</div>')+'<details><summary class="sub">Xabar matni'+(x.custom?' (o\'zgartirilgan)':'')+'</summary><textarea id="pe_x_'+k[0]+'" rows="'+(k[0]==='daily'?12:5)+'" maxlength="2000">'+esc(x.text)+'</textarea></details></div>'}).join('')+'<p class="sub">O\'zgaruvchilar: {hudud} {sana} {hijriy} {bomdod} {quyosh} {peshin} {asr} {shom} {xufton}; alohida xabarda: {namoz} {vaqt} {belgi}. Matnni bo\'shatsangiz standart matn ishlatiladi.</p><button class="btn" onclick="prsv('+d.id+')">Saqlash</button></div>';
return h+'</div>'}
function prlg(L){var KN={test:'🧪 Test'};PRK2.forEach(function(k){KN[k[0]]=k[1]+' '+k[2]});return L.length?'<div class="card">'+L.map(function(l){return '<div style="padding:6px 0;border-bottom:1px solid var(--ln)"><div class="row"><span>'+(PST[l.status]||'')+' '+esc(KN[l.kind]||l.kind)+'</span><span class="sub">'+esc(l.updated_at)+'</span></div><div class="sub">'+esc(l.title||'(o\'chirilgan)')+(+l.tries>1?' · '+l.tries+' urinish':'')+'</div>'+(l.err?'<div class="sub" style="color:var(--r)">'+esc(l.err)+'</div>':'')+'</div>'}).join('')+'</div>':'<div class="card sub">Hali xabar yuborilmagan.</div>'}
function prq(a,id,b,m){var o=b||{};o.id=id;return api(a,o).then(function(j){if(j.data)PRA=j.data;if(j.ok||j.data)av('pr');if(j.ok&&m)toast(m);return j})}
function prad(){api('adm_pr_add',{title:$('pr_t').value,chat_id:$('pr_c').value,region:$('pr_r').value}).then(function(j){if(j.ok){PRA=j.data;av('pr');toast(j.warn?'⚠️ '+j.warn:'Qo\'shildi ✅')}})}
function prsv(id){var o={title:$('pe_t').value,region:$('pe_r').value,sch:{}};PRK2.forEach(function(k){o.sch[k[0]]={on:$('pe_o_'+k[0]).checked,text:$('pe_x_'+k[0]).value};if(k[0]==='daily')o.sch.daily.time=$('pe_tm').value});prq('adm_pr_save',id,o).then(function(j){if(j.ok){PRE=0;av('pr');toast('Saqlandi ✅')}})}
function prts(id){toast('Yuborilmoqda...');prq('adm_pr_test',id,null,'Test xabari yuborildi ✅')}
function prdl(id){cf('Ro\'yxatdan o\'chirilsinmi? Bu chatga namoz xabarlari yuborilmaydi.',function(y){if(y)prq('adm_pr_del',id,null,'O\'chirildi')})}
function prdg(){var e=$('prdg');e.innerHTML='<p class="sub">Tekshirilmoqda...</p>';api('adm_pr_diag',{region:'Toshkent'}).then(function(j){if(!j.ok){e.innerHTML='<p class="sub" style="color:var(--r)">'+esc(j.error||'Aloqa xatosi')+'</p>';return}e.innerHTML='<div class="sub" style="margin-top:8px;word-break:break-all;background:#eef1f6;border-radius:10px;padding:10px;white-space:pre-wrap">'+esc('Natija: '+j.result+'\nZaxira hisob: '+j.calc+'\nHudud: '+j.region+' · '+j.now+' · PHP '+j.php+'\n\n'+j.probes.map(function(p){return p.url+'\nHTTP: '+p.http+(p.curl?' · cURL xato: '+p.curl:'')+' · '+p.ms+' ms · '+p.type+'\n'+p.body}).join('\n\n'))+'</div><p class="sub">Shu oynaning skrinshotini yuboring.</p>'})}
function prttl(){api('adm_pr_cfg',{ttl:$('pr_ttl').value}).then(function(j){if(j.ok){PRA=j.data;av('pr');toast('Saqlandi ✅')}})}
var GDK=[['noad','✅','Guruhga reklama yubormaydi','bot bu guruhga pullik e\'lon va reklama yubormaydi'],['swear','🔞','So\'kinish xabarni o\'chiradi','o\'zbekcha va ruscha so\'kinishlar + pastda o\'zingiz kiritgan so\'zlar'],['link','⚠️','Reklama havolani tozalaydi','t.me, http, www havolalar, kanaldan forward, tugmali xabarlar'],['voice','🔈','So\'kinish golosni o\'chiradi','bot ovozni eshita olmaydi — yoqilsa a\'zolarning barcha ovozli va dumaloq video xabarlari o\'chiriladi'],['spam','🚫','Spam xabardan tozalaydi','10 soniyada 6+ xabar, bir xil matn 3 marta, 5+ ta @mention'],['arabbot','🤨','Arab botlardan himoya qiladi','arabcha ismli akkauntlar va a\'zolar qo\'shgan botlar guruhdan chiqariladi'],['arabad','❗️','Arabcha reklama o\'chiradi','arabcha matn + havola, @mention yoki telefon raqam'],['join','🗑','Kirdi-chiqdini tozalaydi','«… qo\'shildi / chiqib ketdi» xabarlari'],['newbie','🆕','Yangi a\'zolarga 24 soat cheklov','yangi qo\'shilgan a\'zo 24 soat havola, rasm/video, fayl va forward yubora olmaydi — spam botlarning 90% to\'xtaydi'],['gban','🚫','Umumiy qora ro\'yxat','boshqa TartibOn guruhlarida /ban qilingan spamchi bu guruhga ham kira olmaydi'],['slow','⏰','Sekin rejim','bir a\'zo belgilangan soniyada bir martadan ko\'p yoza olmaydi (sozlamalarda)'],['nomedia','🔇','Media vaqti','belgilangan soatlarda rasm, video, stiker taqiqlanadi — matn mumkin (sozlamalarda)'],['fakeadm','🚷','Soxta adminlar','admin ismini ko\'chirgan yoki ismida «admin», «support» bor begonalar chiqariladi — firibgarlikka qarshi'],['phone','📵','Telefon raqamlarni yashirish','telefon raqam yozilgan xabar va kontaktlar o\'chiriladi (shaxsiy ma\'lumot himoyasi)'],['adfmt','🛒','E\'lon formati','savdo guruhi: e\'lon shablonga (Narx, Manzil, Telefon) mos bo\'lmasa o\'chiriladi va namuna ko\'rsatiladi'],['invite','🎫','Taklif bilan yozish','a\'zo guruhga belgilangan sondagi do\'stini qo\'shmaguncha yoza olmaydi (sozlamalarda)']],
GDX=[['apk','📦','Zararli fayllar','.apk, .exe, .bat, .jar va shunga o\'xshash fayllar'],['aiporn','🔞','Porno media va stickerlar (AI)','rasm, sticker, GIF va video muqovasini sun\'iy intellekt tekshiradi'],['aispam','📣','Yashirin reklama (AI)','qoidalardan o\'tib ketgan reklama matnlarini sun\'iy intellekt aniqlaydi'],['arabic','🇸🇦','Barcha arabcha xabarlar','asosan arab harflarida yozilgan har qanday xabar']],
GDALL=['noad','swear','link','voice','spam','arabbot','arabad','join','newbie','gban','fakeadm','apk','aiporn','aispam','captcha'],GDL=null,GDA=null;
function gdl(){if(!GDL)$('gdb').innerHTML='<div class="sk"></div>';api('guard_my').then(function(j){if(j.ok){GDL=j.groups;gdr()}})}
function gdrow(k,on,i,all,hi){return '<div class="row" style="cursor:pointer;padding:10px '+(hi?'10px;margin:8px -10px 0;border-radius:12px;background:var(--soft)':'0;margin-top:8px;border-top:1px solid var(--ln)')+'" onclick="gdt('+i+',\''+k[0]+'\','+(all?1:0)+')"><div style="display:flex;align-items:center;gap:10px">'+ck(on)+'<div><b>'+k[1]+' '+k[2]+'</b>'+(k[3]?'<div class="sub">'+k[3]+'</div>':'')+'</div></div></div>'}
function gdc(g,i,all){var K=GDK.concat(GDX),st=K.filter(function(k){return g.week[k[0]]}).map(function(k){return k[1]+' '+g.week[k[0]]}).join(' · '),full=GDALL.every(function(k){return g.opts[k]});
return '<div class="card"><div class="row"><div><b>'+esc(g.title)+'</b><div class="sub">'+(all?'@'+esc(g.owner)+' · ':'')+(ST[g.status]||'')+' · '+(g.on?'🛡 Himoya yoqilgan':'Himoya o\'chiq')+'</div></div></div>'
+(g.status==='noperm'?'<div class="sub" style="color:var(--r);margin-top:6px">⚠️ Bot guruhda administrator emas. Botni administrator qiling va guruhni qayta qo\'shing.</div>':'')
+(g.err?'<div class="sub" style="color:var(--r);margin-top:6px">⚠️ '+esc(g.err)+'</div>':'')
+'<div class="sub" style="margin-top:6px">Bugun o\'chirildi: <b>'+g.today+'</b>'+(st?' · 7 kunda: '+st:'')+'</div>'
+GDK.concat(GDX,GDM).map(function(k){return gdrow(k,g.opts[k[0]],i,all)}).join('')
+gdrow(['all','🛡','Guruhni 100% himoya qiladi',full?'barcha himoya yoqilgan':'bosing — hammasi birdan yoqiladi'],full,i,all,1)
+gdman(g,i,all)
+'<div style="border-top:1px solid var(--ln);margin-top:10px;padding-top:10px"><b>🔞 Guruhda yozib bo\'lmaydigan so\'zlar</b><div class="sub">Har qatorda bitta so\'z yoki so\'z boshi. Shu so\'z bor xabar o\'chiriladi (kirill/lotin farqi yo\'q).</div><textarea id="gw'+(all?'a':'')+i+'" rows="4" maxlength="3000" placeholder="masalan:&#10;ahmoq&#10;tentak">'+esc(g.words)+'</textarea><button class="btn s" onclick="gdws('+i+','+(all?1:0)+')">Saqlash</button>'+(all?'':' <button class="btn s" onclick="go(\'chats\',\'Guruh\')">📈 Kurs xabarlari</button>')+'</div>'
+(all?'':'<div style="border-top:1px solid var(--ln);margin-top:10px;padding-top:10px"><div class="row"><b>💬 Avto-javoblar</b><button class="btn s" style="flex:none" onclick="arOpen('+i+')">Ochish</button></div><div class="sub">Guruhda kimdir kalit so\'zni yozsa, bot o\'zi javob beradi. Masalan: «manzil» → «Manzilimiz: …»</div><div id="ar'+i+'"></div></div>')
+(all?'':'<div style="border-top:1px solid var(--ln);margin-top:10px;padding-top:10px"><div class="row"><b>📢 Majburiy obuna</b><button class="btn s" style="flex:none" onclick="fsOpen('+i+')">Sozlash</button></div><div class="sub">Guruhda yozish uchun kanalingizga obuna bo\'lish shart bo\'ladi. Obuna bo\'lmaganning xabari o\'chiriladi va unga «Obuna bo\'lish» tugmasi chiqadi.</div><div id="fs'+i+'"></div></div>')+'</div>'}
function fsOpen(i){var e=$('fs'+i);e.innerHTML='<div class="sk"></div>';api('fs_get',{chat:GDL[i].id}).then(function(j){if(j.ok)fsDraw(i,j.fs);else e.innerHTML=''})}
function fsDraw(i,f){$('fs'+i).innerHTML=(f?'<div class="sub" style="margin-top:8px;color:var(--g)">✅ Yoqilgan: <b>@'+esc(f.ch_user)+'</b>'+(f.ch_title&&f.ch_title.replace(/^@/,'')!==f.ch_user?' ('+esc(f.ch_title)+')':'')+' · obuna bo\'lmaganlardan o\'chirilgan xabarlar: '+nf(+f.blocked_n)+'</div><button class="btn s" style="margin-top:6px" onclick="fsSet('+i+',1)">O\'chirish</button>':'<div class="sub" style="margin-top:8px">⛔ O\'chirilgan</div>')+'<div style="margin-top:8px"><input id="fsc'+i+'" placeholder="@kanal_username" value="'+(f?'@'+esc(f.ch_user):'')+'"><div class="sub" style="margin:4px 0 6px">Bot kanalda administrator bo\'lishi kerak (obunachilarni tekshirish uchun). Guruh adminlariga tegilmaydi.</div><button class="btn" onclick="fsSet('+i+',0)">💾 Saqlash</button></div>'}
function fsSet(i,off){api('fs_set',{chat:GDL[i].id,ch:off?'':$('fsc'+i).value.trim()}).then(function(j){if(j.ok){toast(off?'O\'chirildi':'Yoqildi ✅');fsDraw(i,j.fs)}})}
function arOpen(i){var e=$('ar'+i);e.innerHTML='<div class="sk"></div>';api('ar_list',{chat:GDL[i].id}).then(function(j){if(j.ok)arDraw(i,j.list);else e.innerHTML=''})}
function arDraw(i,L){$('ar'+i).innerHTML=(L.length?L.map(function(r){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);align-items:flex-start"><div style="min-width:0"><b>🔑 '+esc(r.kw)+'</b><div class="sub" style="white-space:pre-wrap;word-break:break-word">'+esc(r.reply)+'</div><div class="sub">Javob berildi: '+nf(+r.hits)+' marta</div></div><button class="btn s" style="flex:none" onclick="arDel('+i+','+r.id+')">🗑</button></div>'}).join(''):'<div class="sub" style="margin-top:6px">Hali avto-javob yo\'q.</div>')+'<div style="border-top:1px solid var(--ln);margin-top:8px;padding-top:8px"><input id="ark'+i+'" maxlength="100" placeholder="Kalit so\'z(lar), vergul bilan: manzil, adres"><textarea id="arr'+i+'" rows="3" maxlength="1000" placeholder="Javob matni"></textarea><button class="btn" onclick="arAdd('+i+')">➕ Qo\'shish</button></div>'}
function arAdd(i){var k=$('ark'+i).value.trim(),r=$('arr'+i).value.trim();if(!k||!r){toast('Kalit so\'z va javob matnini yozing');return}api('ar_save',{chat:GDL[i].id,kw:k,reply:r}).then(function(j){if(j.ok){toast('Qo\'shildi ✅');arDraw(i,j.list)}})}
function arDel(i,id){cf('Avto-javob o\'chirilsinmi?',function(ok){if(ok)api('ar_del',{chat:GDL[i].id,id:id}).then(function(j){if(j.ok)arDraw(i,j.list)})})}
function gdr(){var h='<div class="card"><b>➕ Guruhni himoyaga ulash</b><input id="gd_u" placeholder="@guruh_username yoki -100... ID"><button class="btn" onclick="gdadd()">Qo\'shish</button><div class="sub" style="margin-top:8px">Avval botni guruhga <b>administrator</b> qiling: «Xabarlarni o\'chirish» va «Foydalanuvchilarni bloklash» huquqlari bilan. Qo\'shilgan zahoti himoya yoqiladi. Guruh adminlari xabarlariga tegilmaydi. Guruhda /himoya — vazifalar ro\'yxati.</div></div>';
h+=GDL.length?GDL.map(function(g,i){return gdc(g,i,0)}).join(''):'<div class="card sub">Sizda hali guruh yo\'q — yuqorida qo\'shing.</div>';$('gdb').innerHTML=h}
function gdadd(){var v=$('gd_u').value.trim();if(!v){toast('Guruh username yoki ID sini kiriting');return}api('chat_add',{username:v,want:'Guruh',interval:3}).then(function(j){if(j.ok){toast(j.msg);gdl()}})}
function gdsave(i,all,o,w){var g=(all?GDA.groups:GDL)[i],b={id:g.id,opts:o,all:all};if(w!=null)b.words=w;return api('guard_set',b).then(function(j){if(!j.ok)return j;if(all){GDA.groups=j.groups;av('gd')}else{GDL=j.groups;gdr()}if(j.warn)toast('⚠️ '+j.warn);return j})}
function gdt(i,k,all){var g=(all?GDA.groups:GDL)[i],o={};GDK.concat(GDX,GDM).forEach(function(x){o[x[0]]=!!g.opts[x[0]]});if(k==='all'){var f=GDALL.every(function(x){return o[x]});GDALL.forEach(function(x){o[x]=!f})}else o[k]=!o[k];gdsave(i,all,o)}
function gdws(i,all){var g=(all?GDA.groups:GDL)[i];gdsave(i,all,g.opts,$('gw'+(all?'a':'')+i).value).then(function(j){if(j&&j.ok&&!j.warn)toast('Saqlandi ✅')})}
var GDM=[['captcha','🤖','Kapcha','yangi a\'zo 2 daqiqada «Men odamman» tugmasini bosmasa guruhdan chiqariladi'],['autowarn','⚠️','Avto-ogohlantirish','qoida buzganga ogohlantirish; limitdan keyin vaqtincha yoza olmaydi'],['welcome','👋','Salomlashish','yangi a\'zoga salom xabari (2 daqiqadan keyin o\'chadi)'],['night','🌙','Tungi rejim','belgilangan vaqtda guruhga faqat adminlar yozadi'],['logpm','📨','O\'chirilganlarni menga yuborish','har bir o\'chirilgan xabar sizga shaxsan keladi'],['top10','🏆','Haftalik TOP-10','har dushanba o\'tgan haftaning eng faol 10 a\'zosi guruhga e\'lon qilinadi'],['rep','⭐','Reputatsiya','xabarga «rahmat» yoki «+» deb javob berilsa — ball; /reyting'],['gq','🧑‍🏫','Kirishda test savoli','yangi a\'zoga savol beriladi — noto\'g\'ri javob bersa yoki 2 daqiqada javob bermasa chiqariladi (savol sozlamalarda)'],['juma','🕌','Juma sukuti','har Juma namoz vaqtida guruh yopiladi va keyin o\'zi ochiladi (vaqt sozlamalarda)']],GDO={},
GKL={fakeadm:'Soxta admin',phone:'Telefon raqam',adfmt:'E\'lon formati',invite:'Do\'st qo\'shmagan',newbie:'Yangi a\'zo',gban:'Qora ro\'yxat',slow:'Sekin rejim',nomedia:'Media vaqti',link:'Reklama havola',swear:'So\'kinish',voice:'Ovozli',spam:'Spam',arabbot:'Arab bot',arabad:'Arabcha reklama',arabic:'Arabcha',join:'Kirdi-chiqdi',apk:'Zararli fayl',aiporn:'Porno (AI)',aispam:'Reklama (AI)',night:'Tungi rejim',captcha:'Tasdiqlanmagan'};
function dtf(s){return s?s.slice(8,10)+'.'+s.slice(5,7)+'.'+s.slice(0,4)+' '+s.slice(11,16):''}
function dtl(min){var d=new Date(Date.now()+min*60000),p=function(n){return('0'+n).slice(-2)};return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())}
function ago(t,now){if(!+t)return'hech yozmagan';var d=Math.floor((now-t)/86400);return d<1?'bugun':d+' kun oldin'}
function chopt(L,sel){return L.map(function(c){return '<option value="'+c.id+'"'+(c.id==sel?' selected':'')+'>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</option>'}).join('')}
function gdman(g,i,all){var sx=(all?'a':'')+i,c=g.cfg;return '<div style="margin-top:10px;border-top:1px solid var(--ln);padding-top:10px"><b>⚙️ Guruh boshqaruvi sozlamalari</b>'
+'<p class="sub" style="margin:12px 0 0">👋 Salomlashish matni ({ism}, {guruh})</p><textarea id="gc_w'+sx+'" rows="3" maxlength="1000">'+esc(c.welcome)+'</textarea>'
+'<div style="display:flex;gap:8px"><div style="flex:1"><p class="sub" style="margin:0">🌙 Tun boshlanishi</p><input id="gc_f'+sx+'" type="time" value="'+esc(c.night_from)+'"></div><div style="flex:1"><p class="sub" style="margin:0">Tugashi</p><input id="gc_t'+sx+'" type="time" value="'+esc(c.night_to)+'"></div></div>'
+'<div style="display:flex;gap:8px"><div style="flex:1"><p class="sub" style="margin:0">⚠️ Ogohlantirish soni</p><input id="gc_l'+sx+'" type="number" inputmode="numeric" min="1" max="10" value="'+c.warn_limit+'"></div><div style="flex:1"><p class="sub" style="margin:0">🔇 Mute (soat)</p><input id="gc_m'+sx+'" type="number" inputmode="numeric" min="1" max="720" value="'+c.mute_h+'"></div></div>'
+'<p class="sub" style="margin:0">⏰ Sekin rejim — necha soniyada 1 xabar</p><input id="gc_s'+sx+'" type="number" inputmode="numeric" min="5" max="3600" value="'+(c.slow_s||30)+'">'
+'<div style="display:flex;gap:8px"><div style="flex:1;min-width:0"><p class="sub" style="margin:0">🔇 Media taqiqi: dan</p><input id="gc_mf'+sx+'" type="time" value="'+esc(c.media_from||'23:00')+'"></div><div style="flex:1;min-width:0"><p class="sub" style="margin:0">gacha</p><input id="gc_mt'+sx+'" type="time" value="'+esc(c.media_to||'07:00')+'"></div></div>'
+'<p class="sub" style="margin:8px 0 0">🗣 Kuzatiladigan so\'zlar — guruhda yozilsa, sizga shaxsan xabar keladi (vergul yoki har qatorda bitta)</p><textarea id="gc_k'+sx+'" rows="2" maxlength="1000" placeholder="narxi, sotiladi, buyurtma">'+esc(c.watch||'')+'</textarea>'
+'<p class="sub" style="margin:8px 0 0">🛒 E\'lon shabloni — majburiy bandlar (vergul bilan)</p><input id="gc_af'+sx+'" maxlength="200" value="'+esc(c.adfmt||'Narx, Manzil, Telefon')+'">'
+'<p class="sub" style="margin:0">🎫 Yozish uchun nechta do\'st qo\'shishi kerak</p><input id="gc_in'+sx+'" type="number" inputmode="numeric" min="1" max="50" value="'+(c.inv_n||3)+'">'
+'<p class="sub" style="margin:0">🧑‍🏫 Kirishdagi test savoli</p><input id="gc_qq'+sx+'" maxlength="200" placeholder="masalan: Guruhimiz qaysi shahar haqida?" value="'+esc(c.q_text||'')+'"><div style="display:flex;gap:8px"><div style="flex:1;min-width:0"><input id="gc_qo'+sx+'" maxlength="60" placeholder="✅ To\'g\'ri javob" value="'+esc(c.q_ok||'')+'"></div><div style="flex:1;min-width:0"><input id="gc_qb'+sx+'" maxlength="200" placeholder="❌ Noto\'g\'rilar, vergul bilan" value="'+esc(c.q_bad||'')+'"></div></div>'
+'<div style="display:flex;gap:8px"><div style="flex:1;min-width:0"><p class="sub" style="margin:0">🕌 Juma sukuti: dan</p><input id="gc_jf'+sx+'" type="time" value="'+esc(c.juma_from||'12:30')+'"></div><div style="flex:1;min-width:0"><p class="sub" style="margin:0">gacha</p><input id="gc_jt'+sx+'" type="time" value="'+esc(c.juma_to||'13:30')+'"></div></div>'
+'<p class="sub" style="margin:0">📍 Manzil — guruhda /manzil yozilsa chiqadi</p><input id="gc_ad'+sx+'" maxlength="200" placeholder="Toshkent sh., Chilonzor 9-kvartal, 12-uy" value="'+esc(c.addr||'')+'"><div style="display:flex;gap:8px"><div style="flex:1;min-width:0"><input id="gc_at'+sx+'" maxlength="60" placeholder="📞 Telefon" value="'+esc(c.addr_tel||'')+'"></div><div style="flex:1;min-width:0"><input id="gc_ag'+sx+'" maxlength="300" placeholder="🗺 Xarita: 41.311, 69.279" value="'+esc(c.addr_geo||'')+'"></div></div>'
+'<button class="btn s" onclick="gdcfg('+i+','+(all?1:0)+')">Saqlash</button>'
+'<div class="sub" style="margin:12px 0 6px">👮 Admin buyruqlari — kerakli xabarga javob (reply) qilib yozing: <b>/warn</b> ogohlantirish · <b>/unwarn</b> · <b>/mute 2h</b> (30m, 1d) · <b>/unmute</b> · <b>/kick</b> chiqarish · <b>/ban</b> butunlay · <b>/unban</b> (/ban qilingan umumiy qora ro\'yxatga ham tushadi) · <b>/ishonch</b> va <b>/ishonchsiz</b> — ishonchli a\'zo · <b>/yop 30m</b> va <b>/och</b> — guruhni yopish/ochish · <b>/jim 10m</b> — hamma vaqtincha jim · <b>/eslat 18:00 matn</b> (har kuni 09:00, har dushanba 09:00, 2s) · <b>/eslatmalar</b>. A\'zolar uchun: <b>/report</b> — shikoyat, <b>@admin</b> — adminlarni chaqirish, <b>/manzil</b>, <b>/reyting</b>. Guruhda <b>/himoya</b> — vazifalar, <b>/top</b> — taklif reytingi.</div>'
+'<div style="display:flex;flex-wrap:wrap;gap:6px"><button class="btn s" onclick="gdmem('+i+','+(all?1:0)+')">👥 A\'zolar faolligi</button><button class="btn s" onclick="gdlog('+i+','+(all?1:0)+')">🗑 O\'chirilgan xabarlar</button><button class="btn s" onclick="gdal('+i+','+(all?1:0)+')">🕵️ Admin harakatlari</button><button class="btn s" onclick="gdtr('+i+','+(all?1:0)+')">✅ Ishonchli a\'zolar</button><button class="btn s" onclick="gdrm('+i+','+(all?1:0)+')">⏰ Eslatmalar</button></div><div id="gx'+sx+'"></div></div>'}
function gdg(i,all){return (all?GDA.groups:GDL)[i]}
function gdcfg(i,all){var g=gdg(i,all),sx=(all?'a':'')+i;api('guard_cfg',{id:g.id,welcome:$('gc_w'+sx).value,night_from:$('gc_f'+sx).value,night_to:$('gc_t'+sx).value,warn_limit:$('gc_l'+sx).value,mute_h:$('gc_m'+sx).value,slow_s:$('gc_s'+sx).value,media_from:$('gc_mf'+sx).value,media_to:$('gc_mt'+sx).value,watch:$('gc_k'+sx).value,adfmt:$('gc_af'+sx).value,inv_n:$('gc_in'+sx).value,q_text:$('gc_qq'+sx).value,q_ok:$('gc_qo'+sx).value,q_bad:$('gc_qb'+sx).value,juma_from:$('gc_jf'+sx).value,juma_to:$('gc_jt'+sx).value,addr:$('gc_ad'+sx).value,addr_tel:$('gc_at'+sx).value,addr_geo:$('gc_ag'+sx).value}).then(function(j){if(j.ok){g.cfg=j.cfg;toast('Saqlandi ✅')}})}
function gdmem(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('guard_members',{id:g.id}).then(function(j){if(!j.ok)return;
e.innerHTML='<div class="sub" style="margin-top:10px">Bot ko\'rgan a\'zolar: <b>'+j.total+'</b> · 7 kunda faol: <b>'+j.active7+'</b>. Hisob bot qo\'shilgandan keyingi xabarlar bo\'yicha.</div>'
+(j.top.length?'<p style="margin:10px 0 4px"><b>🔥 Eng faollar</b></p>'+j.top.map(function(x,n){return '<div class="row sub" style="padding:4px 0"><span>'+(n+1)+'. '+esc(x.name)+(x.username?' @'+esc(x.username):'')+'</span><b>'+x.msgs+'</b></div>'}).join(''):'')
+'<p style="margin:10px 0 4px"><b>😴 7 kundan beri yozmaganlar ('+j.idle.length+(j.idle.length>=100?'+':'')+')</b></p>'+(j.idle.length?j.idle.map(function(x){return '<div class="row sub" style="padding:4px 0"><span>'+esc(x.name)+(x.username?' @'+esc(x.username):'')+'</span><span>'+ago(x.last_at,j.now)+'</span></div>'}).join(''):'<div class="sub">Yo\'q</div>')})}
function gdlog(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('guard_dlog',{id:g.id}).then(function(j){if(!j.ok)return;
e.innerHTML=j.log.length?j.log.map(function(l){var r=l.txt&&l.txt.charAt(0)!=='[';return '<div style="padding:8px 0;border-bottom:1px solid var(--ln)"><div class="row sub"><span>'+(l.ok==1?'🗑':'⚠️')+' '+esc(GKL[l.kind]||l.kind)+' · '+esc(l.uname||('ID '+l.user_id))+'</span><span>'+esc(dtf(l.at))+'</span></div>'+(l.txt?'<div style="word-break:break-word;font-size:14px;margin-top:2px">'+esc(l.txt)+'</div>':'')+(r?'<button class="btn s" style="margin-top:6px" onclick="gdrs('+l.id+')">♻️ Qayta yuborish</button>':'')+'</div>'}).join(''):'<p class="sub">Hali o\'chirilgan xabar yo\'q.</p>'})}
var ALG={warn:'⚠️ Ogohlantirdi',unwarn:'↩️ Ogohlantirish olindi',mute:'🔇 Cheklandi',unmute:'🔊 Cheklov olindi',ban:'⛔ Blokladi',unban:'✅ Blokdan chiqardi',kick:'👢 Chiqardi',yop:'🔒 Guruhni yopdi',jim:'🤐 Jim rejimi',och:'🔓 Guruhni ochdi',ishonch:'✅ Ishonchli qildi',ishonchsiz:'☑️ Ishonchlidan oldi','admin+':'👮 Admin qildi','admin-':'👤 Adminlikdan oldi'};
function gdal(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('alog_list',{id:g.id}).then(function(j){if(!j.ok)return;e.innerHTML='<p style="margin:10px 0 4px"><b>🕵️ Admin harakatlari</b></p><p class="sub" style="margin:0 0 6px">Bloklash, chiqarish, cheklash va bot buyruqlari. Adminlar qo\'lda o\'chirgan xabarlarni Telegram botga ko\'rsatmaydi.</p>'+(j.log.length?j.log.map(function(l){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span><b>'+esc(l.admin_name||'Admin')+'</b> · '+(ALG[l.action]||esc(l.action))+(l.target_name?' — '+esc(l.target_name):'')+(l.detail?' ('+esc(l.detail)+')':'')+'</span><span style="flex:none">'+esc(new Date(l.at*1000).toLocaleString('uz',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))+'</span></div>'}).join(''):'<p class="sub">Hali yozuv yo\'q.</p>')})}
function gdtr(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('trust_list',{id:g.id}).then(function(j){if(j.ok)gdtrd(i,all,j.list)})}
function gdtrd(i,all,L){var e=$('gx'+(all?'a':'')+i),sx=(all?'a':'')+i;e.innerHTML='<p style="margin:10px 0 4px"><b>✅ Ishonchli a\'zolar</b></p><p class="sub" style="margin:0 0 6px">Himoya ularning havola, rasm va xabarlariga tegmaydi. Guruhda xabariga javob qilib /ishonch yozsangiz ham qo\'shiladi.</p>'+(L.length?L.map(function(x){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span>'+esc(x.name)+(x.username?' @'+esc(x.username):'')+'</span><button class="btn s" style="flex:none" onclick="gdtrx('+i+','+(all?1:0)+','+x.user_id+')">🗑</button></div>'}).join(''):'<p class="sub">Hali yo\'q.</p>')+'<div style="display:flex;gap:8px;margin-top:8px"><input id="gtr'+sx+'" placeholder="@username" style="flex:1"><button class="btn s" style="flex:none" onclick="gdtra('+i+','+(all?1:0)+')">➕</button></div>'}
function gdtra(i,all){var g=gdg(i,all),v=$('gtr'+(all?'a':'')+i).value.trim();if(!v)return;api('trust_add',{id:g.id,who:v}).then(function(j){if(j.ok){toast('Qo\'shildi ✅');gdtrd(i,all,j.list)}})}
function gdtrx(i,all,uid){var g=gdg(i,all);api('trust_del',{id:g.id,uid:uid}).then(function(j){if(j.ok)gdtrd(i,all,j.list)})}
function gdrm(i,all){var g=gdg(i,all),e=$('gx'+(all?'a':'')+i);e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('rem_list',{id:g.id}).then(function(j){if(j.ok)gdrmd(i,all,j.list)})}
function gdrmd(i,all,L){$('gx'+(all?'a':'')+i).innerHTML='<p style="margin:10px 0 4px"><b>⏰ Eslatmalar</b></p><p class="sub" style="margin:0 0 6px">Guruhda admin yozadi: <b>/eslat 18:00 matn</b> · <b>/eslat 2s matn</b> (m — daqiqa, s — soat, k — kun) · <b>/eslat har kuni 09:00 matn</b> · <b>/eslat har dushanba 09:00 matn</b>.</p>'+(L.length?L.map(function(r){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln);align-items:flex-start"><span>#'+r.id+' · <b>'+esc(r.when)+'</b><br>'+esc(r.body)+'</span><button class="btn s" style="flex:none" onclick="gdrmx('+i+','+(all?1:0)+','+r.id+')">🗑</button></div>'}).join(''):'<p class="sub">Faol eslatma yo\'q.</p>')}
function gdrmx(i,all,rid){var g=gdg(i,all);api('rem_del',{id:g.id,rid:rid}).then(function(j){if(j.ok)gdrmd(i,all,j.list)})}
function gbl(){var e=$('gbl');if(!e)return;e.innerHTML='<p class="sub">Yuklanmoqda...</p>';api('gban_list').then(function(j){if(!j.ok)return;e.innerHTML='<p class="sub" style="margin:4px 0 8px">Jami: <b>'+j.n+'</b>. Guruhlarda /ban qilinganlar shu yerga tushadi va «Umumiy qora ro\'yxat» yoqilgan barcha guruhlarga kira olmaydi.</p>'+(j.list.length?j.list.map(function(x){return '<div class="row sub" style="padding:6px 0;border-bottom:1px solid var(--ln)"><span>'+esc(x.name||('ID '+x.user_id))+' · '+esc(x.chat||'')+' · '+esc(x.reason)+'</span><button class="btn s" style="flex:none" onclick="gbx('+x.user_id+')">Olib tashlash</button></div>'}).join(''):'<p class="sub">Bo\'sh.</p>')})}
function gbx(uid){cf('Qora ro\'yxatdan olib tashlansinmi?',function(y){if(y)api('gban_del',{uid:uid}).then(function(j){if(j.ok)gbl()})})}
function gdrs(id){cf('Xabar guruhga qayta yuborilsinmi?',function(y){if(y)api('guard_restore',{log:id}).then(function(j){if(j.ok)toast('Yuborildi ✅')})})}
/* ---- Postlar ---- */
var POD=null,REP={none:'Bir marta',daily:'Har kuni',weekly:'Har hafta'};
function pol(){api('post_list').then(function(j){if(!j.ok)return;POD=j;por();pcal()})}
var PCM=null;
function pcal(m){var e=$('poc');if(!e||!POD)return;var n=new Date();if(m!=null)PCM=m;if(PCM==null)PCM=n.getFullYear()*12+n.getMonth();var Y=Math.floor(PCM/12),M=PCM%12,first=new Date(Y,M,1),days=new Date(Y,M+1,0).getDate(),off=(first.getDay()+6)%7,by={};
var add=function(d,p){(by[d]=by[d]||[]).push(p)};POD.posts.filter(function(p){return p.active==1}).forEach(function(p){var t=new Date(p.run_at.replace(' ','T'));for(var d=1;d<=days;d++){var c=new Date(Y,M,d,23,59);if(c<t)continue;var dd=new Date(Y,M,d);if(p.rep==='daily'||(p.rep==='weekly'&&dd.getDay()===t.getDay())||(p.rep==='none'&&t.getFullYear()===Y&&t.getMonth()===M&&t.getDate()===d))add(d,p)}});
var MN=['Yanvar','Fevral','Mart','Aprel','May','Iyun','Iyul','Avgust','Sentabr','Oktabr','Noyabr','Dekabr'],h='<div class="card"><div class="row"><button class="btn s" style="flex:none;width:auto" onclick="pcal(PCM-1)">‹</button><b>🗓 '+MN[M]+' '+Y+'</b><button class="btn s" style="flex:none;width:auto" onclick="pcal(PCM+1)">›</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:10px;text-align:center;font-size:12px">'+['Du','Se','Ch','Pa','Ju','Sh','Ya'].map(function(x){return '<div class="sub">'+x+'</div>'}).join('');
for(var i=0;i<off;i++)h+='<div></div>';for(var d=1;d<=days;d++){var L=by[d]||[],td=Y===n.getFullYear()&&M===n.getMonth()&&d===n.getDate();h+='<div onclick="pcd('+d+')" style="cursor:pointer;padding:6px 0;border-radius:10px;background:'+(L.length?'var(--soft)':'transparent')+';'+(td?'outline:2px solid var(--b)':'')+'"><b style="font-size:14px">'+d+'</b><div style="font-size:11px;color:var(--b);min-height:13px">'+(L.length?'● '+L.length:'')+'</div></div>'}
h+='</div><div id="pcd" class="sub" style="margin-top:8px">Kunni bosing — o\'sha kungi postlar ko\'rinadi.</div></div>';e.innerHTML=h;PCAL=by}
var PCAL={};
function pcd(d){var L=PCAL[d]||[];$('pcd').innerHTML=L.length?L.map(function(p){return '<div style="padding:6px 0;border-top:1px solid var(--ln)">🕐 <b>'+esc(p.run_at.slice(11,16))+'</b> · '+esc(p.username)+(p.rep!=='none'?' · 🔁':'')+'<div style="word-break:break-word">'+esc(String(p.body||'[media]').slice(0,80))+'</div></div>'}).join(''):d+'-kunga post rejalashtirilmagan.'}
function pxl(){var e=$('pox');if(!e)return;e.innerHTML='<div class="sk"></div>';Promise.all([api('rss_list'),api('cd_list'),api('sl_list')]).then(function(r){if(!r[0].ok)return;PX={rss:r[0],cd:r[1],sl:r[2]};pxr()})}
var PX=null;
function pxr(){var R=PX.rss,C=PX.cd,S=PX.sl,ch=chopt(R.chats),h='';
h+='<div class="card"><b>📰 Saytdan avtomatik post (RSS)</b><div class="sub" style="margin:4px 0 8px">Sayt yoki blogda yangi maqola chiqsa, kanalingizga sarlavha, qisqa matn va havola bilan o\'zi joylanadi (15 daqiqada tekshiriladi).</div>'+(R.chats.length?'<select id="rs_c">'+ch+'</select><input id="rs_u" placeholder="https://sayt.uz/feed yoki /rss"><button class="btn" onclick="rsa()">➕ Qo\'shish</button>':'<p class="sub">Avval kanal qo\'shing.</p>')+R.list.map(function(f){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div style="min-width:0"><b style="font-size:14px;word-break:break-all">'+esc(f.url)+'</b><div class="sub">→ '+esc(f.username)+' · '+f.n+' ta post'+(f.err?' · <span style="color:var(--r)">⚠️ '+esc(f.err)+'</span>':'')+'</div></div><button class="btn s" style="flex:none;width:auto" onclick="rsd('+f.id+')">🗑</button></div>'}).join('')+'</div>';
h+='<div class="card"><b>⏱ Sanoq posti (countdown)</b><div class="sub" style="margin:4px 0 8px">«Aksiyagacha 3 kun qoldi» — post kanalga chiqadi va har soatda o\'zi yangilanadi.</div>'+(C.chats.length?'<select id="cd_c">'+ch+'</select><input id="cd_t" maxlength="200" placeholder="Masalan: Katta aksiyagacha"><p class="sub" style="margin:0">Tugash vaqti</p><input id="cd_e" type="datetime-local" value="'+dtl(60*24*3)+'"><label class="lr in"><span class="lt"><b>Postni tepaga mahkamlash</b></span><input type="checkbox" id="cd_p"></label><button class="btn" onclick="cda()">⏱ Joylash</button>':'')+C.list.map(function(d){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div><b style="font-size:14px">'+esc(d.title)+'</b><div class="sub">'+esc(d.username)+' · '+new Date(d.end_at*1000).toLocaleString('uz-UZ',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+(d.done==1?' · ✅ tugagan':'')+'</div></div>'+(d.done==1?'':'<button class="btn s" style="flex:none;width:auto" onclick="cdd('+d.id+')">⏹</button>')+'</div>'}).join('')+'</div>';
h+='<div class="card"><b>🔗 Qisqa havolalar</b><div class="sub" style="margin:4px 0 8px">Postga qisqa havola qo\'ying — necha marta bosilganini shu yerda ko\'rasiz.</div><input id="sl_u" placeholder="Uzun havola: https://..."><input id="sl_k" maxlength="20" placeholder="Qisqa nom (ixtiyoriy): aksiya"><button class="btn" onclick="sla()">🔗 Yaratish</button>'+S.list.map(function(l){var u=S.base+l.code;return '<div style="padding:8px 0;border-top:1px solid var(--ln);margin-top:8px"><div class="row"><b style="font-size:14px">👆 '+nf(+l.clicks)+' marta bosildi</b><button class="btn s" style="flex:none;width:auto" onclick="sld('+l.id+')">🗑</button></div><div class="sub" style="word-break:break-all">'+esc(u)+'</div><div class="sub" style="word-break:break-all">→ '+esc(l.url)+'</div><button class="btn s" style="margin-top:4px;width:auto" onclick="cpyt(\''+esc(u)+'\')">📋 Nusxalash</button></div>'}).join('')+'</div>';
$('pox').innerHTML=h}
function cpyt(t){try{navigator.clipboard.writeText(t);toast('Nusxalandi ✅')}catch(e){toast(t)}}
function rsa(){api('rss_add',{chat:$('rs_c').value,url:$('rs_u').value.trim()}).then(function(j){if(j.ok){toast('Qo\'shildi ✅ Yangi maqolalar kanalga chiqadi');PX.rss=j;pxr()}})}
function rsd(id){cf('RSS manba o\'chirilsinmi?',function(y){if(y)api('rss_del',{id:id}).then(function(j){if(j.ok){PX.rss=j;pxr()}})})}
function cda(){api('cd_add',{chat:$('cd_c').value,title:$('cd_t').value,end_at:$('cd_e').value,pin:$('cd_p').checked?1:0}).then(function(j){if(j.ok){toast('Joylandi ✅');PX.cd=j;pxr()}})}
function cdd(id){api('cd_del',{id:id}).then(function(j){if(j.ok){PX.cd=j;pxr()}})}
function sla(){api('sl_add',{url:$('sl_u').value.trim(),code:$('sl_k').value.trim()}).then(function(j){if(j.ok){toast('Yaratildi ✅');PX.sl=j;pxr()}})}
function sld(id){cf('Havola o\'chirilsinmi?',function(y){if(y)api('sl_del',{id:id}).then(function(j){if(j.ok){PX.sl=j;pxr()}})})}
function gcl(){var e=$('gcb');if(!e)return;api('gc_list').then(function(j){if(j.ok){GCD=j;gcr()}})}
var GCD=null;
function gcr(){var j=GCD,h='<div class="card"><b>🔑 Sovg\'a kodi</b><div class="sub" style="margin:4px 0 8px">Kanalga yashirin kod chiqadi. Kodni botga birinchi yuborgan obunachilar yutadi — tez va qiziqarli o\'yin.</div>'+(j.chats.length?'<select id="gc_c">'+chopt(j.chats)+'</select><input id="gc_p" maxlength="300" placeholder="Sovg\'a: masalan, 20 000 so\'mlik paynet"><div style="display:flex;gap:8px"><input id="gc_k" maxlength="40" placeholder="Kod: BAHOR25" style="flex:1"><input id="gc_n" type="number" inputmode="numeric" min="1" max="100" value="10" style="flex:none;width:90px"></div><button class="btn" onclick="gca()">🎁 Kanalga joylash</button>':'<p class="sub">Avval kanal qo\'shing.</p>')+'</div>';
h+=j.list.map(function(g){return '<div class="card"><div class="row"><b>🎁 '+esc(g.prize)+'</b><span class="sub">'+(g.status==='active'?'🟢 '+g.n+'/'+g.winners:'✅ tugagan')+'</span></div><div class="sub">'+esc(g.username)+' · kod: <b>'+esc(g.code)+'</b></div>'+(g.wins.length?'<div style="margin-top:6px;font-size:14px">'+g.wins.map(function(w,i){return (i+1)+'. '+esc(w.name)+(w.uname?' @'+esc(w.uname):'')}).join('<br>')+'</div>':'')+(g.status==='active'?'<button class="btn s" style="margin-top:8px;width:auto" onclick="gcs('+g.id+')">⏹ Yakunlash</button>':'')+'</div>'}).join('');$('gcb').innerHTML=h}
function gca(){api('gc_add',{chat:$('gc_c').value,prize:$('gc_p').value,code:$('gc_k').value.trim(),winners:$('gc_n').value}).then(function(j){if(j.ok){toast('Kanalga joylandi ✅');GCD=j;gcr()}})}
function gcs(id){cf('Sovg\'a o\'yini yakunlansinmi?',function(y){if(y)api('gc_stop',{id:id}).then(function(j){if(j.ok){GCD=j;gcr()}})})}
function prc(w,id,p){var v=$(id).value.trim();if(!v)return;api('promo_check',{code:v,what:w}).then(function(j){var e=$(id+'_r');if(e)e.innerHTML=j.ok?'<span style="color:var(--g)">✅ '+j.pct+'% chegirma — '+fmt(Math.round(p*(100-j.pct)/100))+'</span>':''})}
function dmy(t){var d=new Date(t*1000),p=function(n){return('0'+n).slice(-2)};return p(d.getDate())+'.'+p(d.getMonth()+1)+'.'+d.getFullYear()}
var PCD=null;
function pcl(){$('pcb').innerHTML='<div class="sk"></div>';api('pc_list').then(function(j){if(!j.ok)return;PCD=j;var h='<p class="sub" style="margin:-6px 2px 12px">Yopiq (pullik) kanal va guruhlar. Obuna balansdan to\'lanadi, kirish havolasi botga keladi. Muddat tugaganda kanaldan chiqarilasiz.</p>';
h+=j.list.length?j.list.map(function(c){var my=+c.my_until>j.now;return '<div class="card"><div class="row"><div style="min-width:0"><b>🔐 '+esc(c.username)+'</b><div class="sub">'+(c.members?nf(+c.members)+' '+(c.ctype==='Kanal'?'obunachi':'a\'zo')+' · ':'')+c.days+' kun</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px">'+esc(c.descr)+'</div>':'')+(my?'<div class="sub" style="margin-top:6px;color:var(--g)">✅ Obunangiz '+dmy(c.my_until)+' gacha</div>':'')+(c.own==1?'<div class="sub" style="margin-top:8px">👤 Bu sizning kanalingiz — sozlamalari «Kanallarim» bo\'limida.</div>':'<button class="btn'+(my?' s':'')+'" style="margin-top:8px" onclick="pcbuy('+c.id+','+c.price+')">'+(my?'🔁 Uzaytirish':'🔓 Obuna bo\'lish')+' · '+fmt(+c.price)+'</button>')+'</div>'}).join(''):'<div class="card sub">Hozircha pullik kanal yo\'q. Kanal egasi bo\'lsangiz — «Kanallarim» → kanal kartasida «🔐 Pullik obuna»ni yoqing.</div>';$('pcb').innerHTML=h})}
function pcbuy(id,p){cf(fmt(p)+' balansingizdan yechiladi. Davom etilsinmi?',function(y){if(y)api('pc_buy',{id:id}).then(function(j){if(j.ok){toast('✅ Obuna faollashdi — kirish havolasi botga yuborildi');pcl()}else if(j.need_topup)go('bal')})})}
function pcOpen(id){var e=$('pcs'+id);e.innerHTML='<div class="sk"></div>';api('pc_get',{id:id}).then(function(j){if(j.ok)pcDraw(id,j);else e.innerHTML=''})}
function pcDraw(id,j){var p=j.pc;$('pcs'+id).innerHTML='<label class="lr in"><span class="lt"><b>Pullik obunani yoqish</b><span>Faol obunachilar: '+j.subs+' · jami tushum: '+fmt(+p.earned)+'</span></span><input type="checkbox" id="pco'+id+'"'+(p.on_==1?' checked':'')+'></label><input id="pcp'+id+'" type="number" inputmode="numeric" placeholder="Oylik narx (so\'m)" value="'+(+p.price||'')+'"><input id="pcd'+id+'" maxlength="300" placeholder="Tavsif: nima beriladi (masalan, VIP signal, darslar)" value="'+esc(p.descr||'')+'"><div class="sub" style="margin:-4px 0 8px">Pul obunachi balansidan sizning balansingizga tushadi (xizmat haqi '+j.fee+'%). Bot kanalda «Taklif havolasi» va «Bloklash» huquqiga ega bo\'lishi kerak.</div>'+(j.warn?'<div class="sub" style="color:var(--r);margin-bottom:8px">⚠️ '+esc(j.warn)+'</div>':'')+'<button class="btn s" onclick="pcSave('+id+')">💾 Saqlash</button>'}
function pcSave(id){api('pc_set',{id:id,on:$('pco'+id).checked?1:0,price:$('pcp'+id).value,descr:$('pcd'+id).value}).then(function(j){if(j.ok){toast(j.warn?'Saqlandi, lekin huquqni tekshiring':'Saqlandi ✅');pcDraw(id,j)}})}
var AUD=null,AUSEL=0,AUIMG='';
var FMT={'24':'1/24 (24 soatda o\'chadi)','48':'2/48 (48 soatda o\'chadi)','0':'doimiy'};
function aul(){$('aub').innerHTML='<div class="sk"></div>';api('auc_list').then(function(j){if(j.ok){AUD=j;aur()}})}
function aur(){var j=AUD,h='<p class="sub" style="margin:-6px 2px 12px">Kanallarga reklamani to\'g\'ridan-to\'g\'ri egasidan oling: narx ochiq, pul faqat reklama joylangach egasiga o\'tadi. 24 soatda javob bo\'lmasa — pul qaytadi.</p>';
h+=j.list.length?j.list.map(function(c){return '<div class="card"><div class="row"><div style="min-width:0"><b>📢 '+esc(c.username)+'</b><div class="sub">'+(c.members?nf(+c.members)+' obunachi · ':'')+esc(c.vz_cat||'Umumiy')+' · '+FMT[c.fmt]+'</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px">'+esc(c.descr)+'</div>':'')+(AUSEL==c.id?'<div style="margin-top:8px"><textarea id="aut" rows="4" maxlength="1000" placeholder="Reklama matni"></textarea><label class="up">🖼 Rasm (ixtiyoriy)<input type="file" accept="image/*" style="display:none" onchange="auPick(this)"></label><div id="aupv" class="sub"></div><div style="display:flex;gap:8px"><input id="aup" maxlength="30" placeholder="🎟 Promo-kod" style="flex:1;min-width:0;text-transform:uppercase"><button class="btn s" style="flex:none;width:auto" onclick="prc(\'auc\',\'aup\','+c.price+')">Tekshirish</button></div><div id="aup_r" class="sub" style="margin:-4px 0 8px"></div><button class="btn" onclick="aubuy('+c.id+','+c.price+')">💳 To\'lash va yuborish</button></div>':'<button class="btn s" style="margin-top:8px" onclick="AUSEL='+c.id+';AUIMG=\'\';aur()">🛒 Reklama berish</button>')+'</div>'}).join(''):'<div class="card sub">Hozircha reklama joyi yo\'q. Kanal egasi bo\'lsangiz — kanal kartasida «📣 Reklama birjasi»ni yoqing.</div>';
var ST2={pending:'⏳ Egasi ko\'rib chiqmoqda',posting:'⏳',posted:'✅ Joylandi',rejected:'❌ Rad etildi (pul qaytdi)',expired:'⌛ Javob bo\'lmadi (pul qaytdi)'};
if(j.mine.length)h+='<div class="card"><b>🛒 Buyurtmalarim</b>'+j.mine.map(function(o){return '<div class="row" style="margin-top:8px"><div><b>'+esc(o.username)+' · '+fmt(+o.price)+'</b><div class="sub">#'+o.id+'</div></div><span class="tag">'+(ST2[o.status]||o.status)+'</span></div>'}).join('')+'</div>';
if(j.sales.length)h+='<div class="card"><b>💰 Sotuvlarim</b>'+j.sales.map(function(o){return '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--ln)"><div class="row"><b>'+esc(o.username)+' · '+fmt(o.price-o.fee)+'</b><span class="tag">'+(ST2[o.status]||o.status)+'</span></div><div class="sub" style="word-break:break-word">'+esc(String(o.body).slice(0,160))+'</div>'+(o.status==='pending'?'<div style="display:flex;gap:8px;margin-top:6px"><button class="btn" onclick="auact('+o.id+',1)">✅ Joylash</button><button class="btn s" onclick="auact('+o.id+',0)">❌ Rad etish</button></div>':'')+'</div>'}).join('')+'</div>';
$('aub').innerHTML=h}
function auPick(i){var f=i.files&&i.files[0];if(!f)return;imgfit(f,1280,1280,false,function(d){AUIMG=d;$('aupv').textContent='🖼 Rasm tanlandi'})}
function aubuy(id,p){var t=$('aut').value.trim();if(t.length<5){toast('Reklama matnini yozing');return}cf(fmt(p)+' balansingizdan yechiladi (rad etilsa qaytadi). Yuborilsinmi?',function(y){if(y)api('auc_buy',{id:id,text:t,image:AUIMG,promo:$('aup').value.trim()}).then(function(j){if(j.ok){toast('✅ Buyurtma kanal egasiga yuborildi');AUSEL=0;AUD=j;aur()}else if(j.need_topup)go('bal')})})}
function auact(id,ok){api('auc_act',{id:id,ok:ok}).then(function(j){if(j.ok){toast(ok?'✅ Joylandi':'Rad etildi');AUD=j;aur()}})}
function auOpen(id){var e=$('aus'+id);e.innerHTML='<div class="sk"></div>';api('auc_get',{id:id}).then(function(j){if(j.ok)auDraw(id,j);else e.innerHTML=''})}
function auDraw(id,j){var p=j.slot;$('aus'+id).innerHTML='<label class="lr in"><span class="lt"><b>Reklama joyini sotish</b><span>Sotilgan: '+j.sold+' ta</span></span><input type="checkbox" id="auo'+id+'"'+(p.on_==1?' checked':'')+'></label><div style="display:flex;gap:8px"><input id="aupr'+id+'" type="number" inputmode="numeric" placeholder="Narx (so\'m)" value="'+(+p.price||'')+'" style="flex:1;min-width:0"><select id="auf'+id+'" style="flex:1;min-width:0">'+['24','48','0'].map(function(k){return '<option value="'+k+'"'+(p.fmt==k?' selected':'')+'>'+FMT[k]+'</option>'}).join('')+'</select></div><input id="aud'+id+'" maxlength="300" placeholder="Shartlar: mavzu cheklovi, joylash vaqti" value="'+esc(p.descr||'')+'"><div class="sub" style="margin:-4px 0 8px">Buyurtma kelganda bot sizga yozadi — «Joylash» bosilsa reklama kanalga chiqadi va pul (xizmat haqi '+j.fee+'% ayirib) balansingizga tushadi.</div><button class="btn s" onclick="auSave('+id+')">💾 Saqlash</button>'}
function auSave(id){api('auc_set',{id:id,on:$('auo'+id).checked?1:0,price:$('aupr'+id).value,fmt:$('auf'+id).value,descr:$('aud'+id).value}).then(function(j){if(j.ok){toast('Saqlandi ✅');auDraw(id,j)}})}
function rtl(){$('rtb').innerHTML='<div class="sk"></div>';api('rt_list').then(function(j){if(j.ok)rtr(j)})}
function rtr(j){var row=function(c,i,b){return '<div class="row" style="padding:10px 0;border-top:1px solid var(--ln)"><div style="min-width:0"><b>'+(b?'⭐ ':(i<3?['🥇','🥈','🥉'][i]:(i+1)+'.')+' ')+esc(c.username)+'</b><div class="sub">'+nf(c.members)+' obunachi'+(c.cat?' · '+esc(c.cat):'')+'</div></div>'+(c.grow!=null?'<b style="flex:none;color:var(--g)">+'+nf(c.grow)+(c.pct!=null?' <span class="sub">('+c.pct+'%)</span>':'')+'</b>':'')+'</div>'},h='<p class="sub" style="margin:-6px 2px 12px">Oxirgi 7 kunda eng tez o\'sgan kanallar. Har kuni yangilanadi.</p>';
if(j.boost.length)h+='<div class="card"><b>⭐ Tavsiya etiladi</b>'+j.boost.map(function(c){return row(c,0,1)}).join('')+'</div>';
h+='<div class="card"><b>🏆 Haftaning TOP-10</b>'+(j.top.length?j.top.map(function(c,i){return row(c,i,0)}).join(''):'<div class="sub" style="margin-top:6px">Reyting statistikadan hisoblanadi — bir necha kundan keyin paydo bo\'ladi.</div>')+'</div>';
if(j.my.length)h+='<div class="card"><b>🚀 Kanalimni ko\'tarish</b><div class="sub" style="margin:4px 0 8px">Kanalingiz 7 kun «⭐ Tavsiya etiladi» qatorida, eng tepada turadi'+(j.price?' — narxi '+fmt(j.price):' (tez orada)')+'.</div>'+j.my.map(function(c){return '<div class="row" style="padding:8px 0;border-top:1px solid var(--ln)"><b>'+esc(c.username)+'</b>'+(c.boost?'<span class="tag">⭐ '+dmy(c.boost)+' gacha</span>':'')+(j.price?'<button class="btn s" style="flex:none;width:auto" onclick="rtb('+c.id+','+j.price+')">🚀 '+(c.boost?'Uzaytirish':'Ko\'tarish')+'</button>':'')+'</div>'}).join('')+'</div>';$('rtb').innerHTML=h}
function rtb(id,p){cf(fmt(p)+' balansingizdan yechiladi. Kanal 7 kun tavsiya qatorida turadi.',function(y){if(y)api('rt_boost',{id:id}).then(function(j){if(j.ok){toast('🚀 Kanalingiz ko\'tarildi');rtr(j)}else if(j.need_topup)go('bal')})})}
var XT=null;
function xtr(){var j=XT,ST=j.mon.st,AL2={topup_approve:'✅ To\'lov tasdiqlandi',topup_reject:'❌ To\'lov rad etildi',ad_send:'📤 E\'lon yuborildi',ad_reject:'❌ E\'lon rad etildi',paycfg:'💳 Karta/narx o\'zgardi',promo_add:'🎟 Promo-kod',promo_del:'🗑 Promo-kod o\'chirildi',tfa:'🔐 2FA',tfa_ok:'🔐 Kod bilan kirdi',xt_set:'⚙️ Sozlamalar',boost:'🚀 Ko\'tarish',kechki_xabar:'🌙 Kechki xabar'},h='<h1>🧩 Qo\'shimcha</h1>';
h+='<div class="card"><div class="row"><b>🔐 Ikki bosqichli tasdiqlash</b><span style="cursor:pointer;flex:none" onclick="xtfa()">'+ck(j.tfa)+'</span></div><div class="sub">Yoqilsa, to\'lovni tasdiqlash, e\'lon yuborish, karta/narxni o\'zgartirish va ommaviy xabar uchun botga keladigan 6 xonali kod so\'raladi (30 daqiqada bir marta). Telefoningiz qo\'lga tushsa ham, ilova orqali pul amallarini qilib bo\'lmaydi.</div></div>';
h+='<div class="card"><div class="row"><b>🔕 Kechasi ovozsiz</b><span style="cursor:pointer;flex:none" onclick="XT.quiet.on=!XT.quiet.on;xtr()">'+ck(j.quiet.on)+'</span></div><div class="sub" style="margin-bottom:6px">Shu vaqtda kanal va guruhlarga bot xabarlari bildirishnomasiz (ovozsiz) ketadi — obunachilar uyg\'onmaydi.</div><div style="display:flex;gap:8px"><input id="xq_f" type="time" value="'+esc(j.quiet.from)+'" style="flex:1;min-width:0"><input id="xq_t" type="time" value="'+esc(j.quiet.to)+'" style="flex:1;min-width:0"></div><button class="btn s" onclick="xts({quiet_on:XT.quiet.on?1:0,quiet_from:$(\'xq_f\').value,quiet_to:$(\'xq_t\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><div class="row"><b>🩺 Sayt monitoringi</b><span style="cursor:pointer;flex:none" onclick="XT.mon.on=!XT.mon.on;xtr()">'+ck(j.mon.on)+'</span></div><div class="sub" style="margin-bottom:6px">Har 5 daqiqada tekshiriladi. Sayt ishlamay qolsa yoki qayta ishlasa — sizga darhol xabar keladi.</div>'+Object.keys(ST).map(function(u){var x=ST[u];return '<div class="row sub" style="padding:4px 0"><span style="word-break:break-all">'+(x.ok?'🟢':'🔴')+' '+esc(u.replace(/^https?:\/\//,'').slice(0,40))+'</span><span style="flex:none">'+(x.ok?x.ms+' ms':'HTTP '+(x.code||'—'))+'</span></div>'}).join('')+'<textarea id="xm_u" rows="4" placeholder="Har qatorda bitta manzil">'+esc(j.mon.urls)+'</textarea><button class="btn s" onclick="xts({mon_on:XT.mon.on?1:0,mon_urls:$(\'xm_u\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>💰 Komissiya va narxlar</b><p class="sub" style="margin:8px 0 2px">🔐 Pullik kanal — xizmat haqi (%)</p><input id="xf_pc" type="number" min="0" max="50" value="'+j.fees.pc_fee+'"><p class="sub" style="margin:0 0 2px">📣 Reklama birjasi — xizmat haqi (%)</p><input id="xf_au" type="number" min="0" max="50" value="'+j.fees.auc_fee+'"><p class="sub" style="margin:0 0 2px">🚀 Reytingda ko\'tarish — 7 kun narxi (0 — o\'chiq)</p><input id="xf_bp" type="number" min="0" value="'+j.fees.boost_price+'"><p class="sub" style="margin:0 0 2px">🏷 Kanal bozori — vositachilik haqi (%)</p><input id="xf_sf" type="number" min="0" max="50" value="'+j.fees.sale_fee+'"><button class="btn s" onclick="xts({pc_fee:$(\'xf_pc\').value,auc_fee:$(\'xf_au\').value,boost_price:$(\'xf_bp\').value,sale_fee:$(\'xf_sf\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><div class="row"><b>📣 Kun kanali</b><span style="cursor:pointer;flex:none" onclick="XT.kk.on=!XT.kk.on;xtr2()">'+ck(j.kk.on)+'</span></div><div class="sub" style="margin-bottom:6px">Har kuni tasodifiy qatnashuvchi kanal boshqa qatnashuvchilarda tavsiya etiladi (24 soatda o\'chadi). Qatnashuvchilar: '+j.kk.n+' ta.</div><input id="xk_t" type="time" value="'+esc(j.kk.time)+'"><button class="btn s" onclick="xts({kk_gon:XT.kk.on?1:0,kk_time:$(\'xk_t\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>🧑‍🤝‍🧑 Kanal egalari klubi</b><div class="sub" style="margin:4px 0 6px">Yopiq guruh ID si yoki @username. Bot u yerda «Taklif havolasi» huquqi bilan admin bo\'lsin — har bir kanal egasiga shaxsiy bir martalik havola beriladi. Bo\'sh qoldirilsa — klub ko\'rinmaydi.</div><input id="xc_c" placeholder="-1001234567890" value="'+esc(j.club)+'"><button class="btn s" onclick="xts({club_chat:$(\'xc_c\').value})">💾 Saqlash</button></div>';
h+='<div class="card"><b>🎓 Video qo\'llanmalar</b><div class="sub" style="margin:4px 0 6px">Videoni baza kanalga joylang va havolasini kiriting — o\'sha bo\'limda «❓ Qanday ishlaydi» tugmasi paydo bo\'ladi.</div><select id="xh_p">'+Object.keys(HLN).map(function(k){return '<option value="'+k+'">'+HLN[k]+(j.help[k]?' ✅':'')+'</option>'}).join('')+'</select><input id="xh_l" placeholder="https://t.me/c/1234567890/45 (bo\'sh — o\'chirish)"><button class="btn s" onclick="xts({help_page:$(\'xh_p\').value,help_link:$(\'xh_l\').value.trim()});HLV=null">💾 Saqlash</button>'+Object.keys(j.help).map(function(k){return '<div class="sub" style="padding:4px 0">✅ '+esc(HLN[k]||k)+' — '+esc(j.help[k])+'</div>'}).join('')+'</div>';
var SC={ads:'E\'lonlar',auc:'Reklama birjasi',boost:'Ko\'tarish',all:'Hammasi'};
h+='<div class="card"><b>🎟 Promo-kodlar</b><div style="display:flex;gap:8px;margin-top:8px"><input id="xp_c" maxlength="30" placeholder="KOD" style="flex:1.4;min-width:0;text-transform:uppercase"><input id="xp_p" type="number" min="1" max="90" placeholder="%" style="flex:.6;min-width:0"></div><div style="display:flex;gap:8px"><input id="xp_u" type="number" min="0" placeholder="Limit (0 — cheksiz)" style="flex:1;min-width:0"><input id="xp_d" type="number" min="0" placeholder="Kun (0 — muddatsiz)" style="flex:1;min-width:0"></div><select id="xp_s">'+Object.keys(SC).map(function(k){return '<option value="'+k+'">'+SC[k]+'</option>'}).join('')+'</select><button class="btn s" onclick="xpa()">➕ Yaratish</button>'+j.promo.map(function(p){return '<div class="row" style="padding:6px 0;border-top:1px solid var(--ln)"><div><b>'+esc(p.code)+'</b> · -'+p.pct+'%<div class="sub">'+SC[p.scope]+' · '+p.used+(+p.max_uses?'/'+p.max_uses:'')+' marta'+(+p.until?' · '+dmy(p.until)+' gacha':'')+'</div></div><button class="btn s" style="flex:none;width:auto" onclick="xpd(\''+esc(p.code)+'\')">🗑</button></div>'}).join('')+'</div>';
h+='<div class="card"><b>🔑 Admin harakatlari tarixi</b>'+(j.audit.length?j.audit.map(function(a){return '<div style="padding:6px 0;border-top:1px solid var(--ln)"><div class="row sub"><span>'+esc(a.name||'Admin')+(a.username?' @'+esc(a.username):'')+'</span><span>'+esc(dtf(a.at))+'</span></div><div style="font-size:14px">'+esc(AL2[a.action]||a.action)+(a.detail?' <span class="sub">'+esc(String(a.detail).slice(0,80))+'</span>':'')+'</div></div>'}).join(''):'<div class="sub">Hali yozuv yo\'q.</div>')+'</div>';return h}
function xtr2(){av('xt')}
function xts(o){api('adm_xt_set',o).then(function(j){if(j.ok){XT=j;toast('Saqlandi ✅');av('xt')}})}
function xtfa(){api('adm_tfa',{on:XT.tfa?0:1}).then(function(j){if(j.ok){XT=j;toast(j.tfa?'🔐 2FA yoqildi':'2FA o\'chirildi');av('xt')}})}
function xpa(){api('adm_pk_add',{code:$('xp_c').value.trim(),pct:$('xp_p').value,uses:$('xp_u').value,days:$('xp_d').value,scope:$('xp_s').value}).then(function(j){if(j.ok){XT=j;toast('Yaratildi ✅');av('xt')}})}
function xpd(c){cf('Promo-kod o\'chirilsinmi?',function(y){if(y)api('adm_pk_del',{code:c}).then(function(j){if(j.ok){XT=j;av('xt')}})})}
function stcsv(id){toast('Tayyorlanmoqda...');api('stat_csv',{id:id}).then(function(j){if(j.ok)toast('📤 Fayl botga yuborildi ✅')})}
function pobt(){var c=$('po_c').value;api('best_time',{chat:c==='all'?0:c}).then(function(j){if(j.ok){$('po_t').value=j.run_at;toast('🧠 '+('0'+j.hour).slice(-2)+':00 — '+j.src)}})}
function clubl(){var e=$('clubb');if(!e)return;api('club').then(function(j){e.innerHTML=j.ok&&j.on&&j.can?'<div class="card"><div class="row"><div><b>🧑‍🤝‍🧑 Kanal egalari klubi</b><div class="sub">Yopiq guruh: tajriba almashish, birgalikda reklama aksiyalari</div></div><button class="btn s" style="flex:none;width:auto" onclick="api(\'club_join\').then(function(k){if(k.ok)toast(\'👉 Taklif havolasi botga yuborildi\')})">Qo\'shilish</button></div></div>':''})}
var SAD=null;
function sall(){$('saleb').innerHTML='<div class="sk"></div>';api('sale_list').then(function(j){if(!j.ok)return;SAD=j;var h='<p class="sub" style="margin:-6px 2px 12px">Sotuvdagi kanal va guruhlar. Raqamlar TartibOn statistikasidan olinadi — soxta emas. Xavfsiz savdo uchun «🛡 Vositachi» tugmasini bosing (haqi '+j.fee+'%).</p>';
h+=j.list.length?j.list.map(function(c){var g=c.m30?(+c.members-c.m30):null,age=Math.max(0,Math.round((Date.now()/1000-new Date(String(c.created_at).replace(' ','T')).getTime()/1000)/86400));return '<div class="card"><div class="row"><div style="min-width:0"><b>🏷 '+esc(c.username)+'</b><div class="sub">'+(c.members?nf(+c.members)+' '+(c.ctype==='Kanal'?'obunachi':'a\'zo'):'')+(g!=null?' · 30 kunda '+(g>=0?'+':'')+nf(g):'')+(c.vz_cat?' · '+esc(c.vz_cat):'')+'</div></div><b style="flex:none">'+fmt(+c.price)+'</b></div>'+(c.descr?'<div class="sub" style="margin-top:6px">'+esc(c.descr)+'</div>':'')+'<div class="sub" style="margin-top:4px">✅ TartibOn\'da '+age+' kundan beri · statistika tasdiqlangan</div>'+(c.own==1?'<div class="sub" style="margin-top:8px">👤 Bu sizning e\'loningiz</div>':'<div style="display:flex;gap:8px;margin-top:8px"><button class="btn s" onclick="salm('+c.id+')">📩 Sotuvchiga yozish</button><button class="btn s" onclick="sals('+c.id+')">🛡 Vositachi</button></div>')+'</div>'}).join(''):'<div class="card sub">Hozircha sotuvda kanal yo\'q. Sotmoqchi bo\'lsangiz — kanal kartasida «🏷 Sotuvga qo\'yish».</div>';$('saleb').innerHTML=h})}
function salm(id){cf('Sotuvchiga sizning ismingiz va profilingiz yuboriladi. Davom etilsinmi?',function(y){if(y)api('sale_msg',{id:id,text:''}).then(function(j){if(j.ok)toast('📩 Sotuvchiga yuborildi — u siz bilan bog\'lanadi')})})}
function sals(id){cf('TartibOn admini vositachi bo\'ladi: pul admin orqali o\'tadi, kanal topshirilgach sotuvchiga beriladi. So\'rov yuborilsinmi?',function(y){if(y)api('sale_safe',{id:id}).then(function(j){if(j.ok)toast('🛡 So\'rov yuborildi — admin bog\'lanadi')})})}
function slOpen(id){var e=$('sls'+id);e.innerHTML='<div class="sk"></div>';api('sale_get',{id:id}).then(function(j){if(j.ok)slDraw(id,j);else e.innerHTML=''})}
function slDraw(id,j){var p=j.sale;$('sls'+id).innerHTML='<label class="lr in"><span class="lt"><b>Sotuvga qo\'yish</b><span>«Kanal bozori» bo\'limida ko\'rinadi</span></span><input type="checkbox" id="slo'+id+'"'+(p.on_==1?' checked':'')+'></label><input id="slp'+id+'" type="number" inputmode="numeric" placeholder="Narx (so\'m)" value="'+(+p.price||'')+'"><input id="sld'+id+'" maxlength="300" placeholder="Tavsif: mavzu, auditoriya, daromad" value="'+esc(p.descr||'')+'"><button class="btn s" onclick="slSave('+id+')">💾 Saqlash</button>'}
function slSave(id){api('sale_set',{id:id,on:$('slo'+id).checked?1:0,price:$('slp'+id).value,descr:$('sld'+id).value}).then(function(j){if(j.ok){toast('Saqlandi ✅');slDraw(id,j)}})}
var HLV=null,HLN={home:'Bosh sahifa',pcb:'Dollar kursi',pnm:'Namoz vaqtlari',pwx:'Ob-havo',pdp:'Tongi xabar',bt:'Bayram tabriklari',po:'Rejalashtirilgan postlar',gd:'Guruh himoyasi',gw:'Konkurslar',qz:'Savol-javob',st:'Statistika',rf:'Taklif havolalari',vz:'O\'zaro reklama',auc:'Reklama birjasi',pc:'Pullik kanallar',rt:'Kanallar reytingi',sale:'Kanal bozori',my:'Kanallarim',bal:'Balans',ads:'E\'lon berish'};
function hlp(p){var put=function(){var pg=$('p-'+p);if(!pg||!HLV||HLV.indexOf(p)<0)return;var h=pg.querySelector('h1');if(h&&!h.querySelector('.hlpb'))h.insertAdjacentHTML('beforeend',' <button class="hlpb" onclick="hlpS(\''+p+'\')" style="border:0;background:var(--soft);color:var(--ac);border-radius:14px;padding:4px 10px;font-size:14px;font-weight:600;vertical-align:middle;cursor:pointer">❓ Qanday ishlaydi</button>')};if(HLV)put();else api('help_list').then(function(j){HLV=j.ok?j.v:[];put()})}
function hlpS(p){toast('Yuborilmoqda...');api('help_send',{page:p}).then(function(j){if(j.ok)toast('🎓 Video botga yuborildi')})}
function chp(id,d){api('chat_pause',{id:id,days:d}).then(function(j){if(j.ok){toast(d?'⏸ Ta\'til rejimi yoqildi':'▶️ Avtomatik xabarlar qayta yoqildi');chats()}})}
function chpb(id){api('chat_pb',{id:id,share:$('pbs'+id).checked?1:0,text:$('pbt'+id).value,url:$('pbu'+id).value.trim()}).then(function(j){if(j.ok){toast('Saqlandi ✅');$('pbu'+id).value=j.url}})}
function chps(id){toast('Tayyorlanmoqda...');api('chat_passport',{id:id}).then(function(j){if(j.ok)toast('Pasport sizga yuborildi ✅')})}
function por(){var j=POD,h='<div class="card"><b>➕ Yangi post</b>'+(j.chats.length?'<select id="po_c">'+(j.chats.length>1?'<option value="all">🌐 Barcha kanal va guruhlarimga</option>':'')+chopt(j.chats)+'</select><textarea id="po_b" rows="6" maxlength="4096" placeholder="Post matni... (qalin: &lt;b&gt;..&lt;/b&gt;, havola: &lt;a href=&quot;..&quot;&gt;..&lt;/a&gt;)"></textarea><input id="po_s" placeholder="Rasm/video (ixtiyoriy): t.me/... post havolasi"><div style="display:flex;gap:8px"><input id="po_bt" placeholder="Tugma nomi" style="flex:1"><input id="po_bu" placeholder="Tugma havolasi https://" style="flex:1.4"></div><p class="sub" style="margin:0">Yuborish vaqti (Toshkent) · <a href="#" onclick="pobt();return false" style="color:var(--ac)">🧠 aqlli vaqt</a></p><input id="po_t" type="datetime-local" value="'+dtl(10)+'"><select id="po_r"><option value="none">Bir marta</option><option value="daily">Har kuni</option><option value="weekly">Har hafta</option></select><select id="po_d"><option value="0">🗑 Avto-o\'chirish: yo\'q</option><option value="1">1 soatdan keyin o\'chsin</option><option value="3">3 soatdan keyin</option><option value="6">6 soatdan keyin</option><option value="12">12 soatdan keyin</option><option value="24">⏳ 24 soatdan keyin (1/24 reklama)</option><option value="48">48 soatdan keyin</option><option value="72">72 soatdan keyin</option></select><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" style="flex:1" onclick="pos()">🗓 Rejalashtirish</button><button class="btn s" onclick="pot()">🧪 Menga yuborish</button></div><button class="btn s" style="margin-top:6px" onclick="pobt()">🧠 Eng yaxshi vaqtni qo\'yish</button><p class="sub" style="margin:8px 0 0">Rasm yoki video uchun uni istalgan kanalga (masalan, video baza) joylang va post havolasini kiriting — matn uning tagiga yoziladi. Bot o\'sha kanalda admin bo\'lishi kerak.</p>':'<p class="sub">Avval kanal yoki guruh qo\'shing.</p>')+'</div>';
h+=j.posts.length?'<h1 style="font-size:18px">🗓 Postlar</h1>'+j.posts.map(function(p){return '<div class="card"><div class="row"><b>'+(p.ctype==='Kanal'?'📢 ':'👥 ')+esc(p.username)+'</b><span class="tag">'+(p.active==1?'⏳ '+REP[p.rep]:(+p.sent_n?'✅ Yuborildi':'⏸ To\'xtatilgan'))+'</span></div><div class="sub">'+(p.active==1?'Navbatdagi: '+esc(dtf(p.run_at)):(p.last_at?'Oxirgi: '+esc(dtf(p.last_at)):''))+(+p.sent_n?' · '+p.sent_n+' marta yuborildi':'')+(p.src?' · 🖼 media':'')+(p.btn_text?' · 🔘 '+esc(p.btn_text):'')+(+p.del_h?' · ⏳ '+p.del_h+' soatdan keyin o\'chadi':'')+'</div>'+(p.last_err?'<div class="sub" style="color:var(--r)">⚠️ '+esc(p.last_err)+'</div>':'')+'<div style="white-space:pre-wrap;word-break:break-word;margin:8px 0;font-size:14px;max-height:120px;overflow:hidden">'+esc(p.body)+'</div><div style="display:flex;gap:6px;flex-wrap:wrap">'+((p.active==1||p.rep!=='none')?'<button class="btn s" onclick="poa(\'post_toggle\','+p.id+')">'+(p.active==1?'⏸ To\'xtatish':'▶️ Davom ettirish')+'</button>':'')+'<button class="btn s" onclick="poa(\'post_del\','+p.id+')">🗑 O\'chirish</button></div></div>'}).join(''):'';
$('pob').innerHTML=h}
function pov(){return {chat:$('po_c').value,body:$('po_b').value,src:$('po_s').value,btn_text:$('po_bt').value,btn_url:$('po_bu').value,run_at:$('po_t').value,rep:$('po_r').value,del_h:$('po_d').value}}
function pos(){api('post_save',pov()).then(function(j){if(j.ok){toast(j.n>1?j.n+' ta kanal/guruhga rejalashtirildi ✅':'Rejalashtirildi ✅');pol()}})}
function pot(){api('post_test',pov()).then(function(j){if(j.ok)toast('Sizga yuborildi ✅')})}
function poa(a,id){var go2=function(){api(a,{id:id}).then(function(j){if(j.ok)pol()})};if(a==='post_del')cf('Post o\'chirilsinmi?',function(y){if(y)go2()});else go2()}
/* ---- Statistika ---- */
function stl(){$('stb').innerHTML='<div class="sk"></div>';api('stat_my').then(function(j){if(!j.ok)return;var h='';
var dl=function(v,t){return v==null?'':'<div style="flex:1;text-align:center"><b class="'+(v>0?'g':v<0?'r':'')+'">'+(v>0?'+':'')+f(v)+'</b><div class="sub">'+t+'</div></div>'};
var bars=function(D,k,col){var mx=1,mn=null;D.forEach(function(d){var v=+d[k];if(d[k]!=null&&v>=0){mx=Math.max(mx,v);mn=mn==null?v:Math.min(mn,v)}});if(mn==null)return '';var base=k==='members'?Math.max(0,mn-(mx-mn)*0.3-1):0;
return '<div style="display:flex;align-items:flex-end;gap:3px;height:56px;margin-top:8px">'+D.map(function(d){var v=+d[k];var hh=d[k]==null||v<0?0:Math.max(3,Math.round((v-base)/(mx-base)*56));return '<div title="'+esc(d.day)+': '+f(v)+'" style="flex:1;height:'+hh+'px;background:'+col+';border-radius:3px 3px 0 0"></div>'}).join('')+'</div>'};
h+=j.chats.length?j.chats.map(function(c){var D=c.days||[],ms=0,jn=0,lf=0;D.forEach(function(d){ms+=+d.msgs;jn+=+d.joins;lf+=+d.lefts});
return '<div class="card"><div class="row"><b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b><span class="sub">'+(c.ctype==='Kanal'?'obunachi':'a\'zo')+'</span></div><div style="font-size:30px;font-weight:700;margin:6px 0">'+(c.now==null?'—':f(c.now))+'</div><div style="display:flex;gap:6px">'+dl(c.d1,'kecha')+dl(c.d7,'7 kun')+dl(c.d30,'30 kun')+'</div>'+bars(D,'members','var(--ac)')+'<div class="sub" style="margin-top:4px">So\'nggi 14 kun · '+(c.ctype==='Guruh'?'💬 '+f(ms)+' xabar · ':'')+(jn||lf?'➕ '+f(jn)+' kirdi · ➖ '+f(lf)+' chiqdi':'kirdi-chiqdi bot admin bo\'lgach hisoblanadi')+'</div>'+(c.ctype==='Guruh'&&ms?bars(D,'msgs','#34c759'):'')+'<button class="btn s" style="margin-top:8px" onclick="stcsv('+c.id+')">📤 Excel (CSV) yuklab olish</button></div>'}).join(''):'<div class="card sub">Kanal yoki guruh qo\'shing — statistika shu yerda chiqadi.</div>';
h+='<div class="card row" style="cursor:pointer" onclick="api(\'stat_wr\',{on:'+(j.wr?0:1)+'}).then(stl)"><div style="display:flex;align-items:center;gap:10px">'+ck(j.wr)+'<div><b>📨 Haftalik hisobot</b><div class="sub">har dushanba soat 9:00 da sizga shaxsan</div></div></div></div><p class="sub" style="margin:0 4px 12px">Postlarning ko\'rishlar sonini Telegram botlarga bermaydi, shuning uchun ular hisobotda yo\'q.</p>';
$('stb').innerHTML=h})}
/* ---- Konkurslar ---- */
var GWD=null,GWS={active:'⏳ Davom etmoqda',done:'✅ Yakunlandi',cancel:'❌ Bekor qilingan'};
function gwl(){api('gw_list').then(function(j){if(!j.ok)return;GWD=j;gwr()})}
function gwr(){var j=GWD,h='<div class="card"><b>🎁 Yangi konkurs</b>'+(j.chats.length?'<p class="sub" style="margin:8px 0 0">Qayerda e\'lon qilinadi</p><select id="gw_c">'+chopt(j.chats)+'</select><textarea id="gw_t" rows="5" maxlength="1500" placeholder="Konkurs haqida: sovrin, qoidalar..."></textarea><p class="sub" style="margin:0 0 4px">Shart — obuna bo\'lish kerak:</p><p class="sub" style="margin:0 0 6px;padding:8px 10px;border-radius:12px;background:var(--soft);color:var(--tx)">ℹ️ Ro\'yxatda faqat bot administrator bo\'lgan kanal va guruhlar chiqadi. Boshqa kanal yoki guruhni shart qilish uchun avval botni o\'sha kanal/guruhga <b>administrator</b> qiling va «Kanal qo\'shish» yoki «Guruh qo\'shish» orqali ulang.</p>'+j.chats.map(function(c,n){return '<label style="display:block;margin:6px 0"><input type="checkbox" class="gw_rq" value="'+c.id+'" style="width:auto;margin:0 8px 0 0"'+(n===0?' checked':'')+'> '+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</label>'}).join('')+'<div style="display:flex;gap:8px"><div style="flex:1"><p class="sub" style="margin:0">G\'oliblar soni</p><input id="gw_w" type="number" inputmode="numeric" min="1" max="20" value="1"></div><div style="flex:1.6"><p class="sub" style="margin:0">Yakunlanish (Toshkent)</p><input id="gw_e" type="datetime-local" value="'+dtl(1440)+'"></div></div><button class="btn" onclick="gwc()">🚀 Konkursni boshlash</button><p class="sub" style="margin:8px 0 0">Post tugma bilan joylanadi. Bosganlarning obunasi tekshiriladi. Vaqt tugaganda g\'oliblar tasodifiy tanlanib (obunadan chiqqanlar hisobga olinmaydi) e\'lon qilinadi.</p>':'<p class="sub">Avval kanal yoki guruh qo\'shing.</p>')+'</div>';
h+=j.list.map(function(g){var w=g.result?JSON.parse(g.result):[];return '<div class="card"><div class="row"><b>'+esc(g.username)+'</b><span class="tag">'+GWS[g.status]+'</span></div><div class="sub">👥 '+g.n+' ishtirokchi · 🏆 '+g.winners+' g\'olib · ⏰ '+esc(dtf(g.ends_at))+'</div><div style="white-space:pre-wrap;word-break:break-word;margin:8px 0;font-size:14px;max-height:90px;overflow:hidden">'+esc(g.title)+'</div>'+(w.length?'<div class="sub">G\'oliblar: '+w.map(function(x){return esc(x.name)+(x.username?' @'+esc(x.username):'')}).join(', ')+'</div>':'')+(g.status==='active'?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><button class="btn s" onclick="gwa(\'gw_finish\','+g.id+')">🏁 Hozir yakunlash</button><button class="btn s" onclick="gwa(\'gw_cancel\','+g.id+')">❌ Bekor qilish</button></div>':'')+'</div>'}).join('');
$('gwb').innerHTML=h}
function gwc(){var rq=[];document.querySelectorAll('.gw_rq').forEach(function(x){if(x.checked)rq.push(x.value)});api('gw_create',{chat:$('gw_c').value,title:$('gw_t').value,req:rq,winners:$('gw_w').value,ends:$('gw_e').value}).then(function(j){if(j.ok){toast('Konkurs boshlandi 🎉');gwl()}})}
function gwa(a,id){cf(a==='gw_finish'?'Konkurs hozir yakunlanib, g\'oliblar e\'lon qilinsinmi?':'Konkurs bekor qilinsinmi?',function(y){if(y)api(a,{id:id}).then(function(j){if(j.ok)gwl()})})}
/* ---- Taklif havolalari ---- */
var RFD=null;
function rfl(){api('ref_list').then(function(j){if(!j.ok)return;RFD=j;rfr()})}
function rfr(){var j=RFD,md=['🥇','🥈','🥉'],h='<div class="card"><b>🔗 Do\'stlarni taklif qiling</b><div class="sub" style="margin-top:6px">Shaxsiy havolangizni oling va tarqating. Havola orqali kirgan har bir odam sizga hisoblanadi. Eng ko\'p taklif qilganlar reytingda.</div></div>';
h+=j.open.length?j.open.map(function(c,i){return '<div class="card"><div class="row"><b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b>'+(c.rank?'<span class="tag">'+(md[c.rank-1]||c.rank+'-o\'rin')+'</span>':'')+'</div>'+(c.link?'<input readonly value="'+esc(c.link)+'" onclick="this.select()"><div class="sub">Siz taklif qilganlar: <b>'+c.joins+'</b></div><div style="display:flex;gap:6px;margin-top:8px"><button class="btn s" onclick="rfcp('+i+')">📋 Nusxalash</button><button class="btn s" onclick="rfsh('+i+')">📤 Ulashish</button></div>':'<button class="btn" style="margin-top:8px" onclick="rfg('+c.id+')">🔗 Havolamni olish</button>')+(c.top.length?'<p style="margin:12px 0 4px"><b>🏆 Reyting</b></p>'+c.top.map(function(t,n){return '<div class="row sub" style="padding:3px 0"><span>'+(md[n]||(n+1)+'.')+' '+esc(t.name)+'</span><b>'+t.joins+'</b></div>'}).join(''):'')+'</div>'}).join(''):'<div class="card sub">Hozircha taklif tanlovi yo\'q.</div>';
if(j.mine.length)h+='<h1 style="font-size:18px">⚙️ Mening kanal/guruhlarim</h1><div class="card"><div class="sub" style="margin-bottom:4px">Yoqilsa, a\'zolar shaxsiy taklif havolasini oladi. Botga «Havola orqali taklif qilish» huquqi kerak.</div>'+j.mine.map(function(c){return '<div class="row" style="padding:10px 0;border-top:1px solid var(--ln);cursor:pointer" onclick="rft('+c.id+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.ref_on==1)+'<b>'+(c.ctype==='Kanal'?'📢 ':'👥 ')+esc(c.username)+'</b></div></div>'+(c.ref_on==1?'<div style="display:flex;gap:6px;margin:0 0 8px"><button class="btn s" onclick="rftop('+c.id+',this)">🏆 Reyting</button><button class="btn s" onclick="rfp('+c.id+')">📣 Reytingni yuborish</button></div><div id="rft'+c.id+'"></div>':'')}).join('')+'</div>';
$('rfb').innerHTML=h}
function rfg(id){api('ref_get',{id:id}).then(function(j){if(j.ok)rfl()})}
function rfcp(i){var t=RFD.open[i].link;var ok=function(){toast('Nusxalandi ✅')};try{navigator.clipboard.writeText(t).then(ok,function(){prompt('Nusxalang:',t)})}catch(e){prompt('Nusxalang:',t)}}
function rfsh(i){var u='https://t.me/share/url?url='+encodeURIComponent(RFD.open[i].link);try{tg.openTelegramLink(u)}catch(e){location.href=u}}
function rft(id){api('ref_toggle',{id:id}).then(function(j){if(j.ok){if(j.warn)toast('⚠️ '+j.warn);rfl()}})}
function rftop(id){api('ref_top',{id:id}).then(function(j){if(!j.ok)return;$('rft'+id).innerHTML='<div class="sub" style="margin-bottom:8px">Jami taklif orqali kirganlar: <b>'+j.total+'</b></div>'+(j.top.length?j.top.map(function(t,n){return '<div class="row sub" style="padding:3px 0"><span>'+(n+1)+'. '+esc(t.name)+(t.username?' @'+esc(t.username):'')+'</span><b>'+t.joins+'</b></div>'}).join(''):'<div class="sub">Hali hech kim yo\'q.</div>')})}
function rfp(id){cf('Reyting kanal/guruhga yuborilsinmi?',function(y){if(y)api('ref_post',{id:id}).then(function(j){if(j.ok)toast('Yuborildi ✅')})})}
function gda(){api('adm_guard').then(function(j){if(j.ok){GDA=j;av('gd')}})}
function ail(){api('adm_ai_cfg',{limit:$('ai_l').value}).then(function(j){if(j.ok){GDA.ai.limit=+$('ai_l').value;toast('Saqlandi ✅')}})}
function ait(){$('ai_r').textContent='Tekshirilmoqda...';api('adm_ai_test',{text:$('ai_t').value}).then(function(j){$('ai_r').textContent=j.ok?'Natija: '+({ok:'✅ oddiy xabar',spam:'📣 spam/reklama',porn:'🔞 behayo',refusal:'⚠️ model javob bermadi'}[j.verdict]||j.verdict)+' · bugun '+j.used+' so\'rov':'Xato: '+(j.error||'')})}
function gdw(){api('adm_guard_words',{words:$('gd_w').value}).then(function(j){if(j.ok){GDA.words=$('gd_w').value;toast('Saqlandi ✅')}})}
var DPC=null;
var BTC=null;
function btl(){$('btb').innerHTML='<div class="sk"></div><div class="sk"></div>';api('bt_my').then(function(j){if(j.ok){BTC=j;btr()}})}
function btdf(d){if(!d)return '';var p=d.split('-');return p[2]+'.'+p[1]+'.'+p[0]}
function btr(){var j=BTC,C=j.cfg,A=j.adm,h='<p class="sub" style="margin:-6px 2px 12px">Har Juma va bayram kunlari soat <b>'+esc(C.time)+'</b> da kanal va guruhlaringizga video tabrik (tagida matn bilan) yuboriladi.'+(C.on?'':' <b style="color:var(--r)">Hozir o\'chirilgan.</b>')+'</p>';
if(A)h+='<div class="card row" style="cursor:pointer" onclick="btf(\'\')"><div style="display:flex;align-items:center;gap:10px">'+ck(C.on)+'<div><b>Bayram tabriklari</b><div class="sub">'+C.n+' ta kanal/guruh · oxirgi: '+esc(C.last||'—')+'</div></div></div></div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Bayramlar</b></div>'+C.items.map(function(x){var nx=x.next?btdf(x.next):(x.fix===''?'sana kiritilmagan':'');return '<div class="card"><div class="row"><div style="display:flex;align-items:center;gap:10px;min-width:0">'+(A?'<span style="cursor:pointer;flex:none" onclick="btf(\''+x.k+'\')">'+ck(x.o)+'</span>':'')+'<div style="min-width:0"><b>'+(x.k==='juma'?'🕌 ':'🎉 ')+esc(x.name)+'</b><div class="sub">'+(x.fix==='fri'?'Har Juma · keyingisi: ':'')+esc(nx)+' · '+(x.v?'🎬 video':'📝 matn')+(x.o?'':' · ⛔ o\'chirilgan')+'</div></div></div><button class="btn s" style="flex:none" onclick="btt(\''+x.k+'\')">📩 Namuna</button></div>'
+(A?'<details style="margin-top:8px"><summary class="sub">✏️ Video va matnni o\'zgartirish</summary>'+(x.fix===''?'<p class="sub" style="margin:8px 0 4px">Bayram sanasi (har yili o\'zgaradi):</p><input id="btd_'+x.k+'" type="date" value="'+esc(x.d)+'">':'')+'<p class="sub" style="margin:8px 0 4px">Video havolasi (baza kanaldagi post):</p><input id="btv_'+x.k+'" placeholder="https://t.me/c/1234567890/45" value="'+esc(x.v)+'"><p class="sub" style="margin:8px 0 4px">Video tagidagi matn — {sana}, {yil}, {yosh}, {bayram}; qalin: &lt;b&gt;..&lt;/b&gt;</p><textarea id="btt_'+x.k+'" rows="7" maxlength="1024">'+esc(x.t)+'</textarea><button class="btn" onclick="bts()">💾 Saqlash</button></details>':'')+'</div>'}).join('');
if(A)h+='<div class="card"><b>⏰ Yuborish vaqti (Toshkent)</b><input id="bt_time" type="time" value="'+esc(C.time)+'"><button class="btn s" onclick="bts()">Saqlash</button><p class="sub" style="margin-top:6px">Video baza kanaldan olinadi: botni baza kanalga administrator qiling, videoni joylang va post havolasini (Копировать ссылку) kiriting. Bir kunga bayram va Juma to\'g\'ri kelsa — bayram tabrigi yuboriladi.</p></div>';
h+='<div class="row" style="margin:12px 2px 8px"><b>Kanallarim</b>'+(j.chats.length?'<button class="btn s" onclick="btall()">✅ Hammasi</button>':'')+'</div>'+(j.chats.length?j.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="btc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.bt_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('btb').innerHTML=h}
function btf(k){var C=BTC.cfg,on=k?!C.items.filter(function(x){return x.k===k})[0].o:!C.on;api('adm_bt_flag',{k:k,on:on?1:0}).then(function(j){if(j.ok){BTC.cfg=j.bt;btr()}})}
function bts(){var o={time:($('bt_time')||{}).value||BTC.cfg.time,items:{}};BTC.cfg.items.forEach(function(x){var v=$('btv_'+x.k),t=$('btt_'+x.k),d=$('btd_'+x.k);o.items[x.k]={v:v?v.value.trim():x.v,t:t?t.value:x.t,d:d?d.value:x.d}});api('adm_bt',o).then(function(j){if(j.ok){BTC.cfg=j.bt;btr();toast('Saqlandi ✅')}})}
function btt(k){toast('Yuborilmoqda...');api('bt_test',{k:k}).then(function(j){if(j.ok)toast('Sizga yuborildi ✅')})}
function btc(i){var c=BTC.chats[i],on=c.bt_on==1?0:1;api('bt_my_set',{id:c.id,on:on}).then(function(j){if(j.ok){c.bt_on=on;btr();toast(on?'Yoqildi ✅':'O\'chirildi')}})}
function btall(){api('bt_my_set',{id:0,on:1}).then(function(j){if(j.ok){BTC.chats.forEach(function(c){c.bt_on=1});btr();toast('Hamma kanal va guruhlarga yoqildi ✅')}})}
function dpl(){$('dpb').innerHTML='<div class="sk"></div>';api('dp_my').then(function(j){if(j.ok){DPC=j;dpr()}})}
function ck(on){return '<span class="sw'+(on?' on':'')+'"></span>'}
function dpr(){var j=DPC,D=j.cfg,h='';
if(D){h+='<div class="card row" style="cursor:pointer" onclick="dpf(0)"><div style="display:flex;align-items:center;gap:10px">'+ck(D.on)+'<div><b>Tongi xabar</b><div class="sub">har kuni '+esc(D.time)+' · '+D.n+' ta kanal</div></div></div><span class="sub">'+(D.on?'Yoqilgan':'O\'chirilgan')+'</span></div>'
+'<div class="row" style="margin:4px 2px 8px"><b>Hafta kunlari</b><button class="btn s" onclick="dpa()">✅ Hammasi</button></div>'
+D.days.map(function(x){return '<div class="card row" style="cursor:pointer" onclick="dpf('+x.d+')"><div style="display:flex;align-items:center;gap:10px">'+ck(x.o)+'<b>'+esc(x.name)+'</b></div><span class="sub">'+(x.v?'🎬 video':'📝 matn')+'</span></div>'}).join('')}
else if(!j.on)h+='<div class="card sub">Tongi xabar hozircha o\'chirilgan.</div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Kanallarim</b>'+(D?'':'<span class="sub">har kuni '+esc(j.time)+'</span>')+'</div>'+(j.chats.length?j.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="dpc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.dp_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('dpb').innerHTML=h}
function dpf(d,on){var D=DPC.cfg;if(on==null)on=d?!D.days[d-1].o:!D.on;return api('adm_dp_flag',{d:d,on:on}).then(function(j){if(j.ok){DPC.cfg=j.dp;DPC.on=j.dp.on;if(AD)AD.dp=j.dp;dpr()}return j})}
function dpa(){var p=Promise.resolve();DPC.cfg.days.forEach(function(x){if(!x.o)p=p.then(function(){return dpf(x.d,true)})});p.then(function(){toast('7 kun yoqildi ✅')})}
function hm2(m){return m<60?m+' daqiqa':Math.floor(m/60)+' soat'+(m%60?' '+m%60+' daq':'')}
function prh(){api('pr_home').then(function(j){var e=$('prh');if(!e)return;if(!j.ok){e.innerHTML='';return}var my='';try{my=localStorage.getItem('pr_reg')||''}catch(x){}
e.innerHTML='<div class="sc" style="cursor:pointer" onclick="go(\'pr\')"><div class="sh2">Namoz vaqtlari <span class="sub">· '+j.icon+' '+(j.tomorrow?'Ertaga ':'')+esc(j.name)+' · '+(j.started?'vaqti kirdi':hm2(j.mins)+' qoldi')+'</span><span class="chv2">›</span></div><div class="pgr">'+j.rows.map(function(x){return '<div'+(x.r===my?' class="me"':'')+'><span>'+esc(x.n)+'</span><b>'+esc(x.t)+'</b></div>'}).join('')+'</div></div>'})}
setInterval(function(){var p=$('p-pnm');if(p&&p.classList.contains('on'))prh()},120000);
function dpc(i){var c=DPC.chats[i],on=c.dp_on==1?0:1;api('dp_my_set',{id:c.id,on:on}).then(function(j){if(j.ok){c.dp_on=on;dpr();toast(on?'Yoqildi ✅':'O\'chirildi')}})}
function dpv(){var o={time:$('dp_time').value,days:{}};AD.dp.days.forEach(function(x){o.days[x.d]={v:$('dp_v'+x.d).value.trim(),t:$('dp_t'+x.d).value}});return o}
function dps(cb){api('adm_dp',dpv()).then(function(j){if(!j.ok)return;AD.dp=j.dp;if(cb)cb();else{toast('Saqlandi ✅');av('dp')}})}
function dpt(d){dps(function(){api('adm_dp_test',{d:d}).then(function(j){if(j.ok)toast('Sizga yuborildi ✅')})})}
/* ---- SAVOL-JAVOB: bitta sahifa — Sozlash (bo'limni bosqichma-bosqich tanlash), Reyting, Savollar bazasi (admin) ---- */
var SJ={c:0,d:null,tab:'set',cat:null,cc:null,m:'all',rc:0,bf:'',bs:'',bp:0,bl:null,ed:0,ai:null,ain:10,ail:2,tm:null};
function qzn(p){var n={k:SJ.d.tree},T=[];if(p){var a=p.split('/');for(var i=0;i<a.length;i++){if(!n.k||!n.k[a[i]])return null;n=n.k[a[i]];T.push(n.t)}}return {n:n,T:T}}
function qzc(p){var C=SJ.d.counts||{},s=0;for(var k in C)if(!p||k===p||k.indexOf(p+'/')===0)s+=+C[k];return s}
function qzlab(p){var x=qzn(p);return x&&x.T.length?x.T.join(' › '):'Barcha bo\'limlar aralash'}
function qzleaf(p){var x=qzn(p);return !!(p&&x&&!x.n.k)}
function sjl(c){if(c!=null)SJ.c=c;if(!SJ.d)$('sjb').innerHTML='<div class="sk"></div><div class="sk"></div>';api('qz_home',SJ.c?{chat:SJ.c}:{}).then(function(j){if(!j.ok)return;var my=j.groups.filter(function(g){return g.manage});if(my.length&&!my.some(function(g){return g.id===j.chat})){SJ.c=my[0].id;return sjl()}SJ.d=j;SJ.c=j.chat;if(SJ.cc!==j.chat){SJ.cc=j.chat;SJ.cat=j.cfg?j.cfg.cat:''}if(!my.length&&SJ.tab==='set')SJ.tab=j.admin?'bank':'rank';SJ.d.off=j.now-Math.floor(Date.now()/1000);sjr()})}
function sjtab(t){SJ.tab=t;sjr();if(t==='rank')sjrk(SJ.m);if(t==='bank'&&!SJ.bl)sjq(0)}
function sjr(){var j=SJ.d,my=j.groups.filter(function(g){return g.manage}),T=[];if(my.length)T.push(['set','⚙️ Sozlash']);T.push(['rank','🏆 Reyting']);if(j.admin)T.push(['bank','🗂 Savollar']);
var h='<div style="display:flex;gap:6px;margin:-4px 0 12px">'+T.map(function(t){return '<button class="btn'+(SJ.tab===t[0]?'':' s')+'" style="flex:1;padding:10px 4px;font-size:14px" onclick="sjtab(\''+t[0]+'\')">'+t[1]+'</button>'}).join('')+'</div>';
if(SJ.tab==='set')h+=my.length?sjset(my):'<div class="card sub">Savol-javob o\'zingiz qo\'shgan kanal va guruhlarda o\'ynaladi. Avval «Kanal qo\'shish» yoki «Guruh qo\'shish» orqali qo\'shing (bot administrator bo\'lsin).</div>';
if(SJ.tab==='rank')h+=sjrank();if(SJ.tab==='bank')h+='<div id="sjbank"></div>';
$('sjb').innerHTML=h;if(SJ.tab==='bank')sjbank();sjtick()}
/* bo'lim tanlash: yuqorida yo'l (bosib orqaga qaytiladi), pastda keyingi bosqich variantlari va savollar soni */
function pk(t,cur,leaf){var x=qzn(cur)||qzn(''),a=cur?cur.split('/'):[],n=x.n,h='';
if(a.length){h+='<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:10px"><button class="qzch" onclick="pks(\''+t+'\',\'\')">‹ Bo\'limlar</button>';for(var i=0;i<a.length;i++){var p=a.slice(0,i+1).join('/');h+='<span class="sub">›</span><button class="qzch'+(i===a.length-1?' on':'')+'" onclick="pks(\''+t+'\',\''+p+'\')">'+esc(qzn(p).n.t)+'</button>'}h+='</div>'}
if(n.k){var K=Object.keys(n.k);
if(!a.length)h+='<div style="display:grid;gap:8px">'+(leaf?'':'<div class="qzcd'+(cur===''?' on':'')+'" onclick="pks(\''+t+'\',\'\',1)"><b>🌐 Hamma bo\'limlar aralash</b><span>Barcha bo\'lim va fanlardan tasodifiy savollar</span><i>'+qzc('')+' ta savol</i></div>')+K.map(function(k){return '<div class="qzcd" onclick="pks(\''+t+'\',\''+k+'\')"><b>'+esc(n.k[k].t)+'</b><span>'+esc(n.k[k].d||'')+'</span><i>'+qzc(k)+' ta savol</i></div>'}).join('')+'</div>';
else h+='<p class="sub" style="margin:0 0 6px">'+(a.length===1&&a[0]==='maktab'?'Sinfni tanlang':'Keyingisini tanlang')+(leaf?':':' (yoki shu bo\'limning hammasi aralash qoladi):')+'</p><div style="display:grid;grid-template-columns:repeat('+(a[0]==='maktab'&&a.length===1?4:2)+',minmax(0,1fr));gap:6px">'+K.map(function(k){var p=cur+'/'+k,c=qzc(p);return '<button class="qzch2" onclick="pks(\''+t+'\',\''+p+'\')"><b>'+esc(n.k[k].t)+'</b><small>'+(c?c+' ta':'—')+'</small></button>'}).join('')+'</div>'}
if(cur!==''||!leaf){var c=qzc(cur);h+='<div class="qzsum">'+(leaf&&!qzleaf(cur)?'👆 Fanni tanlang':'✅ '+esc(qzlab(cur))+'<br><span class="sub">'+(c?c+' ta savol':'⚠️ Bu bo\'limda hali savol yo\'q')+'</span>')+'</div>'}
return h}
function pks(t,p){if(t==='set')SJ.cat=p;if(t==='bank'){SJ.bf=p;SJ.ed=0;SJ.ai=null;sjq(0);return}sjr()}
