else if(!m.on)h+='<div class="card sub">Kanallarga yuborish hozircha o\'chirilgan.</div>';
h+='<div class="row" style="margin:4px 2px 8px"><b>Kanallarimga yuborish</b><span class="sub">har kuni '+esc(m.cfg?m.cfg.time:m.time)+'</span></div>'+(m.chats.length?m.chats.map(function(c,i){return '<div class="card row" style="cursor:pointer" onclick="wxc('+i+')"><div style="display:flex;align-items:center;gap:10px">'+ck(c.wx_on==1)+'<b>'+esc(c.username)+'</b></div><span class="sub">'+esc(c.ctype)+'</span></div>'}).join(''):'<div class="card sub">Tasdiqlangan kanal yoki guruh yo\'q. Avval «Kanal qo\'shish» orqali qo\'shing.</div>');
$('wxb').innerHTML=h}
