function xbs(){toast('Saqlanmoqda...');api('adm_xbset',{on:XBK.list.filter(function(b){return b.on}).map(function(b){return b.id})}).then(function(j){if(!j.ok){toast(j.error||'Xato');return}XBK=j.xb;MBK=j.banks;XBR=null;av('manual');toast('Saqlandi ✅')})}
